WHERE id = 'cbc8ebd0-e767-41bc-a955-9b1ecd12f54c';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was ist das Ziel der Expansion?", "a": "Einen ersten asiatischen Markt erschließen; Japan wurde wegen Marktgröße und Zahlungskraft gewählt."}, {"q": "Wie läuft die Handwerkervermittlung in Japan heute?", "a": "Überwiegend über persönliche Empfehlungen und lokale Netzwerke; digitale Vermittler spielen kaum eine Rolle."}, {"q": "Gibt es lokale Wettbewerber?", "a": "Wenige kleine Anbieter ohne dominante Plattform — der Markt ist offen, aber kulturell anspruchsvoll."}, {"q": "Wie wichtig ist Lokalisierung?", "a": "Sehr: Sprache, Qualitätsnachweise und Vertrauen entscheiden; ein rein übersetztes EU-Produkt gilt intern als aussichtslos."}, {"q": "Welche Ressourcen stehen bereit?", "a": "Ein Landesbudget für drei Jahre und die Bereitschaft, mit lokalem Partner oder kleinem Zukauf zu starten."}]$J$::jsonb,
  reference_tree = $J$[{"id": "0f3f-n1", "title": "Markt & Kultur", "isPriority": true, "bulletPoints": [{"id": "0f3f-n1b1", "text": "Vertrauensmechanismen: Empfehlungen ersetzen"}, {"id": "0f3f-n1b2", "text": "Qualitäts-/Zertifizierungsstandards verstehen"}], "children": [{"id": "0f3f-n1c1", "title": "Zahlungs- & Servicegewohnheiten lokalisieren", "bulletPoints": [], "children": []}]}, {"id": "0f3f-n2", "title": "Wettbewerb & Kunden", "isPriority": false, "bulletPoints": [{"id": "0f3f-n2b1", "text": "Lücke: keine dominante Plattform"}, {"id": "0f3f-n2b2", "text": "Customer Journey je Segment kartieren"}], "children": []}, {"id": "0f3f-n3", "title": "Eintrittsmodell", "isPriority": false, "bulletPoints": [{"id": "0f3f-n3b1", "text": "Lokaler Partner oder kleiner Zukauf statt Greenfield"}, {"id": "0f3f-n3b2", "text": "Pilot in einer Metropolregion (z.B. Tokio)"}], "children": []}, {"id": "0f3f-n4", "title": "Aufbau der Angebotsseite", "isPriority": false, "bulletPoints": [{"id": "0f3f-n4b1", "text": "Handwerker-Akquise & Verifizierung"}, {"id": "0f3f-n4b2", "text": "Anreize für erste Bewertungen/Referenzen"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Vertrauens- und Kulturfrage schlägt Technik: Wer den Empfehlungs-Mechanismus digital nachbaut (Verifizierung, Zertifikate, Partner) und mit Pilot + lokalem Partner startet, trifft den Kern.$T$
WHERE id = '0f3f9bf6-b315-48a3-a463-e066776ba6b8';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Welches Segment soll adressiert werden?", "a": "Specialty-Coffee-Enthusiasten im Premium-Segment — preislich deutlich über Kapselmaschinen."}, {"q": "Wie groß ist das Premium-Segment?", "a": "Klein, aber mit dem Specialty-Trend zweistellig wachsend; verlässliche Zahlen fehlen und wären zu validieren."}, {"q": "Was unterscheidet das Produkt?", "a": "Siebträger-Qualität mit Automatik-Komfort und Langlebigkeit — in Europa klarer Testsieger."}, {"q": "Gibt es schon US-Vertrieb oder Service?", "a": "Nein, weder Händlernetz noch Serviceinfrastruktur; Spannungs-/Zertifizierungsanpassung (UL) steht ebenfalls aus."}, {"q": "Wie stark sind die Wettbewerber?", "a": "Breville, Jura und DeLonghi sind etabliert und besetzen die relevanten Retail-Regale."}]$J$::jsonb,
  reference_tree = $J$[{"id": "d419-n1", "title": "Segment & Positionierung", "isPriority": false, "bulletPoints": [{"id": "d419-n1b1", "text": "Zielgruppe Specialty-Enthusiasten schärfen"}, {"id": "d419-n1b2", "text": "Zahlungsbereitschaft & Segmentgröße validieren"}], "children": []}, {"id": "d419-n2", "title": "Kanalstrategie", "isPriority": true, "bulletPoints": [{"id": "d419-n2b1", "text": "D2C-Start (Marge, Datenhoheit) vs. Premium-Retail"}, {"id": "d419-n2b2", "text": "Amazon: Sichtbarkeit vs. Preisdruck"}], "children": [{"id": "d419-n2c1", "title": "Coffee-Community & Influencer als Einstiegskanal", "bulletPoints": [], "children": []}]}, {"id": "d419-n3", "title": "Operations & Service", "isPriority": false, "bulletPoints": [{"id": "d419-n3b1", "text": "UL-Zertifizierung & 120V-Anpassung"}, {"id": "d419-n3b2", "text": "Service-/Reparaturnetz von Tag 1"}], "children": []}, {"id": "d419-n4", "title": "Wettbewerb & Business Case", "isPriority": false, "bulletPoints": [{"id": "d419-n4b1", "text": "Differenzierung vs. Breville/Jura"}, {"id": "d419-n4b2", "text": "Eintrittsinvestition & Break-even-Pfad"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Nischen-Markteintritt: Kanalwahl ist die zentrale Entscheidung (D2C/Community-Start liegt nahe). Service-Infrastruktur wird oft vergessen — starke Antworten haben sie drin.$T$
WHERE id = 'd4198132-ab6c-423d-b3c2-d1bfa3884419';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was verkauft das Unternehmen genau?", "a": "Smart-Thermostate und Steuerungen für Wärmepumpen — in Deutschland über Installateure und Fachgroßhandel vertrieben."}, {"q": "Warum Frankreich?", "a": "Großer Markt mit strenger Effizienzregulierung (RE2020), die smarte Steuerungen begünstigt."}, {"q": "Was bedeutet der hohe Elektroheizungs-Anteil?", "a": "Das Produkt muss Elektro-Direktheizungen ansteuern können — dafür ist eine Produktanpassung nötig."}, {"q": "Wie stark sind Netatmo und Somfy?", "a": "Beide sind lokal etabliert mit starken Handelsbeziehungen; Netatmo gehört zu Legrand."}, {"q": "Welche Kanäle sind denkbar?", "a": "Installateure, Baumärkte (Leroy Merlin, Castorama) und Online — der Installateurskanal erfordert lokalen Support."}]$J$::jsonb,
  reference_tree = $J$[{"id": "da2f-n1", "title": "Marktspezifika & Produkt", "isPriority": true, "bulletPoints": [{"id": "da2f-n1b1", "text": "Elektroheizungs-Kompatibilität entwickeln"}, {"id": "da2f-n1b2", "text": "RE2020 als Verkaufsargument nutzen"}], "children": [{"id": "da2f-n1c1", "title": "Wärmepumpen-Welle als Timing-Chance", "bulletPoints": [], "children": []}]}, {"id": "da2f-n2", "title": "Wettbewerbspositionierung", "isPriority": false, "bulletPoints": [{"id": "da2f-n2b1", "text": "Differenzierung vs. Netatmo/Somfy (Effizienz-Expertise)"}, {"id": "da2f-n2b2", "text": "Preis-Leistungs-Positionierung"}], "children": []}, {"id": "da2f-n3", "title": "Vertrieb & Partner", "isPriority": false, "bulletPoints": [{"id": "da2f-n3b1", "text": "Installateurs-Netz mit Schulung/Support aufbauen"}, {"id": "da2f-n3b2", "text": "Baumarkt- und Online-Listung"}], "children": []}, {"id": "da2f-n4", "title": "Markteintritts-Ökonomie", "isPriority": false, "bulletPoints": [{"id": "da2f-n4b1", "text": "Lokalisierungskosten (Produkt, Support, Marketing)"}, {"id": "da2f-n4b2", "text": "Phasenplan & Erfolgskriterien"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Regulierung (RE2020) ist hier Rückenwind — gute Antworten machen sie zum Verkaufsargument statt zur Hürde und erkennen die Produktanpassung an Elektroheizung als Eintrittsvoraussetzung.$T$
WHERE id = 'da2f093f-0931-4ae4-899d-2396a81a4722';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was ist das Ziel der Zentralisierung?", "a": "Deutliche Kostensenkung und einheitliche Prozessqualität, ohne die Versorgung an den Standorten zu gefährden."}, {"q": "Wie groß sind die Redundanzen?", "a": "Jeder Standort leistet sich eigene IT-, Einkaufs- und HR-Teams; erste Schätzungen sehen 20-30% Doppelarbeit."}, {"q": "Wie heterogen ist die IT?", "a": "Sehr — teils unterschiedliche Systeme für dieselben Aufgaben, was jede Konsolidierung erschwert."}, {"q": "Wie stehen die Standorte dazu?", "a": "Skeptisch bis ablehnend; die Häuser fürchten Kontrollverlust und schlechteren Service."}, {"q": "Gibt es Vorgaben zum Personal?", "a": "Betriebsbedingte Kündigungen sollen vermieden werden — Abbau über Fluktuation und Umschulung."}]$J$::jsonb,
  reference_tree = $J$[{"id": "b61f-n1", "title": "Ist-Analyse & Baseline", "isPriority": false, "bulletPoints": [{"id": "b61f-n1b1", "text": "Prozesslandkarte & Kosten je Standort"}, {"id": "b61f-n1b2", "text": "Redundanzen quantifizieren, Best Practices finden"}], "children": []}, {"id": "b61f-n2", "title": "Zielmodell", "isPriority": true, "bulletPoints": [{"id": "b61f-n2b1", "text": "Shared-Service-Center-Design je Funktion (IT/Einkauf/HR)"}, {"id": "b61f-n2b2", "text": "Governance & Service-Level gegenüber Häusern"}], "children": [{"id": "b61f-n2c1", "title": "Standortwahl & Systemkonsolidierung", "bulletPoints": [], "children": []}]}, {"id": "b61f-n3", "title": "Umsetzung & Change", "isPriority": false, "bulletPoints": [{"id": "b61f-n3b1", "text": "Phasenplan: Quick Wins (Einkauf bündeln) zuerst"}, {"id": "b61f-n3b2", "text": "Mitarbeiter: Umschulung statt Kündigung, Kommunikation"}], "children": []}, {"id": "b61f-n4", "title": "Nutzen & Risiken", "isPriority": false, "bulletPoints": [{"id": "b61f-n4b1", "text": "Einsparziel & KPIs (Kosten, Servicequalität)"}, {"id": "b61f-n4b2", "text": "Risiko Servicequalität in Übergangsphase"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$SSC-Klassiker mit Stakeholder-Dimension: Neben dem Zielmodell zählen Change-Management und Service-Level-Zusagen an skeptische Standorte. Einkauf ist der typische Quick Win.$T$
WHERE id = 'b61fe531-88a1-4cc5-abbb-c09a86db9173';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie lange dauert die Bearbeitung heute?", "a": "Im Schnitt mehr als doppelt so lang wie der Branchendurchschnitt; Beschwerden und Anrufe binden zusätzlich Kapazität."}, {"q": "Welche Anträge sind am aufwendigsten?", "a": "Ein großer Teil sind eigentlich Standardfälle — komplex wird es durch fehlende Angaben und Systembrüche."}, {"q": "Wie hoch ist der Automatisierungsgrad?", "a": "Niedrig: Fast alles läuft über manuelle Prüfung in mehreren, schlecht integrierten Systemen."}, {"q": "Warum so viele Rückfragen?", "a": "Die Antragsformulare sind unklar, Belege fehlen häufig — jede Rückfrage kostet Tage."}, {"q": "Gibt es Budget für IT?", "a": "Ja, der Vorstand ist bereit zu investieren, erwartet aber auch kurzfristig sichtbare Verbesserungen."}]$J$::jsonb,
  reference_tree = $J$[{"id": "6358-n1", "title": "Prozessdiagnose", "isPriority": false, "bulletPoints": [{"id": "6358-n1b1", "text": "End-to-End-Prozess kartieren, Engpässe messen"}, {"id": "6358-n1b2", "text": "Fallarten clustern: Standard vs. komplex"}], "children": []}, {"id": "6358-n2", "title": "Automatisierung", "isPriority": true, "bulletPoints": [{"id": "6358-n2b1", "text": "Dunkelverarbeitung für Standardfälle"}, {"id": "6358-n2b2", "text": "KI-gestützte Beleg-/Dokumentprüfung"}], "children": [{"id": "6358-n2c1", "title": "Systembrüche schließen (Integration)", "bulletPoints": [], "children": []}]}, {"id": "6358-n3", "title": "Quick Wins", "isPriority": false, "bulletPoints": [{"id": "6358-n3b1", "text": "Formulare & Upload verbessern → weniger Rückfragen"}, {"id": "6358-n3b2", "text": "Prioritäts-Routing: einfache Fälle sofort"}], "children": []}, {"id": "6358-n4", "title": "Steuerung & Kunde", "isPriority": false, "bulletPoints": [{"id": "6358-n4b1", "text": "Durchlaufzeit-KPIs & Transparenz je Team"}, {"id": "6358-n4b2", "text": "Status-Tracking für Kunden (entlastet Hotline)"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Prozess-Case mit klarer Zweiteilung: Quick Wins (Rückfragen, Routing) + strukturelle Automatisierung (Dunkelverarbeitung). Wer Standard- von Komplexfällen trennt, hat den Kern.$T$
WHERE id = '63582979-9dc1-4f82-b27c-ad1a646d2e77';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie setzt sich der OEE-Rückstand zusammen?", "a": "Alle drei Faktoren liegen unter Ziel: Verfügbarkeit wegen ungeplanter Stillstände, Leistung wegen Taktzeitverlusten, Qualität wegen Ausschuss."}, {"q": "Was verursacht die Stillstände?", "a": "Ein Großteil geht auf wenige Anlagentypen zurück; Wartung ist überwiegend reaktiv."}, {"q": "Wie laufen die Umrüstungen?", "a": "Unstandardisiert — die Zeiten variieren stark zwischen Schichten und liegen weit über Zielwert."}, {"q": "Wie sind die Schichten aufgestellt?", "a": "Erfahrene Teams erreichen deutlich bessere Werte — Wissen ist nicht dokumentiert."}, {"q": "Welche Datenbasis existiert?", "a": "Maschinendaten werden erfasst, aber kaum systematisch ausgewertet."}]$J$::jsonb,
  reference_tree = $J$[{"id": "afd1-n1", "title": "Verfügbarkeit", "isPriority": true, "bulletPoints": [{"id": "afd1-n1b1", "text": "Stillstands-Pareto: wenige Anlagen zuerst"}, {"id": "afd1-n1b2", "text": "Predictive/präventive Wartung einführen"}], "children": [{"id": "afd1-n1c1", "title": "Ersatzteil-Management optimieren", "bulletPoints": [], "children": []}]}, {"id": "afd1-n2", "title": "Leistung", "isPriority": false, "bulletPoints": [{"id": "afd1-n2b1", "text": "Taktzeitverluste je Linie analysieren"}, {"id": "afd1-n2b2", "text": "SMED: Umrüstzeiten standardisieren"}], "children": []}, {"id": "afd1-n3", "title": "Qualität", "isPriority": false, "bulletPoints": [{"id": "afd1-n3b1", "text": "Ausschuss-Ursachen (Pareto) beheben"}, {"id": "afd1-n3b2", "text": "Qualitäts-Regelkreise an den Linien"}], "children": []}, {"id": "afd1-n4", "title": "Befähigung & Steuerung", "isPriority": false, "bulletPoints": [{"id": "afd1-n4b1", "text": "Best-Practice-Transfer zwischen Schichten"}, {"id": "afd1-n4b2", "text": "OEE-Daten transparent im Shopfloor-Management"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Lehrbuch-OEE-Zerlegung (Verfügbarkeit/Leistung/Qualität) plus Befähigungs-Ebene. Pareto-Denken (wenige Anlagen, wenige Ursachen) unterscheidet starke von generischen Antworten.$T$
WHERE id = 'afd1fb89-2882-4140-837d-771268689729';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie stark soll erhöht werden?", "a": "Der CFO denkt an 15-20% — final ist das nicht; die Analyse soll die Höhe mitbestimmen."}, {"q": "Warum jetzt?", "a": "Kosten sind gestiegen, und die Preise wurden seit vier Jahren nicht angepasst; der Vorstand sieht aufgestauten Spielraum."}, {"q": "Wie ist die Kundenbindung?", "a": "Churn ist niedrig, Wechselkosten sind hoch — die Software ist tief in HR-Prozesse integriert."}, {"q": "Was machen die Wettbewerber preislich?", "a": "Vergleichbare Anbieter liegen je nach Paket auf ähnlichem oder leicht höherem Niveau."}, {"q": "Gibt es Preisdifferenzierung?", "a": "Bisher ein Einheitspreis pro Mitarbeiter und Monat, kaum Paketierung."}]$J$::jsonb,
  reference_tree = $J$[{"id": "f673-n1", "title": "Zahlungsbereitschaft & Risiko", "isPriority": true, "bulletPoints": [{"id": "f673-n1b1", "text": "Wechselkosten & Churn-Risiko je Segment"}, {"id": "f673-n1b2", "text": "Wettbewerbspreise als Anker"}], "children": [{"id": "f673-n1c1", "title": "Preis-Absatz-Wirkung: Szenarien 10/15/20%", "bulletPoints": [], "children": []}]}, {"id": "f673-n2", "title": "Struktur statt nur Höhe", "isPriority": false, "bulletPoints": [{"id": "f673-n2b1", "text": "Paketierung (Basic/Pro/Enterprise)"}, {"id": "f673-n2b2", "text": "Value-Metrik prüfen: pro Mitarbeiter vs. Module"}], "children": []}, {"id": "f673-n3", "title": "Umsetzung Bestandskunden", "isPriority": false, "bulletPoints": [{"id": "f673-n3b1", "text": "Staffelung & Ankündigungsfristen"}, {"id": "f673-n3b2", "text": "Grandfathering für Schlüsselkunden"}], "children": []}, {"id": "f673-n4", "title": "Kommunikation & Flankierung", "isPriority": false, "bulletPoints": [{"id": "f673-n4b1", "text": "Wertargumentation (neue Features, Support)"}, {"id": "f673-n4b2", "text": "Vertriebs-Playbook für Einwände"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Preiserhöhung bei niedriger Churn = viel Spielraum, aber Umsetzung entscheidet: Segmentierung, Staffelung, Wert-Story. Wer nur 'erhöhen ja/nein' diskutiert, greift zu kurz.$T$
WHERE id = 'f6738f3e-329c-4611-8159-04ca5bd4523d';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was heißt kostenbasiert heute konkret?", "a": "Preis = Herstellkosten plus fixer Aufschlag — unabhängig davon, was das Produkt beim Kunden bewirkt."}, {"q": "Wie unterschiedlich ist der Kundennutzen?", "a": "Enorm: Dieselbe Chemikalie spart je nach Anwendung wenig oder sehr viel Prozesskosten beim Kunden."}, {"q": "Wovor hat der Vertrieb Angst?", "a": "Vor Kundenverlusten und schwierigen Gesprächen — er hat keine Werkzeuge, den Wert zu argumentieren."}, {"q": "Welche Daten existieren?", "a": "Kaum systematische Daten über Kundenanwendungen; das Wissen steckt in den Köpfen der Anwendungstechniker."}, {"q": "Wie schnell soll die Umstellung gehen?", "a": "Der Vorstand will erste Ergebnisse innerhalb eines Jahres, keine Big-Bang-Umstellung."}]$J$::jsonb,
  reference_tree = $J$[{"id": "0c5b-n1", "title": "Wertanalyse", "isPriority": true, "bulletPoints": [{"id": "0c5b-n1b1", "text": "Kundensegmentierung nach Anwendung & Nutzen"}, {"id": "0c5b-n1b2", "text": "Value-in-Use quantifizieren (eingesparte Prozesskosten)"}], "children": [{"id": "0c5b-n1c1", "title": "Referenz- vs. Differenzierungswert je Produkt", "bulletPoints": [], "children": []}]}, {"id": "0c5b-n2", "title": "Pilotierung", "isPriority": false, "bulletPoints": [{"id": "0c5b-n2b1", "text": "Pilot mit ausgewählten Produkten/Kunden"}, {"id": "0c5b-n2b2", "text": "Pricing-Tool & Datenbasis aufbauen"}], "children": []}, {"id": "0c5b-n3", "title": "Vertrieb & Change", "isPriority": false, "bulletPoints": [{"id": "0c5b-n3b1", "text": "Value-Selling-Training & Argumentationshilfen"}, {"id": "0c5b-n3b2", "text": "Incentives von Volumen auf Marge umstellen"}], "children": []}, {"id": "0c5b-n4", "title": "Risiko & Governance", "isPriority": false, "bulletPoints": [{"id": "0c5b-n4b1", "text": "Kundenverlust-Risiko je Segment steuern"}, {"id": "0c5b-n4b2", "text": "Eskalations-/Ausnahmeregeln definieren"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Value-Pricing-Transformation = Analytik + Change: Ohne Vertriebs-Enablement und Pilot scheitert es. Starke Antworten haben beide Seiten, nicht nur die Wertformel.$T$
WHERE id = '0c5bb759-0205-4aa1-8492-929a3e68ed5b';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was genau treibt die Kunden weg?", "a": "Unvorhersehbare Rechnungen: Kunden können ihre Monatskosten nicht prognostizieren und erleben böse Überraschungen."}, {"q": "Wie viele Preiskomponenten gibt es?", "a": "Mehrere Dutzend einzeln bepreiste Komponenten — historisch gewachsen."}, {"q": "Was schätzen Kunden am Anbieter?", "a": "Support und persönliche Betreuung werden deutlich besser bewertet als bei den Hyperscalern."}, {"q": "Wie preissensibel sind die Kunden?", "a": "Mittel — Planbarkeit ist ihnen wichtiger als der letzte Cent."}, {"q": "Gibt es Constraints für das neue Modell?", "a": "Bestandsumsatz soll nicht kannibalisiert werden; die Migration muss für Kunden attraktiv sein."}]$J$::jsonb,
  reference_tree = $J$[{"id": "e6b9-n1", "title": "Diagnose des Ist-Modells", "isPriority": false, "bulletPoints": [{"id": "e6b9-n1b1", "text": "Komponenten clustern, Hauptkostentreiber finden"}, {"id": "e6b9-n1b2", "text": "Vergleich mit AWS/Azure-Preislogik"}], "children": []}, {"id": "e6b9-n2", "title": "Neues Modell", "isPriority": true, "bulletPoints": [{"id": "e6b9-n2b1", "text": "Wenige Pakete (S/M/L/Enterprise) mit Planbarkeit"}, {"id": "e6b9-n2b2", "text": "Flatrate-Elemente + transparente Overage-Regeln"}], "children": [{"id": "e6b9-n2c1", "title": "Kostenprognose-Dashboard als Produktfeature", "bulletPoints": [], "children": []}]}, {"id": "e6b9-n3", "title": "Migration", "isPriority": false, "bulletPoints": [{"id": "e6b9-n3b1", "text": "Bestandskunden-Mapping auf neue Pakete"}, {"id": "e6b9-n3b2", "text": "Savings-Garantie/Preisschutz für Wechsler"}], "children": []}, {"id": "e6b9-n4", "title": "Positionierung", "isPriority": false, "bulletPoints": [{"id": "e6b9-n4b1", "text": "Planbarkeit + Support als Differenzierung vermarkten"}, {"id": "e6b9-n4b2", "text": "Churn- und Umsatz-Effekt tracken"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Das Problem ist Vorhersagbarkeit, nicht Preishöhe. Gute Antworten bauen das neue Modell um Planbarkeit (Pakete, Garantien, Transparenz) und regeln die Migration aktiv.$T$
WHERE id = 'e6b9842b-c89a-41a7-8a12-c5f1cb686bd0';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was motiviert den Wechsel?", "a": "Viele lizenzierte User nutzen die Software kaum — der Wert korreliert eher mit Projekten und Aktivität als mit Sitzanzahl."}, {"q": "Wo hängt der Umsatz heute?", "a": "Ein Großteil kommt von Enterprise-Kunden mit großen Sitzpaketen — genau dort wäre reines Usage-Pricing riskant."}, {"q": "Welche Nutzungsmetriken kommen infrage?", "a": "Aktive Projekte, aktive Nutzer pro Monat oder Aktionen — belastbare Daten liegen vor."}, {"q": "Was machen Wettbewerber?", "a": "Überwiegend Per-Seat; einzelne Herausforderer testen Hybrid-Modelle."}, {"q": "Wie schnell soll umgestellt werden?", "a": "Ohne Bestandskunden-Schock — eine Übergangsphase von etwa einem Jahr gilt als akzeptabel."}]$J$::jsonb,
  reference_tree = $J$[{"id": "003e-n1", "title": "Impact-Simulation", "isPriority": true, "bulletPoints": [{"id": "003e-n1b1", "text": "Umsatzeffekt je Kunde simulieren (Gewinner/Verlierer)"}, {"id": "003e-n1b2", "text": "Enterprise-Risiko separat quantifizieren"}], "children": [{"id": "003e-n1c1", "title": "Metrik-Wahl: aktive Nutzer vs. Projekte", "bulletPoints": [], "children": []}]}, {"id": "003e-n2", "title": "Zielmodell", "isPriority": false, "bulletPoints": [{"id": "003e-n2b1", "text": "Hybrid: Basisgebühr + Nutzungskomponente"}, {"id": "003e-n2b2", "text": "Mindest-Commitment für Planbarkeit"}], "children": []}, {"id": "003e-n3", "title": "Transition", "isPriority": false, "bulletPoints": [{"id": "003e-n3b1", "text": "Grandfathering & Wahlrecht für Bestandskunden"}, {"id": "003e-n3b2", "text": "Stufenweise Umstellung, klare Kommunikation"}], "children": []}, {"id": "003e-n4", "title": "Steuerung", "isPriority": false, "bulletPoints": [{"id": "003e-n4b1", "text": "Erfolgs-KPIs (NRR, Churn, Neukunden-Conversion)"}, {"id": "003e-n4b2", "text": "Rollback-Kriterien definieren"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Kern ist die Simulation: Wer gewinnt/verliert unter Usage-Pricing — besonders Enterprise. Hybrid-Modell + sanfte Transition ist die naheliegende, gut begründbare Empfehlung.$T$
WHERE id = '003e9c51-331a-4408-af4c-9f0e53dc660f';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie sehen die Unit Economics aus?", "a": "LTV/CAC liegt unter 2 und fällt; der CAC ist in zwei Jahren um mehr als die Hälfte gestiegen."}, {"q": "Warum steigt der CAC so stark?", "a": "Steigende Werbepreise in Social-Kanälen und zunehmende Konkurrenz durch andere D2C-Marken."}, {"q": "Wie schlimm sind die Retouren?", "a": "Probeschlaf-Retouren liegen deutlich über Plan; zurückgesandte Matratzen sind kaum wiederverwertbar."}, {"q": "Wie oft kaufen Kunden wieder?", "a": "Fast nie — eine Matratze hält Jahre; Zusatzsortiment (Kissen, Bettwaren) wird kaum mitverkauft."}, {"q": "Gibt es Offline-Präsenz?", "a": "Nein, reiner Online-Vertrieb."}]$J$::jsonb,
  reference_tree = $J$[{"id": "edc9-n1", "title": "Unit Economics reparieren", "isPriority": true, "bulletPoints": [{"id": "edc9-n1b1", "text": "CAC senken: Kanalmix, Brand vs. Performance"}, {"id": "edc9-n1b2", "text": "Retourenquote senken (Beratung, Erwartungsmanagement)"}], "children": [{"id": "edc9-n1c1", "title": "Retourenkosten in LTV ehrlich einrechnen", "bulletPoints": [], "children": []}]}, {"id": "edc9-n2", "title": "LTV erhöhen", "isPriority": false, "bulletPoints": [{"id": "edc9-n2b1", "text": "Warenkorb: Bundles & Zusatzsortiment"}, {"id": "edc9-n2b2", "text": "Wiederkauf-Kategorien (Bettwaren, Topper)"}], "children": []}, {"id": "edc9-n3", "title": "Wachstumstempo & Fixkosten", "isPriority": false, "bulletPoints": [{"id": "edc9-n3b1", "text": "Wachstum an profitablen Kohorten ausrichten"}, {"id": "edc9-n3b2", "text": "Fixkosten-/Overheaddisziplin"}], "children": []}, {"id": "edc9-n4", "title": "Pfad zur Profitabilität", "isPriority": false, "bulletPoints": [{"id": "edc9-n4b1", "text": "Szenarien: Break-even bei welchem CAC/Retourenniveau?"}, {"id": "edc9-n4b2", "text": "Meilensteine für Investoren definieren"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$D2C-Falle: Wachstum kaschiert kaputte Unit Economics. Starke Antworten arbeiten an CAC UND Retouren, statt nur mehr Marketing zu fordern, und liefern eine Break-even-Logik.$T$
WHERE id = 'edc985ce-d2a2-4f13-a11d-2bcee39dc3c3';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie unterschiedlich sind die Städte?", "a": "Sehr: Die besten Städte sind nahe Break-even, die schwächsten verlieren pro Fahrzeug ein Vielfaches davon."}, {"q": "Was treibt die Unterschiede?", "a": "Auslastung und Umsatz pro Fahrzeug — beeinflusst von Dichte, Zonenzuschnitt und lokaler Konkurrenz."}, {"q": "Warum liegen die Wartungskosten über Plan?", "a": "Höhere Schadenquoten und teure Ad-hoc-Reparaturen; Werkstattverträge sind nie neu verhandelt worden."}, {"q": "Gibt es Preisdifferenzierung?", "a": "Kaum — weitgehend einheitliche Minutenpreise über Städte und Tageszeiten."}, {"q": "Was erwartet der Investor konkret?", "a": "Einen glaubwürdigen Plan, der den Konzern innerhalb von zwei Jahren auf Break-even bringt — auch um den Preis von Marktaustritten."}]$J$::jsonb,
  reference_tree = $J$[{"id": "cbc5-n1", "title": "Transparenz je Stadt", "isPriority": true, "bulletPoints": [{"id": "cbc5-n1b1", "text": "P&L pro Stadt aufstellen"}, {"id": "cbc5-n1b2", "text": "Treiberbaum: Auslastung x Umsatz/Fahrzeug x Kosten"}], "children": [{"id": "cbc5-n1c1", "title": "Break-even-Auslastung je Stadt berechnen", "bulletPoints": [], "children": []}]}, {"id": "cbc5-n2", "title": "Portfolio-Entscheidungen", "isPriority": false, "bulletPoints": [{"id": "cbc5-n2b1", "text": "Schwache Städte: sanieren, schrumpfen oder Exit"}, {"id": "cbc5-n2b2", "text": "Zonen-/Flottengröße je Stadt optimieren"}], "children": []}, {"id": "cbc5-n3", "title": "Ertrag & Preis", "isPriority": false, "bulletPoints": [{"id": "cbc5-n3b1", "text": "Dynamisches Pricing (Zeit, Zone, Nachfrage)"}, {"id": "cbc5-n3b2", "text": "B2B-/Abo-Angebote für Grundauslastung"}], "children": []}, {"id": "cbc5-n4", "title": "Kostenhebel", "isPriority": false, "bulletPoints": [{"id": "cbc5-n4b1", "text": "Wartungs- & Versicherungsverträge neu verhandeln"}, {"id": "cbc5-n4b2", "text": "Schadenmanagement & Telematik"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Städte-P&L zuerst — ohne Transparenz keine Priorisierung. Gute Antworten trauen sich Portfolio-Entscheidungen (Exit schwacher Städte) und nennen Preis- plus Kostenhebel.$T$
WHERE id = 'cbc58191-2c8a-4ed7-ba32-fe9e734f44ab';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie groß ist der Großkunde inzwischen?", "a": "Er steht für rund ein Drittel des Umsatzes — mit weiter wachsendem Anteil."}, {"q": "Wie kam der Vertrag zustande?", "a": "Aggressiv verhandelt in einer Wachstumsphase; Preisgleitklauseln für Rohstoffe fehlen."}, {"q": "Welche versteckten Kosten verursacht er?", "a": "Sonderwünsche, Expresslieferungen, lange Zahlungsziele und dedizierte Kapazitäten, die nirgends bepreist sind."}, {"q": "Wie entwickeln sich die Rohstoffkosten?", "a": "Deutlich gestiegen und volatil — ohne Gleitklauseln trägt der Hersteller das Risiko allein."}, {"q": "Wie ist die Verhandlungsposition?", "a": "Der Kunde hat Alternativen, aber ein Wechsel wäre für ihn mit Umstellungskosten und Qualitätsrisiken verbunden."}]$J$::jsonb,
  reference_tree = $J$[{"id": "422a-n1", "title": "Kundenprofitabilität", "isPriority": true, "bulletPoints": [{"id": "422a-n1b1", "text": "P&L je Kunde/Segment: Bestands- vs. Neukunden"}, {"id": "422a-n1b2", "text": "Vollkosten des Großkunden inkl. versteckter Kosten"}], "children": [{"id": "422a-n1c1", "title": "Konzentrationrisiko (1/3 Umsatz) bewerten", "bulletPoints": [], "children": []}]}, {"id": "422a-n2", "title": "Vertrag & Preis", "isPriority": false, "bulletPoints": [{"id": "422a-n2b1", "text": "Neuverhandlung: Gleitklauseln, Service-Bepreisung"}, {"id": "422a-n2b2", "text": "Walk-away-Szenario durchrechnen"}], "children": []}, {"id": "422a-n3", "title": "Kosten & Effizienz", "isPriority": false, "bulletPoints": [{"id": "422a-n3b1", "text": "Rohstoff-Hedging/Einkaufsstrategie"}, {"id": "422a-n3b2", "text": "Komplexitätskosten (Sonderwünsche) reduzieren"}], "children": []}, {"id": "422a-n4", "title": "Portfolio-Strategie", "isPriority": false, "bulletPoints": [{"id": "422a-n4b1", "text": "Bestandskunden-Pricing pflegen"}, {"id": "422a-n4b2", "text": "Neukundenmix: Marge vor Volumen"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Wachstum ohne Marge: Der Großkunde ist Umsatzsegen und Margenfluch. Kern sind Kunden-P&L inkl. versteckter Kosten und eine vorbereitete Neuverhandlung mit Walk-away-Logik.$T$
WHERE id = '422aebe7-7a98-4c83-b716-c9e35a1b3d7d';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was ist das übergeordnete Ziel?", "a": "Zurück auf einen klaren Wachstumspfad für eine spätere Series D oder einen Exit — der Vorstand will EINE priorisierte Richtung."}, {"q": "Wie viel Kapital steht bereit?", "a": "Die Series C erlaubt eine große Wette oder zwei kleine — nicht alle drei Optionen parallel."}, {"q": "Was spricht für die eigene Versicherung?", "a": "Volle Wertschöpfung und Produktkontrolle; dagegen sprechen BaFin-Lizenz, Kapitalanforderungen und Konflikt mit den heutigen Versicherungspartnern."}, {"q": "Welche angrenzenden Finanzprodukte wären denkbar?", "a": "Baufinanzierung, Konsumkredite und Geldanlage — die Kundenbasis fragt das teilweise aktiv nach."}, {"q": "Wie realistisch ist internationale Expansion?", "a": "Der Broker-Markt ist national reguliert und fragmentiert; jedes Land bedeutet fast einen Neustart."}]$J$::jsonb,
  reference_tree = $J$[{"id": "5c31-n1", "title": "Bewertungsrahmen", "isPriority": true, "bulletPoints": [{"id": "5c31-n1b1", "text": "Kriterien: Marktpotenzial, Komplexität, Kapital, Fit"}, {"id": "5c31-n1b2", "text": "Synergien mit Kundenbasis & Tech-Stack"}], "children": [{"id": "5c31-n1c1", "title": "Risiko-Rendite-Matrix über die 3 Optionen", "bulletPoints": [], "children": []}]}, {"id": "5c31-n2", "title": "Option 1: Vertikal (eigene Versicherung)", "isPriority": false, "bulletPoints": [{"id": "5c31-n2b1", "text": "BaFin-Lizenz & Kapitalbindung"}, {"id": "5c31-n2b2", "text": "Kanalkonflikt mit Versicherungspartnern"}], "children": []}, {"id": "5c31-n3", "title": "Option 2: Horizontal (Finanzprodukte)", "isPriority": false, "bulletPoints": [{"id": "5c31-n3b1", "text": "Cross-Selling in Bestandskunden = Quick Win"}, {"id": "5c31-n3b2", "text": "Regulatorisch leichter (Vermittlermodell)"}], "children": []}, {"id": "5c31-n4", "title": "Option 3: International", "isPriority": false, "bulletPoints": [{"id": "5c31-n4b1", "text": "Länderregulierung = hoher Aufwand je Markt"}, {"id": "5c31-n4b2", "text": "Erst nach gewonnener Heimatbasis sinnvoll"}], "children": []}, {"id": "5c31-n5", "title": "Empfehlung & Sequenz", "isPriority": false, "bulletPoints": [{"id": "5c31-n5b1", "text": "Priorisierung mit Begründung"}, {"id": "5c31-n5b2", "text": "Meilensteine & Abbruchkriterien"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Optionsbewertungs-Case: Erwartet wird ein expliziter Bewertungsrahmen plus begründete Priorisierung (typisch: horizontal zuerst als Quick Win, vertikal/international später). Wer nur eine Option vertieft, verfehlt das Format.$T$
WHERE id = '5c317ca6-7a3c-4bd3-b078-8a6cf93103a9';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie ist die Ausgangslage im OTC-Geschäft?", "a": "Fast der gesamte Umsatz ist OTC; der Markt wächst kaum und der Preiskampf drückt die Bruttomarge Jahr für Jahr."}, {"q": "Wie groß ist die Rx-Chance?", "a": "Der Rx-Markt ist um ein Vielfaches größer als OTC; mit dem E-Rezept wird er erstmals digital adressierbar."}, {"q": "Was fehlt für Rx operativ?", "a": "Kühlkette, Same-Day-Fähigkeit in Ballungsräumen und pharmazeutische Beratungskapazität — alles investitionsintensiv."}, {"q": "Wie akut ist die Amazon-Gefahr?", "a": "Amazon Pharmacy ist in den USA aktiv; ein EU-Start gilt intern als Frage der Zeit, nicht des Ob."}, {"q": "Welche finanzielle Leitplanke gilt?", "a": "Die Rx-Investitionen müssen aus dem laufenden OTC-Cashflow finanzierbar sein — keine externe Kapitalerhöhung."}]$J$::jsonb,
  reference_tree = $J$[{"id": "bb5c-n1", "title": "OTC-Basis verteidigen", "isPriority": false, "bulletPoints": [{"id": "bb5c-n1b1", "text": "Kundenbindung: Abo & Loyalty"}, {"id": "bb5c-n1b2", "text": "Marge: Eigenmarken, Einkaufs- und Prozesseffizienz"}], "children": []}, {"id": "bb5c-n2", "title": "Rx-Expansion", "isPriority": true, "bulletPoints": [{"id": "bb5c-n2b1", "text": "Investitionsplan Kühlkette & Logistik"}, {"id": "bb5c-n2b2", "text": "Regulatorik & Beratungspflichten klären"}], "children": [{"id": "bb5c-n2c1", "title": "Pilotregion mit Same-Day als Testfeld", "bulletPoints": [], "children": []}]}, {"id": "bb5c-n3", "title": "Wettbewerbsstrategie", "isPriority": false, "bulletPoints": [{"id": "bb5c-n3b1", "text": "Differenzierung vs. Amazon: Beratung, Vertrauen"}, {"id": "bb5c-n3b2", "text": "First-Mover-Tempo vs. VC-Startups"}], "children": []}, {"id": "bb5c-n4", "title": "Finanzierung & Sequenz", "isPriority": false, "bulletPoints": [{"id": "bb5c-n4b1", "text": "Rx-Invest aus OTC-Cashflow staffeln"}, {"id": "bb5c-n4b2", "text": "Meilensteine & Stop-Kriterien"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Zwei-Fronten-Case: OTC-Cash-Basis sichern UND Rx-Fenster nutzen, unter Finanzierungsrestriktion. Starke Antworten sequenzieren (Pilot → Skalierung) und behandeln Amazon/Startups als getrennte Bedrohungen.$T$
WHERE id = 'bb5ca514-6964-4413-b063-1924ef26f11e';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie lange reicht die Runway?", "a": "Rund 20 Monate bei aktuellem Burn — die gewählte Richtung muss davor sichtbare Traktion zeigen."}, {"q": "Wie gut läuft das Kerngeschäft?", "a": "Product-Market-Fit in Deutschland ist belegt: gute Rückzahlungsquoten, wachsende Nachfrage, enge Bank-Partnerschaften."}, {"q": "Was würde die Geo-Expansion kosten?", "a": "Jedes EU-Land braucht eigene Lizenzierung und lokale Kreditrisikomodelle — pro Land ein mittlerer siebenstelliger Betrag bis zur Traktion."}, {"q": "Wie groß ist das Cross-Sell-Potenzial?", "a": "Bestandskunden fragen aktiv nach Factoring; die Vertriebsbeziehung existiert bereits."}, {"q": "Was spräche für die Banking-Plattform?", "a": "Langfristig höhere Margen und Unabhängigkeit — aber BaFin-Volllizenz, lange Vorlaufzeit und das höchste Kapitalrisiko."}]$J$::jsonb,
  reference_tree = $J$[{"id": "4a60-n1", "title": "Bewertungsrahmen", "isPriority": true, "bulletPoints": [{"id": "4a60-n1b1", "text": "Kriterien: Time-to-Revenue, Kapitalbedarf, Regulatorik, Fit"}, {"id": "4a60-n1b2", "text": "Runway 20 Monate als harte Nebenbedingung"}], "children": [{"id": "4a60-n1c1", "title": "Szenario je Option: Was ist in 12 Monaten beweisbar?", "bulletPoints": [], "children": []}]}, {"id": "4a60-n2", "title": "Produkt-Expansion (Factoring & Co.)", "isPriority": false, "bulletPoints": [{"id": "4a60-n2b1", "text": "Cross-Sell an Bestandskunden: schnellste Traktion"}, {"id": "4a60-n2b2", "text": "Geringste regulatorische Hürde"}], "children": []}, {"id": "4a60-n3", "title": "Geo-Expansion", "isPriority": false, "bulletPoints": [{"id": "4a60-n3b1", "text": "Lizenz & Risikomodell je Land"}, {"id": "4a60-n3b2", "text": "Pilotland-Logik (AT/NL) — aber teuer & langsam"}], "children": []}, {"id": "4a60-n4", "title": "Banking-Plattform", "isPriority": false, "bulletPoints": [{"id": "4a60-n4b1", "text": "Volllizenz: Dauer & Kapital sprengen die Runway"}, {"id": "4a60-n4b2", "text": "Später als Option offenhalten"}], "children": []}, {"id": "4a60-n5", "title": "Empfehlung", "isPriority": false, "bulletPoints": [{"id": "4a60-n5b1", "text": "Sequenz: Produkt zuerst, Geo nach Nachweis"}, {"id": "4a60-n5b2", "text": "Meilensteine für Investoren"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Trilemma unter Kapitalknappheit: Die Runway ist das entscheidende Bewertungskriterium. Erwartet wird eine klare, begründete Sequenz-Empfehlung (typisch: Produkt-Expansion zuerst) — nicht drei parallele Analysen.$T$
WHERE id = '4a60a56f-a4af-4d92-8798-18b9dd48a8a3';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was ist das strategische Motiv?", "a": "Die Schadensregulierung ist der größte Kostenblock des Konzerns; die KI-Lösung verspricht schnellere und günstigere Bearbeitung."}, {"q": "Wie belastbar ist der Algorithmus?", "a": "Bei B2B-Kunden nachweislich gute Ergebnisse — aber trainiert auf fremden Datenbeständen; die Übertragbarkeit auf das eigene Portfolio ist offen."}, {"q": "Wie hängt das Startup von Schlüsselpersonen ab?", "a": "Stark: Ein kleines ML-Team um die beiden Gründer trägt die gesamte Weiterentwicklung."}, {"q": "Kauft man nicht Konkurrenz zum eigenen Bestand?", "a": "Das InsurTech bedient heute auch zwei Wettbewerber des Konzerns — diese Verträge würden bei Übernahme wackeln."}, {"q": "Was wäre die Alternative zum Kauf?", "a": "Eine mehrjährige Exklusiv-Lizenz oder ein gemeinsames Pilotprojekt mit Kaufoption."}]$J$::jsonb,
  reference_tree = $J$[{"id": "6cd1-n1", "title": "Strategischer Fit & Nutzen", "isPriority": true, "bulletPoints": [{"id": "6cd1-n1b1", "text": "Einsparpotenzial in eigener Schadenregulierung quantifizieren"}, {"id": "6cd1-n1b2", "text": "Pilot auf eigenem Portfolio vor Signing"}], "children": [{"id": "6cd1-n1c1", "title": "Make/Buy/Partner-Vergleich", "bulletPoints": [], "children": []}]}, {"id": "6cd1-n2", "title": "Tech- & Team-Due-Diligence", "isPriority": false, "bulletPoints": [{"id": "6cd1-n2b1", "text": "Algorithmus-Qualität & Datenübertragbarkeit"}, {"id": "6cd1-n2b2", "text": "Retention des ML-Teams (Earn-out, Anreize)"}], "children": []}, {"id": "6cd1-n3", "title": "Kommerzielle Effekte", "isPriority": false, "bulletPoints": [{"id": "6cd1-n3b1", "text": "B2B-Kundenverlust (Wettbewerber) einpreisen"}, {"id": "6cd1-n3b2", "text": "Integrationsfähigkeit in konservative IT"}], "children": []}, {"id": "6cd1-n4", "title": "Deal & Risiken", "isPriority": false, "bulletPoints": [{"id": "6cd1-n4b1", "text": "Bewertung: Kostenersparnis-Case statt Umsatz-Multiple"}, {"id": "6cd1-n4b2", "text": "Kultur- und Integrationsrisiko Konzern vs. Startup"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Capability-M&A mit Besonderheit: Der Business Case ist Kostenersparnis im eigenen Haus, nicht das Umsatzwachstum des Targets. Pilot-vor-Kauf und Team-Retention sind die Schlüsselpunkte.$T$
WHERE id = '6cd182f6-982f-467d-bd79-c4de02caf1ba';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Warum überhaupt dieses Target?", "a": "Der Fonds sucht Distressed-Gelegenheiten mit Technologie-Substanz — das Karbon-Leichtbau-Portfolio gilt als unterbewertet."}, {"q": "Wie akut ist die Finanzlage?", "a": "EBITDA negativ, Covenants gerissen; ohne frisches Geld droht in etwa einem Jahr die Zahlungsunfähigkeit."}, {"q": "Wie werthaltig sind die Patente?", "a": "Das Leichtbau-Know-how ist auch für E-Mobilität und Luftfahrt relevant — die heutigen Kunden nutzen es kaum."}, {"q": "Wie flexibel sind die Werke?", "a": "Deutsche Werke sind unterausgelastet mit hohen Fixkosten; Osteuropa ist kostengünstig und ausbaufähig."}, {"q": "Was erwartet der Fonds als Rendite?", "a": "Distressed-typisch: mindestens 2,5-3x über fünf Jahre, mit klarem Downside-Schutz über den Liquidationswert."}]$J$::jsonb,
  reference_tree = $J$[{"id": "f030-n1", "title": "Investment-These", "isPriority": true, "bulletPoints": [{"id": "f030-n1b1", "text": "Tech-Assets vs. operative Risiken bewerten"}, {"id": "f030-n1b2", "text": "Downside: Liquidationswert als Boden"}], "children": [{"id": "f030-n1c1", "title": "Einstieg über Debt oder Equity strukturieren", "bulletPoints": [], "children": []}]}, {"id": "f030-n2", "title": "Turnaround-Plan", "isPriority": false, "bulletPoints": [{"id": "f030-n2b1", "text": "Bilanz: Schulden restrukturieren"}, {"id": "f030-n2b2", "text": "Operativ: Werkkonsolidierung, Verlagerung nach Osteuropa"}], "children": []}, {"id": "f030-n3", "title": "Wertschöpfung", "isPriority": false, "bulletPoints": [{"id": "f030-n3b1", "text": "Leichtbau-Pivot zu E-Mobility/Aerospace"}, {"id": "f030-n3b2", "text": "Kundenbasis diversifizieren (weg von wenigen OEMs)"}], "children": []}, {"id": "f030-n4", "title": "Risiken & Exit", "isPriority": false, "bulletPoints": [{"id": "f030-n4b1", "text": "OEM-Verträge & Kundenkonzentration"}, {"id": "f030-n4b2", "text": "Exit-Kanäle: Strategen vs. Secondary"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Distressed-PE: These = billiger Einstieg + Tech-Substanz + hartes Turnaround-Programm. Downside-Schutz (Liquidationswert) und Restrukturierung der Passivseite gehören zwingend in die Struktur.$T$
WHERE id = 'f030619d-bda2-4d04-8f14-e3831cf4f228';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was ist der Familie am wichtigsten?", "a": "Neben dem Preis: Fortbestand des Unternehmens, Standort- und Arbeitsplatzsicherheit sowie der Name — die Gewichtung ist aber offen."}, {"q": "Wie unterscheiden sich die Angebote preislich?", "a": "Der chinesische Konzern bietet spürbar mehr; PE und Stratege liegen nah beieinander darunter."}, {"q": "Was würde der Wettbewerber mit der Firma machen?", "a": "Synergien heben — mittelfristig drohen Standortkonsolidierung und Markenverschmelzung."}, {"q": "Welche Auflagen drohen beim China-Deal?", "a": "Eine Investitionsprüfung nach AWV ist wahrscheinlich; der Technologietransfer wäre politisch sensibel."}, {"q": "Was plant der PE-Fonds?", "a": "Buy-and-Build mit dem Management, Exit nach fünf bis sieben Jahren — Standortgarantien nur befristet."}]$J$::jsonb,
  reference_tree = $J$[{"id": "dc6b-n1", "title": "Entscheidungskriterien der Familie", "isPriority": true, "bulletPoints": [{"id": "dc6b-n1b1", "text": "Preis vs. Vermächtnis vs. Arbeitsplätze gewichten"}, {"id": "dc6b-n1b2", "text": "Kriterien-Scorecard über die 3 Optionen"}], "children": [{"id": "dc6b-n1c1", "title": "Zielbild: Was heißt 'Erfolg' in 10 Jahren?", "bulletPoints": [], "children": []}]}, {"id": "dc6b-n2", "title": "Käufer-Analyse", "isPriority": false, "bulletPoints": [{"id": "dc6b-n2b1", "text": "Stratege: Synergien vs. Standortrisiko"}, {"id": "dc6b-n2b2", "text": "PE: Weiterführung, aber Exit-Logik"}, {"id": "dc6b-n2b3", "text": "China: Preis + Technologietransfer + AWV-Risiko"}], "children": []}, {"id": "dc6b-n3", "title": "Deal-Gestaltung", "isPriority": false, "bulletPoints": [{"id": "dc6b-n3b1", "text": "Garantien: Standort, Beschäftigung, Marke"}, {"id": "dc6b-n3b2", "text": "Rückbeteiligung/Earn-out als Brücke"}], "children": []}, {"id": "dc6b-n4", "title": "Prozess & Stakeholder", "isPriority": false, "bulletPoints": [{"id": "dc6b-n4b1", "text": "Mitarbeiter & Betriebsrat einbinden"}, {"id": "dc6b-n4b2", "text": "Regulatorische Zeitachsen (AWV) einplanen"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Kein reiner Bewertungs-Case: Zuerst die Zieldimensionen der Familie strukturieren, dann Optionen dagegen scoren. Vertragsgestaltung (Garantien, Rückbeteiligung) als eigenes Lösungsfeld zeigt Seniorität.$T$
WHERE id = 'dc6bd971-1c55-4c13-83fd-2b5e265bfc37';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was fordern die Aktionäre konkret?", "a": "Fokussierung auf die profitablen Kernbereiche; ein aktivistischer Investor droht mit öffentlichen Forderungen."}, {"q": "Wie sieht das Verlustsegment aus?", "a": "Stabiler Umsatz, aber strukturell fallendes EBIT — im Konzern fehlt die Investitionsbereitschaft, es weiterzuentwickeln."}, {"q": "Gibt es Käuferinteresse?", "a": "Erste Sondierungen zeigen Interesse von PE-Fonds und einem ausländischen Strategen."}, {"q": "Wie teuer wäre das Akquisitionsziel?", "a": "Marktüblich wären zweistellige EBIT-Multiples — finanzierbar nur mit dem Verkaufserlös des Verlustsegments."}, {"q": "Gibt es Wechselwirkungen zwischen beiden Deals?", "a": "Ja: Timing und Erlös des Verkaufs bestimmen die Finanzierungskraft für den Zukauf; parallel laufende Prozesse überfordern die Organisation womöglich."}]$J$::jsonb,
  reference_tree = $J$[{"id": "e8ac-n1", "title": "Divestiture-Logik", "isPriority": false, "bulletPoints": [{"id": "e8ac-n1b1", "text": "Strategischer Fit & Turnaround-Alternativen"}, {"id": "e8ac-n1b2", "text": "Erlösspanne, Steuern, Kennzahleneffekt"}], "children": []}, {"id": "e8ac-n2", "title": "Akquisitions-Logik", "isPriority": false, "bulletPoints": [{"id": "e8ac-n2b1", "text": "Fit des Nischenführers: Technologie, Kunden"}, {"id": "e8ac-n2b2", "text": "Bewertung vs. Synergien quantifizieren"}], "children": []}, {"id": "e8ac-n3", "title": "Kapital & Sequenz", "isPriority": true, "bulletPoints": [{"id": "e8ac-n3b1", "text": "Verkaufserlös finanziert Zukauf: Reihenfolge klären"}, {"id": "e8ac-n3b2", "text": "Bilanz-/Rating-Wirkung beider Deals"}], "children": [{"id": "e8ac-n3c1", "title": "Parallel vs. sequenziell: Organisationskapazität", "bulletPoints": [], "children": []}]}, {"id": "e8ac-n4", "title": "Stakeholder & Umsetzung", "isPriority": false, "bulletPoints": [{"id": "e8ac-n4b1", "text": "Aktionärs-Story: Fokus-Narrativ"}, {"id": "e8ac-n4b2", "text": "Mitarbeiter/Betriebsrat im Verkaufssegment"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Doppel-Deal mit Abhängigkeit: Die Verzahnung (Erlös finanziert Zukauf, Sequenzfrage) ist der Kern — wer beide Transaktionen isoliert prüft, übersieht das Wesentliche.$T$
WHERE id = 'e8acf5a2-7ab8-448d-86b4-d3de50da3e09';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Warum D2C statt Handelspartner?", "a": "Volle Marken- und Preiskontrolle sowie Kundendaten; der Vorstand fürchtet Verwässerung über Dritte."}, {"q": "Wie bekannt ist die Marke in China?", "a": "In Europa stark, in China nur einer kleinen Kennerschicht vertraut — es braucht Markenaufbau von nahezu null."}, {"q": "Welche Kanäle dominieren im chinesischen Luxusmarkt?", "a": "Tmall Luxury Pavilion und WeChat-Ökosystem sind quasi Pflicht; eigene Flagship-Stores in Tier-1-Städten schaffen Glaubwürdigkeit."}, {"q": "Was ist mit Daigou und Grauimporten?", "a": "Ein relevanter Teil des China-Umsatzes läuft heute über Grauimporte aus Europa — Preisharmonisierung wäre nötig."}, {"q": "Welches Budget steht bereit?", "a": "Definiert, aber begrenzt: ein Flagship, digitale Kanäle und drei Jahre Markenaufbau sind gedeckt — kein flächiges Store-Netz."}]$J$::jsonb,
  reference_tree = $J$[{"id": "76f4-n1", "title": "Markt & Konsument", "isPriority": false, "bulletPoints": [{"id": "76f4-n1b1", "text": "Luxus-Konsumentensegmente & Kaufverhalten"}, {"id": "76f4-n1b2", "text": "Wettbewerbsbenchmark internationaler Marken"}], "children": []}, {"id": "76f4-n2", "title": "Kanal-Ökosystem", "isPriority": true, "bulletPoints": [{"id": "76f4-n2b1", "text": "Digital: Tmall Luxury, WeChat, Mini-Programs"}, {"id": "76f4-n2b2", "text": "Physisch: 1 Flagship Tier-1 als Anker"}], "children": [{"id": "76f4-n2c1", "title": "KOL-/Social-Strategie für Markenaufbau", "bulletPoints": [], "children": []}]}, {"id": "76f4-n3", "title": "Marke & Pricing", "isPriority": false, "bulletPoints": [{"id": "76f4-n3b1", "text": "Lokalisierte Markenerzählung ohne Identitätsverlust"}, {"id": "76f4-n3b2", "text": "Preisharmonisierung vs. Daigou"}], "children": []}, {"id": "76f4-n4", "title": "Setup & Risiken", "isPriority": false, "bulletPoints": [{"id": "76f4-n4b1", "text": "Eigene Einheit vs. TP-Partner (operative Ausführung)"}, {"id": "76f4-n4b2", "text": "Regulatorik, Datenlokalisierung, Geopolitik"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$China-Luxus hat eigene Spielregeln: Ohne Tmall/WeChat-Ökosystem und KOL-Aufbau funktioniert D2C nicht. Daigou/Preisharmonisierung zu erkennen unterscheidet starke Antworten.$T$
WHERE id = '76f4daa1-2b03-4c79-95cc-69f3275af74b';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was bietet der US-Partner konkret an?", "a": "Gespräche liefen über eine Vertriebspartnerschaft mit Produktintegration; auch ein Joint Venture wurde erwähnt."}, {"q": "Wie komplementär sind die Produkte?", "a": "Stark: Der Partner ist bei Kalkulation (Estimating) führend, das eigene Produkt bei Projektmanagement/BIM — Kundenüberlappung gering."}, {"q": "Wie unterscheidet sich der US-Markt?", "a": "Andere Baunormen und Vertragsmodelle, größere Projektvolumina, konsolidierte Top-Wettbewerber mit hohen Marketingbudgets."}, {"q": "Was würde ein eigener Markteintritt kosten?", "a": "Aufbau von Vertrieb, Support und Lokalisierung würde Jahre dauern und einen hohen zweistelligen Millionenbetrag binden."}, {"q": "Was ist das Risiko der Partnerschaft?", "a": "Abhängigkeit: Der Partner könnte nach ein paar Jahren selbst bauen oder von einem Wettbewerber gekauft werden."}]$J$::jsonb,
  reference_tree = $J$[{"id": "5373-n1", "title": "Make-or-Ally-Entscheidung", "isPriority": true, "bulletPoints": [{"id": "5373-n1b1", "text": "Eigenaufbau vs. Partnerschaft vs. Akquisition"}, {"id": "5373-n1b2", "text": "Time-to-Market & Kapitalbindung je Option"}], "children": [{"id": "5373-n1c1", "title": "Opportunitätskosten: DACH-Kerngeschäft nicht vernachlässigen", "bulletPoints": [], "children": []}]}, {"id": "5373-n2", "title": "Partnerschafts-Analyse", "isPriority": false, "bulletPoints": [{"id": "5373-n2b1", "text": "Produkt-Komplementarität & Kundenzugang"}, {"id": "5373-n2b2", "text": "Deal-Struktur: Reseller, JV, Cross-Licensing, Anteil"}], "children": []}, {"id": "5373-n3", "title": "Lokalisierung & Produkt", "isPriority": false, "bulletPoints": [{"id": "5373-n3b1", "text": "US-Baunormen & Workflows abbilden"}, {"id": "5373-n3b2", "text": "Support/Implementierung vor Ort"}], "children": []}, {"id": "5373-n4", "title": "Risiken & Schutz", "isPriority": false, "bulletPoints": [{"id": "5373-n4b1", "text": "Abhängigkeit vom Partner (Exklusivität, Laufzeit, IP)"}, {"id": "5373-n4b2", "text": "Exit-/Übernahmeklauseln vordenken"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Make-or-Ally unter Zeit- und Kapitaldruck: Die Partnerschaft ist attraktiv, braucht aber Vertragsschutz gegen Abhängigkeit. Starke Antworten strukturieren die Deal-Optionen explizit.$T$
WHERE id = '53738cb4-eeea-46d3-9774-7dfce082c618';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was ist das strategische Motiv?", "a": "Die europäischen Kernmärkte sind gesättigt; Afrika bietet Nutzer- und Umsatzwachstum, das zu Hause fehlt."}, {"q": "Welche Übernahmeziele stehen konkret an?", "a": "In beiden Ländern je ein mittelgroßer Betreiber mit landesweitem Netz, aber Investitionsstau."}, {"q": "Wie unterscheiden sich die Risiken?", "a": "Nigeria: Währungsvolatilität und politische Unsicherheit bei großem Markt. Kenia: stabiler, aber Safaricom dominiert mit hohem Marktanteil."}, {"q": "Wie wichtig ist Mobile Money?", "a": "Zentral — in beiden Märkten läuft ein Großteil des Zahlungsverkehrs mobil; M-Pesa zeigt das Ertragspotenzial."}, {"q": "Welche Fähigkeiten fehlen dem Konzern?", "a": "Keinerlei Afrika-Erfahrung und kein Mobile-Money-Betrieb — beides müsste mit dem Target einkauft oder aufgebaut werden."}]$J$::jsonb,
  reference_tree = $J$[{"id": "7773-n1", "title": "Ländervergleich", "isPriority": true, "bulletPoints": [{"id": "7773-n1b1", "text": "Marktgröße & Wachstum vs. Wettbewerbsposition"}, {"id": "7773-n1b2", "text": "Risikoprofil: Währung, Politik, Regulierung"}], "children": [{"id": "7773-n1c1", "title": "Szenario-Bewertung beider Targets (NPV + Risiko)", "bulletPoints": [], "children": []}]}, {"id": "7773-n2", "title": "Mobile Money als 2. Standbein", "isPriority": false, "bulletPoints": [{"id": "7773-n2b1", "text": "Ertragsmodell & Banking-Regulatorik"}, {"id": "7773-n2b2", "text": "Fähigkeitsaufbau: Team aus dem Target halten"}], "children": []}, {"id": "7773-n3", "title": "Eintritts- & Betriebsmodell", "isPriority": false, "bulletPoints": [{"id": "7773-n3b1", "text": "Mehrheitsübernahme vs. Beteiligung mit lokalem Partner"}, {"id": "7773-n3b2", "text": "Investitionsplan Netz (Capex-Staffelung)"}], "children": []}, {"id": "7773-n4", "title": "Risikomanagement", "isPriority": false, "bulletPoints": [{"id": "7773-n4b1", "text": "Währungs-Hedging & Gewinnrepatriierung"}, {"id": "7773-n4b2", "text": "Exit-Optionen bei Eskalation"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Länder-Vergleichslogik mit expliziten Kriterien ist Pflicht; Mobile Money gehört als eigenes Wertfeld hinein. Wer Nigeria/Kenia nur beschreibt statt zu scoren, bleibt unter dem Anspruch.$T$
WHERE id = '77730723-7874-4939-ae2b-f46180eb0d1b';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Welches Segment ist realistisch?", "a": "Der Enterprise-Markt ist von drei Platzhirschen besetzt — realistisch ist der fragmentierte Mid-Market."}, {"q": "Wie gut passt das Produkt zum US-Markt?", "a": "Kernfunktionen ja, aber US-spezifische Regulatorik (SEC, HIPAA) ist nur teilweise abgedeckt — Lokalisierungsaufwand ist real."}, {"q": "Was genau bietet das Akquisitionsziel?", "a": "Rund 20 Mio USD ARR im Mid-Market, profitabel, loyaler Kundenstamm — aber technologisch veraltet und mit begrenztem Produkt-Fit."}, {"q": "Was würde der Eigenaufbau dauern?", "a": "Intern geschätzt drei bis vier Jahre bis zu relevantem ARR — mit hohem Risiko, ohne lokale Marke nicht durchzudringen."}, {"q": "Wie ist die Preisvorstellung des Targets?", "a": "Marktübliche ARR-Multiples für profitables SaaS — verhandelbar, aber kein Schnäppchen."}]$J$::jsonb,
  reference_tree = $J$[{"id": "1d85-n1", "title": "Markt & Zielsegment", "isPriority": false, "bulletPoints": [{"id": "1d85-n1b1", "text": "Enterprise vs. Mid-Market: Wettbewerbsrealität"}, {"id": "1d85-n1b2", "text": "Regulatorische Produktlücken (SEC, HIPAA)"}], "children": []}, {"id": "1d85-n2", "title": "Build-Szenario", "isPriority": false, "bulletPoints": [{"id": "1d85-n2b1", "text": "Ramp-up: Vertrieb, Marke, 3-4 Jahre Zeitverlust"}, {"id": "1d85-n2b2", "text": "Kapitalbedarf & Durchdringungsrisiko"}], "children": []}, {"id": "1d85-n3", "title": "Buy-Szenario", "isPriority": true, "bulletPoints": [{"id": "1d85-n3b1", "text": "Sofortiger Marktzugang: Kunden, Team, Referenzen"}, {"id": "1d85-n3b2", "text": "Produkt-Fit-Lücke: Migrations-/Integrationsplan"}], "children": [{"id": "1d85-n3c1", "title": "Preis vs. Alternative Build quantifizieren", "bulletPoints": [], "children": []}]}, {"id": "1d85-n4", "title": "Empfehlung & Umsetzung", "isPriority": false, "bulletPoints": [{"id": "1d85-n4b1", "text": "Entscheidungslogik: Zeit vs. Kontrolle vs. Kosten"}, {"id": "1d85-n4b2", "text": "100-Tage-Plan für die gewählte Route"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Build vs. Buy sauber gegenüberstellen (Zeit, Kapital, Risiko) und eine begründete Empfehlung geben — inkl. des unbequemen Punkts, dass das Target technisch altert und Migration kostet.$T$
WHERE id = '1d85c998-7bac-49d0-8616-4c2cecc9082f';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Gibt es einen Zielkonflikt zwischen CO2 und Kosten?", "a": "Teilweise — aber viele Maßnahmen (Netzwerkverdichtung, Energieeffizienz, weniger Luftfracht) senken beides gleichzeitig; genau diese sollen zuerst gefunden werden."}, {"q": "Wie sieht das heutige Netzwerk aus?", "a": "Historisch gewachsen: viele kleine Werke und Läger mit Redundanzen, Kosten deutlich über Branchenbenchmark."}, {"q": "Was fordern die Handelskunden konkret?", "a": "Produktgenaue CO2-Daten (Product Carbon Footprint) innerhalb der nächsten zwei Jahre — sonst drohen Auslistungsgespräche."}, {"q": "Wo entstehen die meisten Emissionen?", "a": "Der Großteil ist Scope 3: Rohstoffe aus Schwellenländern und Transporte; eigene Werke (Scope 1+2) sind der kleinere Teil."}, {"q": "Welche Zielmarken gelten?", "a": "Supply-Chain-Kosten Richtung Branchenbenchmark und ein glaubwürdiger Klimaneutralitätspfad — beides mit messbaren Etappen."}]$J$::jsonb,
  reference_tree = $J$[{"id": "c930-n1", "title": "Netzwerk-Redesign", "isPriority": true, "bulletPoints": [{"id": "c930-n1b1", "text": "Footprint-Analyse: Werke/Läger konsolidieren"}, {"id": "c930-n1b2", "text": "Nearshoring & Transportmodi (weniger Luftfracht)"}], "children": [{"id": "c930-n1c1", "title": "Doppel-Effekt-Maßnahmen (Kosten UND CO2) priorisieren", "bulletPoints": [], "children": []}]}, {"id": "c930-n2", "title": "Dekarbonisierung", "isPriority": false, "bulletPoints": [{"id": "c930-n2b1", "text": "Scope 1+2: Energie, Elektrifizierung"}, {"id": "c930-n2b2", "text": "Scope 3: Rohstoff-Hotspots & Lieferantenprogramm"}], "children": []}, {"id": "c930-n3", "title": "Transparenz & Daten", "isPriority": false, "bulletPoints": [{"id": "c930-n3b1", "text": "PCF-Tracking je Produkt aufbauen"}, {"id": "c930-n3b2", "text": "Kundenreporting für Handelspartner"}], "children": []}, {"id": "c930-n4", "title": "Umsetzung & Steuerung", "isPriority": false, "bulletPoints": [{"id": "c930-n4b1", "text": "Roadmap mit Kosten-/CO2-Zielen je Welle"}, {"id": "c930-n4b2", "text": "Governance: wer trägt die Ziele?"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Der Trick ist die Doppel-Effekt-Priorisierung: Erst Maßnahmen, die Kosten UND CO2 senken. Scope-3-Dominanz und die PCF-Kundenanforderung müssen vorkommen.$T$
WHERE id = 'c9306737-a95b-401b-ac06-bdae7f920505';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wo geht die meiste Ware verloren?", "a": "An den Übergabepunkten (Rampe, Umschlag) und auf langen Touren ohne Sensorik — belastbare Daten gibt es nur für die IoT-Teilflotte."}, {"q": "Wie ist die Flotte aufgestellt?", "a": "Gemischt: eigene LKW und viele Subunternehmer mit heterogenem Standard; zentrale Tourenplanung fehlt."}, {"q": "Wie groß ist der Kostenrückstand?", "a": "Die Logistikkosten liegen spürbar über Benchmark — Haupttreiber sind schlechte Auslastung und ineffiziente Routen."}, {"q": "Welche Investitionen sind denkbar?", "a": "IoT-Vollausstattung und eine Transportplanungssoftware sind budgetierbar, ein Netzwerk-Umbau nur mit Business Case."}, {"q": "Gibt es Service-Vorgaben?", "a": "Lieferfähigkeit und Frische dürfen nicht leiden — Händler messen die Regalverfügbarkeit."}]$J$::jsonb,
  reference_tree = $J$[{"id": "b4f0-n1", "title": "Netzwerk & Touren", "isPriority": true, "bulletPoints": [{"id": "b4f0-n1b1", "text": "Verteilzentren & Routen optimieren (Hub vs. direkt)"}, {"id": "b4f0-n1b2", "text": "Auslastung der Flotte steigern"}], "children": [{"id": "b4f0-n1c1", "title": "Zentrale Transportplanung einführen", "bulletPoints": [], "children": []}]}, {"id": "b4f0-n2", "title": "Kühlketten-Qualität", "isPriority": false, "bulletPoints": [{"id": "b4f0-n2b1", "text": "IoT-Sensorik auf 100% der Flotte"}, {"id": "b4f0-n2b2", "text": "Kritische Übergabepunkte absichern"}], "children": []}, {"id": "b4f0-n3", "title": "Partner & Verträge", "isPriority": false, "bulletPoints": [{"id": "b4f0-n3b1", "text": "Subunternehmer-Standards & Anreize (Schwund-KPIs)"}, {"id": "b4f0-n3b2", "text": "Make-or-Buy je Region prüfen"}], "children": []}, {"id": "b4f0-n4", "title": "Steuerung", "isPriority": false, "bulletPoints": [{"id": "b4f0-n4b1", "text": "Schwund- & Kosten-KPIs in Echtzeit"}, {"id": "b4f0-n4b2", "text": "Business Case: Einsparung vs. Investition"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Zwei Ziele, ein Netzwerk: Kosten (Planung, Auslastung) und Schwund (Sensorik, Übergabepunkte) brauchen je eigene Hebel. Die Subunternehmer-Steuerung wird oft vergessen.$T$
WHERE id = 'b4f00bd3-dc6c-4b99-9c9c-d501a7c698db';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie groß ist die Investition?", "a": "Ein hoher einstelliger Milliardenbetrag über mehrere Jahre — die größte Einzelentscheidung der Firmengeschichte."}, {"q": "Wie stark wiegt die EU-Förderung?", "a": "Sie würde einen zweistelligen Prozentsatz der Investition abdecken, ist aber an Auflagen und Clawback-Klauseln gebunden."}, {"q": "Welche Rolle spielt Geopolitik?", "a": "Zentral: Kunden und Regierungen drängen auf Diversifizierung weg von Asien-Konzentration; das Taiwan-Risiko treibt die Debatte."}, {"q": "Wie unterscheiden sich die Betriebskosten?", "a": "Südostasien ist bei Energie, Personal und Bau klar günstiger; Europa punktet mit Fördermitteln, Kundennähe und Rechtssicherheit."}, {"q": "Für welche Kunden ist der Standort relevant?", "a": "Europäische Automobil- und Industriekunden fordern zunehmend regionale Fertigung — teils vertraglich."}]$J$::jsonb,
  reference_tree = $J$[{"id": "72d6-n1", "title": "Wirtschaftlichkeit (TCO/NPV)", "isPriority": true, "bulletPoints": [{"id": "72d6-n1b1", "text": "Capex mit/ohne Förderung, Opex-Differenzen"}, {"id": "72d6-n1b2", "text": "20-Jahres-NPV & Sensitivitäten (Energiepreis, Auslastung)"}], "children": [{"id": "72d6-n1c1", "title": "Förderauflagen & Clawback-Risiken einpreisen", "bulletPoints": [], "children": []}]}, {"id": "72d6-n2", "title": "Strategische Faktoren", "isPriority": false, "bulletPoints": [{"id": "72d6-n2b1", "text": "Geopolitische Diversifizierung (Taiwan-Risiko)"}, {"id": "72d6-n2b2", "text": "Kundennähe & regionale Fertigungszusagen"}], "children": []}, {"id": "72d6-n3", "title": "Umsetzbarkeit", "isPriority": false, "bulletPoints": [{"id": "72d6-n3b1", "text": "Bauzeit, Genehmigungen, Fachkräfte je Standort"}, {"id": "72d6-n3b2", "text": "Technologie-Node & Fab-Ökosystem"}], "children": []}, {"id": "72d6-n4", "title": "Entscheidung & Absicherung", "isPriority": false, "bulletPoints": [{"id": "72d6-n4b1", "text": "Szenario-Matrix: Kosten vs. Risiko vs. Strategie"}, {"id": "72d6-n4b2", "text": "Phasierung/Modularität als Hedge"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Standortentscheidung = harte TCO-Rechnung PLUS strategische Dimension (Geopolitik, Kundennähe) — beide Ebenen müssen getrennt sichtbar sein. Sensitivitäten zeigen Seniorität.$T$
WHERE id = '72d68811-3822-49df-8aec-5d02ff66c1e1';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie viele Patienten gibt es?", "a": "Eine niedrige vierstellige Zahl in Deutschland — klassischer Orphan-Drug-Bereich."}, {"q": "Wie stark ist die Evidenz?", "a": "Klinisch sehr überzeugend: deutliche Verbesserung gegenüber best-supportive-care, kaum Nebenwirkungen."}, {"q": "Wie läuft die Preisbildung in Deutschland?", "a": "Erstes Jahr freie Preissetzung, parallel AMNOG-Nutzenbewertung, danach Erstattungsbetrags-Verhandlung mit dem GKV-Spitzenverband."}, {"q": "Welche Vergleichstherapie gilt?", "a": "Keine direkte — bewertet wird gegen best-supportive-care, was die Zusatznutzen-Argumentation stärkt."}, {"q": "Welche Erwartungen hat das Unternehmen?", "a": "F&E-Kosten amortisieren und einen Referenzpreis setzen, der internationale Preisverhandlungen nicht beschädigt."}]$J$::jsonb,
  reference_tree = $J$[{"id": "0532-n1", "title": "Wertbasis des Preises", "isPriority": true, "bulletPoints": [{"id": "0532-n1b1", "text": "Klinischer Zusatznutzen & Lebensqualität"}, {"id": "0532-n1b2", "text": "Kosten vermiedener Behandlungen/Hospitalisierung"}], "children": [{"id": "0532-n1c1", "title": "Health-Economics-Dossier (QALY-Argumentation)", "bulletPoints": [], "children": []}]}, {"id": "0532-n2", "title": "Regulatorischer Pfad", "isPriority": false, "bulletPoints": [{"id": "0532-n2b1", "text": "Jahr-1-Preis strategisch setzen (AMNOG)"}, {"id": "0532-n2b2", "text": "Erstattungsverhandlung & Schiedsstellen-Szenario"}], "children": []}, {"id": "0532-n3", "title": "Zugang & Ethik", "isPriority": false, "bulletPoints": [{"id": "0532-n3b1", "text": "Managed-Entry: Pay-for-Performance, Ratenmodelle"}, {"id": "0532-n3b2", "text": "Härtefallprogramme, öffentliche Wahrnehmung"}], "children": []}, {"id": "0532-n4", "title": "Internationale Wirkung", "isPriority": false, "bulletPoints": [{"id": "0532-n4b1", "text": "Referenzpreis-Effekte auf andere Länder"}, {"id": "0532-n4b2", "text": "Launch-Sequenz international"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Pharma-Pricing dreht sich um Nutzenbewertung + Verhandlungspfad (AMNOG), nicht um Kosten-plus. Managed-Entry-Modelle und internationale Referenzeffekte adeln die Antwort.$T$
WHERE id = '05325d4d-ccf6-4963-a497-25ae10f0d313';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie wird heute bepreist?", "a": "Halbjährlich fixierte Preislisten je Haus auf Basis historischer Belegung — Marktveränderungen fließen kaum ein."}, {"q": "Wie groß ist der Rückstand?", "a": "RevPAR liegt spürbar unter Benchmark; Wettbewerber mit KI-Pricing schöpfen Nachfragespitzen deutlich besser ab."}, {"q": "Woher kommen die Beschwerden über Intransparenz?", "a": "Stammgäste sehen stark schwankende Preise für dasselbe Zimmer und fühlen sich unfair behandelt — vor allem im Luxussegment."}, {"q": "Welche Daten sind verfügbar?", "a": "Buchungshistorie ja; externe Signale (Events, Flüge, Wetter) werden bisher gar nicht genutzt."}, {"q": "Gibt es Vorgaben je Marke?", "a": "Der Vorstand will markenspezifische Regeln — was im Budget-Segment funktioniert, darf die Luxusmarke nicht beschädigen."}]$J$::jsonb,
  reference_tree = $J$[{"id": "f3d3-n1", "title": "Segmentierte Pricing-Architektur", "isPriority": true, "bulletPoints": [{"id": "f3d3-n1b1", "text": "Budget: aggressiv dynamisch"}, {"id": "f3d3-n1b2", "text": "Business: nachfragebasiert mit Korridoren"}, {"id": "f3d3-n1b3", "text": "Luxury: wertorientiert, enge Leitplanken"}], "children": []}, {"id": "f3d3-n2", "title": "Technologie & Daten", "isPriority": false, "bulletPoints": [{"id": "f3d3-n2b1", "text": "Pricing-Engine + externe Signale (Events, Flüge)"}, {"id": "f3d3-n2b2", "text": "A/B-Tests & Forecast-Qualität"}], "children": []}, {"id": "f3d3-n3", "title": "Marken- & Kundenschutz", "isPriority": false, "bulletPoints": [{"id": "f3d3-n3b1", "text": "Preiskorridore je Marke"}, {"id": "f3d3-n3b2", "text": "Transparenz & Loyalty-Vorteile für Stammgäste"}], "children": []}, {"id": "f3d3-n4", "title": "Rollout & Steuerung", "isPriority": false, "bulletPoints": [{"id": "f3d3-n4b1", "text": "Pilothäuser je Marke, dann Skalierung"}, {"id": "f3d3-n4b2", "text": "RevPAR-/NPS-Monitoring als Doppelziel"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Dynamic Pricing mit Markenschutz: Die differenzierte Logik je Marke (inkl. Leitplanken im Luxus) ist der Kern. RevPAR UND Kundenwahrnehmung als Doppelmetrik zeigt Reife.$T$
WHERE id = 'f3d33a16-3c52-45b0-a46d-d3beef41bc53';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Was verspricht sich der Vorstand vom Abo?", "a": "Planbare wiederkehrende Erlöse, Kundenbindung und Datenvorteile — plus PR-Effekt als Innovationsführer."}, {"q": "Wie voll sind die Flieger heute?", "a": "Load Factor um 93% — freie Sitze sind knapp, echte Zusatzkapazität gibt es kaum."}, {"q": "Welche Abo-Varianten sind angedacht?", "a": "Inlands-Abo und EU-weites Abo als monatliche Pauschale, Buchung mit Vorlauffenster, Test in zwei Märkten."}, {"q": "Wen würde das Abo anziehen?", "a": "Analysen deuten auf Vielflieger und flexible Privatreisende — genau die Gruppen mit dem größten Kannibalisierungsrisiko."}, {"q": "Welche Nebenerlöse sind relevant?", "a": "Gepäck, Sitzplatz, Verpflegung — Abo-Kunden könnten dort sogar mehr ausgeben."}]$J$::jsonb,
  reference_tree = $J$[{"id": "ccea-n1", "title": "Nachfrage & Kannibalisierung", "isPriority": true, "bulletPoints": [{"id": "ccea-n1b1", "text": "Kannibalisierung vs. inkrementelle Nachfrage quantifizieren"}, {"id": "ccea-n1b2", "text": "Adverse Selection: Vielflieger-Problem"}], "children": [{"id": "ccea-n1c1", "title": "Kapazitätsrealität bei 93% Load Factor", "bulletPoints": [], "children": []}]}, {"id": "ccea-n2", "title": "Ökonomie & Design", "isPriority": false, "bulletPoints": [{"id": "ccea-n2b1", "text": "Break-even-Flüge je Abo-Preis"}, {"id": "ccea-n2b2", "text": "Design-Hebel: Blackout-Zeiten, Standby-Logik, Kontingente"}], "children": []}, {"id": "ccea-n3", "title": "Ertrags-Nebeneffekte", "isPriority": false, "bulletPoints": [{"id": "ccea-n3b1", "text": "Ancillary-Umsatz der Abo-Kunden"}, {"id": "ccea-n3b2", "text": "CLV- und Bindungseffekt"}], "children": []}, {"id": "ccea-n4", "title": "Pilot & Risiko", "isPriority": false, "bulletPoints": [{"id": "ccea-n4b1", "text": "Test in 2 Märkten mit klaren Abbruchkriterien"}, {"id": "ccea-n4b2", "text": "Yield-Management-Konflikte steuern"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Bei 93% Load Factor ist Kannibalisierung + Adverse Selection die Kernfrage — ein Abo verkauft knappe Sitze billiger, wenn das Design (Kontingente, Blackouts, Standby) es nicht verhindert.$T$
WHERE id = 'cceaa705-8fee-41b3-902f-f966a7a532d2';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Warum wollen Kunden RaaS?", "a": "OpEx statt CapEx: keine Anfangsinvestition, Flexibilität bei Auslastungsschwankungen, Service inklusive."}, {"q": "Was besorgt den CFO konkret?", "a": "Umsatz verschiebt sich von Einmalerlösen in Raten — die GuV bricht optisch ein und die Bilanz trägt die Roboter."}, {"q": "Welche Kundensegmente sind RaaS-affin?", "a": "KMU und projektbasierte Fertiger; Großserienkunden kaufen tendenziell weiter klassisch."}, {"q": "Was kostet der Betrieb eines Roboters?", "a": "Wartung, Ersatzteile und Remote-Monitoring sind gut kalkulierbar — die Basis für eine Stunden-/Monatsrate existiert."}, {"q": "Was machen Wettbewerber?", "a": "Zwei testen RaaS in Pilotprogrammen; Preispunkte sind noch nicht etabliert — es gibt ein Zeitfenster."}]$J$::jsonb,
  reference_tree = $J$[{"id": "ed4e-n1", "title": "Preis- & Finanzmodell", "isPriority": true, "bulletPoints": [{"id": "ed4e-n1b1", "text": "Rate kalkulieren: Leasing-Logik + Service + Zielrendite"}, {"id": "ed4e-n1b2", "text": "Revenue-Recognition & Bilanz-Effekt modellieren"}], "children": [{"id": "ed4e-n1c1", "title": "Cash-Flow-Brücke der Übergangsjahre", "bulletPoints": [], "children": []}]}, {"id": "ed4e-n2", "title": "Segment-Strategie", "isPriority": false, "bulletPoints": [{"id": "ed4e-n2b1", "text": "RaaS für KMU/Projektfertiger, Kauf für Großserie"}, {"id": "ed4e-n2b2", "text": "Hybrid: Mietkauf, Mindestlaufzeiten"}], "children": []}, {"id": "ed4e-n3", "title": "Risiko & Asset-Management", "isPriority": false, "bulletPoints": [{"id": "ed4e-n3b1", "text": "Auslastungs-/Rückgaberisiko bepreisen"}, {"id": "ed4e-n3b2", "text": "Refurbishing & Zweitvermarktung"}], "children": []}, {"id": "ed4e-n4", "title": "Go-to-Market", "isPriority": false, "bulletPoints": [{"id": "ed4e-n4b1", "text": "Vertriebsvergütung auf wiederkehrend umstellen"}, {"id": "ed4e-n4b2", "text": "Pilotkunden & Referenzcases"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$RaaS = Pricing + Finanzierung + Risikotransfer in einem: Wer Rate, Bilanz-/Cash-Effekt und Auslastungsrisiko zusammen denkt (und segmentiert statt alles umzustellen), trifft den Kern.$T$
WHERE id = 'ed4ea0bd-6a32-4ef7-a17e-cd61c5c8fbae';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie groß sind die vier Bereiche?", "a": "Automotive und Chemicals tragen den Großteil des Umsatzes und das gesamte positive EBIT; Energy und Digital sind kleiner, wachsen aber."}, {"q": "Warum verlieren Energy und Digital Geld?", "a": "Energy leidet unter Preisdruck und Überkapazität; Digital ist im Aufbau mit hohen Vorlaufkosten und unklarem Geschäftsmodell."}, {"q": "Gibt es Synergien zwischen den Bereichen?", "a": "Begrenzt — Digital liefert Werkzeuge für die anderen Bereiche, Energy teilt sich Standorte mit Chemicals."}, {"q": "Was erwartet der Kapitalmarkt?", "a": "Analysten fordern seit Längerem ein klares Portfolio-Statement; ein Konglomeratsabschlag ist im Kurs sichtbar."}, {"q": "Gibt es Denkverbote?", "a": "Nein — von Turnaround über Verkauf bis Schließung ist alles diskutierbar."}]$J$::jsonb,
  reference_tree = $J$[{"id": "5b0b-n1", "title": "Transparenz je Bereich", "isPriority": true, "bulletPoints": [{"id": "5b0b-n1b1", "text": "EBIT-Brücken & ROIC je Segment"}, {"id": "5b0b-n1b2", "text": "Ursachen: strukturell vs. zyklisch vs. Aufbauphase"}], "children": [{"id": "5b0b-n1c1", "title": "Cross-Subsidies & Verrechnungen sichtbar machen", "bulletPoints": [], "children": []}]}, {"id": "5b0b-n2", "title": "Verlustbereiche: Optionen", "isPriority": false, "bulletPoints": [{"id": "5b0b-n2b1", "text": "Energy: Restrukturierung vs. Verkauf/Schließung"}, {"id": "5b0b-n2b2", "text": "Digital: fokussieren, Meilenstein-Finanzierung"}], "children": []}, {"id": "5b0b-n3", "title": "Gewinnbereiche stärken", "isPriority": false, "bulletPoints": [{"id": "5b0b-n3b1", "text": "Automotive/Chemicals: Cash-Generierung sichern"}, {"id": "5b0b-n3b2", "text": "Reinvestition nur bei klarem ROIC"}], "children": []}, {"id": "5b0b-n4", "title": "Portfolio & Kapitalmarkt", "isPriority": false, "bulletPoints": [{"id": "5b0b-n4b1", "text": "Zielportfolio & Sum-of-Parts-Logik"}, {"id": "5b0b-n4b2", "text": "Kommunikationsfähige Roadmap"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Konzern-Profitabilität = Segmentanalyse + differenzierte Behandlung (Energy ≠ Digital: strukturell vs. Aufbau). Wer alles gleich behandelt, argumentiert am Kern vorbei.$T$
WHERE id = '5b0b36ba-3432-4f8d-af0b-ffef2ed54ad4';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Warum steht der Loyalty-IPO im Raum?", "a": "Das Programm ist hochprofitabel; ein Teilverkauf würde die Verschuldung senken und den Wert sichtbar machen."}, {"q": "Wie hängen Loyalty und Passage zusammen?", "a": "Eng: Das Programm lebt von Flugmeilen, Statusvorteilen und der Kreditkartenpartnerschaft — eine Trennung braucht saubere Verträge."}, {"q": "Wie schlecht steht die Passage da?", "a": "Zurück auf Vorkrisen-Umsatz, aber Marge unter Vorkrise: Treibstoff, Personal und Pünktlichkeitskosten drücken."}, {"q": "Was ist mit Cargo und MRO?", "a": "Cargo normalisiert sich nach dem Boom, bleibt aber profitabel; MRO ist stabil, aber kapitalintensiv."}, {"q": "Wie hoch ist der Schuldendruck?", "a": "Nettoverschuldung deutlich über Ziel; das Rating steht unter Beobachtung."}]$J$::jsonb,
  reference_tree = $J$[{"id": "20d8-n1", "title": "Portfolio-Transparenz", "isPriority": false, "bulletPoints": [{"id": "20d8-n1b1", "text": "ROIC & Marge je Segment"}, {"id": "20d8-n1b2", "text": "Cross-Subsidies & interne Verrechnung (Meilen!)"}], "children": []}, {"id": "20d8-n2", "title": "Loyalty-IPO prüfen", "isPriority": true, "bulletPoints": [{"id": "20d8-n2b1", "text": "Standalone-Bewertung & Erlösverwendung (Schulden)"}, {"id": "20d8-n2b2", "text": "Vertragswerk Meilen/Status nach Teilverkauf"}], "children": [{"id": "20d8-n2c1", "title": "Risiko: Melkkuh verlieren vs. Wert heben", "bulletPoints": [], "children": []}]}, {"id": "20d8-n3", "title": "Passage-Turnaround", "isPriority": false, "bulletPoints": [{"id": "20d8-n3b1", "text": "Yield & Streckenportfolio bereinigen"}, {"id": "20d8-n3b2", "text": "Kostenprogramm Richtung Vorkrisenmarge"}], "children": []}, {"id": "20d8-n4", "title": "Kapitalstruktur", "isPriority": false, "bulletPoints": [{"id": "20d8-n4b1", "text": "Entschuldungspfad & Rating"}, {"id": "20d8-n4b2", "text": "Capex-Priorisierung (Flotte vs. MRO)"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Sum-of-Parts-Case: Loyalty-IPO ist Finanz-Hebel mit strategischem Preis (Abhängigkeiten Passage↔Loyalty). Wer beides verbindet und die Passage-Sanierung nicht vergisst, liegt richtig.$T$
WHERE id = '20d87cca-2a3c-4bd2-9336-63496b54d1b6';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie schnell schrumpft das ICE-Geschäft?", "a": "Mittlerer einstelliger Prozentsatz pro Jahr, mit beschleunigtem Rückgang ab Ende des Jahrzehnts erwartet."}, {"q": "Wann könnte E-Mobility break-even sein?", "a": "Nach interner Planung in vier bis fünf Jahren — wenn Skaleneffekte und zwei Großaufträge kommen."}, {"q": "Wie ist die Belegschaft verteilt?", "a": "Der Großteil arbeitet im ICE-Bereich; Umqualifizierung ist teilweise möglich, aber nicht für alle."}, {"q": "Wie reagieren die OEM-Kunden?", "a": "Sie verlangen Liefertreue im ICE bis zum Schluss UND aggressive E-Preise — die Verhandlungsmacht liegt bei ihnen."}, {"q": "Welche finanziellen Leitplanken gelten?", "a": "Die Konzernmarge darf nicht unter eine kritische Schwelle fallen, sonst drohen Rating- und Covenant-Probleme."}]$J$::jsonb,
  reference_tree = $J$[{"id": "8fe2-n1", "title": "ICE: Ernten", "isPriority": true, "bulletPoints": [{"id": "8fe2-n1b1", "text": "Cash-Cow-Management: Preise, Kosten, kein Neu-Capex"}, {"id": "8fe2-n1b2", "text": "Kapazitäten konsolidieren, sozialverträglicher Abbau"}], "children": []}, {"id": "8fe2-n2", "title": "E-Mobility: Reifen", "isPriority": false, "bulletPoints": [{"id": "8fe2-n2b1", "text": "Break-even-Pfad & Skaleneffekte"}, {"id": "8fe2-n2b2", "text": "Partnerschaften/Allianzen für Volumen"}], "children": []}, {"id": "8fe2-n3", "title": "Übergangssteuerung", "isPriority": false, "bulletPoints": [{"id": "8fe2-n3b1", "text": "Cash-Brücke: ICE finanziert E-Ramp-up"}, {"id": "8fe2-n3b2", "text": "Personal-Transformation (Umqualifizierung)"}], "children": [{"id": "8fe2-n3c1", "title": "Szenarien: schneller/langsamer ICE-Verfall", "bulletPoints": [], "children": []}]}, {"id": "8fe2-n4", "title": "Stakeholder & Leitplanken", "isPriority": false, "bulletPoints": [{"id": "8fe2-n4b1", "text": "OEM-Verhandlungen (Liefertreue vs. Preise)"}, {"id": "8fe2-n4b2", "text": "Margen-/Rating-Schwellen überwachen"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Dual Transformation: ICE ernten, E reifen, Übergang über Cash-Brücke und Szenarien steuern. Die Personal-Dimension gehört bei diesem Case zwingend dazu.$T$
WHERE id = '8fe2d54d-5433-49a8-8f41-0546d19db5d7';

UPDATE public.framework_cases SET
  clarifying_qa = $J$[{"q": "Wie verteilen sich Umsatz und Ergebnis?", "a": "TV trägt stabil, Events wachsen profitabel; Print und Streaming schreiben zusammen deutliche Verluste."}, {"q": "Wie weit ist Streaming vom Break-even entfernt?", "a": "Bei aktuellem Kurs zwei bis drei Jahre — abhängig von Content-Kosten und Abo-Wachstum."}, {"q": "Gibt es Interessenten für Print?", "a": "Sondierungen zeigen begrenztes Käuferinteresse zu niedrigen Bewertungen; ein Verkauf wäre eher Befreiung als Erlös."}, {"q": "Wie hängen die Segmente zusammen?", "a": "TV-Inhalte und -Reichweite stützen Streaming; Events profitieren von den Medienmarken — Print ist weitgehend entkoppelt."}, {"q": "Welche sozialen Restriktionen gelten?", "a": "Im Print-Segment arbeitet ein großer Teil der Belegschaft; jeder Umbau braucht einen sozialverträglichen Plan."}]$J$::jsonb,
  reference_tree = $J$[{"id": "2313-n1", "title": "Portfolio-Diagnose", "isPriority": true, "bulletPoints": [{"id": "2313-n1b1", "text": "Segmente klassifizieren (Cash Cow, Star, Dog...)"}, {"id": "2313-n1b2", "text": "Sum-of-Parts & Verbundeffekte"}], "children": [{"id": "2313-n1c1", "title": "Print: Harvest vs. Verkauf durchrechnen", "bulletPoints": [], "children": []}]}, {"id": "2313-n2", "title": "Streaming-Turnaround", "isPriority": false, "bulletPoints": [{"id": "2313-n2b1", "text": "Break-even-Pfad: Content-Kosten, Pricing, Bundles"}, {"id": "2313-n2b2", "text": "TV-Synergien maximal nutzen"}], "children": []}, {"id": "2313-n3", "title": "Wachstum finanzieren", "isPriority": false, "bulletPoints": [{"id": "2313-n3b1", "text": "TV-Cash in Streaming/Events lenken"}, {"id": "2313-n3b2", "text": "Events skalieren (Formate, Städte)"}], "children": []}, {"id": "2313-n4", "title": "Umsetzung & Stakeholder", "isPriority": false, "bulletPoints": [{"id": "2313-n4b1", "text": "Sozialplan & Kommunikation Print"}, {"id": "2313-n4b2", "text": "Meilensteine & Kapitalmarkt-Story"}], "children": []}]$J$::jsonb,
  interviewer_notes = $T$Portfolio-Case mit Verbundeffekten: Print-Entscheidung (Harvest vs. Verkauf) und Streaming-Pfad sind die Brennpunkte; TV als Finanzierungsquelle erkennen. Soziale Dimension nicht vergessen.$T$
WHERE id = '231370c4-c0ac-4e00-b418-63be6105faf6';

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'profitability', $T$Dein Klient ist BackWerk24, eine Bäckereikette mit 60 Filialen und eigener Großbäckerei. Trotz gestiegener Preise sinkt der Gewinn seit zwei Jahren. Der Inhaber bittet dich um eine strukturierte Ursachenanalyse mit Empfehlungen.$T$, NULL, $T$Profitability Framework$T$,
  $T$• Kostenseite: Energie: Effizienz Großbäckerei & Öfen, Rohstoffe: Einkauf, Rezepturen — Unteräste: Personaleinsatz nach Frequenz steuern
• Umsatz & Sortiment: Preis-/Mengeneffekt je Produktgruppe, Snack-/Kaffeegeschäft mit höherer Marge pushen
• Verschwendung & Retouren: Bedarfsprognose je Filiale & Tageszeit, Abverkaufslogik am Abend (Rabatte, Apps)
• Filialportfolio: Filial-P&L: Lagen clustern, Schwache Standorte sanieren oder schließen$T$,
  $J$[{"id": "m1-n1", "title": "Kostenseite", "isPriority": true, "bulletPoints": [{"id": "m1-n1b1", "text": "Energie: Effizienz Großbäckerei & Öfen"}, {"id": "m1-n1b2", "text": "Rohstoffe: Einkauf, Rezepturen"}], "children": [{"id": "m1-n1c1", "title": "Personaleinsatz nach Frequenz steuern", "bulletPoints": [], "children": []}]}, {"id": "m1-n2", "title": "Umsatz & Sortiment", "isPriority": false, "bulletPoints": [{"id": "m1-n2b1", "text": "Preis-/Mengeneffekt je Produktgruppe"}, {"id": "m1-n2b2", "text": "Snack-/Kaffeegeschäft mit höherer Marge pushen"}], "children": []}, {"id": "m1-n3", "title": "Verschwendung & Retouren", "isPriority": false, "bulletPoints": [{"id": "m1-n3b1", "text": "Bedarfsprognose je Filiale & Tageszeit"}, {"id": "m1-n3b2", "text": "Abverkaufslogik am Abend (Rabatte, Apps)"}], "children": []}, {"id": "m1-n4", "title": "Filialportfolio", "isPriority": false, "bulletPoints": [{"id": "m1-n4b1", "text": "Filial-P&L: Lagen clustern"}, {"id": "m1-n4b2", "text": "Schwache Standorte sanieren oder schließen"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was ist das Ziel?", "a": "Zurück zur alten Umsatzrendite innerhalb von 18 Monaten — ohne die Marke zu beschädigen."}, {"q": "Sind die Preiserhöhungen angekommen?", "a": "Ja, aber sie haben die Kostensteigerungen nur teilweise aufgefangen; die Stückzahlen gingen leicht zurück."}, {"q": "Welche Kosten sind gestiegen?", "a": "Energie für die Großbäckerei und Öfen, Rohstoffe (Mehl, Butter) und Personal — Energie am stärksten."}, {"q": "Wie viel wird weggeworfen?", "a": "Die Retourenquote (unverkaufte Ware) liegt deutlich über Branchenschnitt — abends sind die Theken bewusst voll."}, {"q": "Unterscheiden sich die Filialen?", "a": "Ja, stark: Bahnhofslagen laufen gut, einige Wohngebietsfilialen kaum kostendeckend."}]$J$::jsonb,
  $T$Mehrschichtiges Kostenproblem: Energie + Retouren sind die stillen Margenkiller. Starke Antworten quantifizieren den Preis-Mengen-Effekt und differenzieren nach Filialen statt pauschal zu sparen.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'profitability', $T$Dein Klient ist ein ambulanter Pflegedienst mit 120 Mitarbeitenden. Die Nachfrage ist hoch, die Touren sind voll — trotzdem ist das Ergebnis kaum positiv. Die Geschäftsführerin fragt: Woran liegt das, und welche Hebel haben wir?$T$, NULL, $T$Profitability Framework$T$,
  $T$• Produktivität der Touren: Tourenoptimierung (Software, Gebiete), Dokumentation digitalisieren (Zeit je Einsatz) — Unteräste: Einsatzarten bündeln: weniger Leerfahrten
• Leistungs- & Klientenmix: Behandlungspflege & besser vergütete Leistungen ausbauen, Unwirtschaftliche Einsätze neu verhandeln oder abgeben
• Vergütung: Kassenverhandlungen vorbereiten (Kostennachweis), Privatleistungen ergänzen
• Personalstabilität: Fluktuation senken (Dienstplanqualität), Ausfallmanagement statt teurer Springer$T$,
  $J$[{"id": "m2-n1", "title": "Produktivität der Touren", "isPriority": true, "bulletPoints": [{"id": "m2-n1b1", "text": "Tourenoptimierung (Software, Gebiete)"}, {"id": "m2-n1b2", "text": "Dokumentation digitalisieren (Zeit je Einsatz)"}], "children": [{"id": "m2-n1c1", "title": "Einsatzarten bündeln: weniger Leerfahrten", "bulletPoints": [], "children": []}]}, {"id": "m2-n2", "title": "Leistungs- & Klientenmix", "isPriority": false, "bulletPoints": [{"id": "m2-n2b1", "text": "Behandlungspflege & besser vergütete Leistungen ausbauen"}, {"id": "m2-n2b2", "text": "Unwirtschaftliche Einsätze neu verhandeln oder abgeben"}], "children": []}, {"id": "m2-n3", "title": "Vergütung", "isPriority": false, "bulletPoints": [{"id": "m2-n3b1", "text": "Kassenverhandlungen vorbereiten (Kostennachweis)"}, {"id": "m2-n3b2", "text": "Privatleistungen ergänzen"}], "children": []}, {"id": "m2-n4", "title": "Personalstabilität", "isPriority": false, "bulletPoints": [{"id": "m2-n4b1", "text": "Fluktuation senken (Dienstplanqualität)"}, {"id": "m2-n4b2", "text": "Ausfallmanagement statt teurer Springer"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie werden Leistungen vergütet?", "a": "Über feste Pflegekassen-Sätze je Leistung — die Preise sind also weitgehend vorgegeben, verhandelt wird selten."}, {"q": "Wo geht Zeit verloren?", "a": "Lange Fahrzeiten zwischen Klienten und viel unbezahlte Dokumentationszeit — die Tourenplanung erfolgt manuell."}, {"q": "Wie ist der Leistungsmix?", "a": "Viele kurze, schlecht vergütete Einsätze; besser vergütete Behandlungspflege macht nur einen kleinen Teil aus."}, {"q": "Wie hoch sind Ausfälle und Fluktuation?", "a": "Beides über Branchenschnitt — Springer und Überstunden verteuern jede Woche."}, {"q": "Gibt es Spielraum bei den Kassen?", "a": "Vergütungsverhandlungen sind möglich, wurden aber seit Jahren nicht geführt."}]$J$::jsonb,
  $T$Bei regulierten Preisen liegt der Hebel in Produktivität (Fahr-/Doku-Zeit) und Leistungsmix. Wer nur 'Preise erhöhen' sagt, hat das Vergütungssystem nicht verstanden.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'profitability', $T$Dein Klient betreibt drei Indoor-Spielplätze für Familien. Zwei laufen profitabel, der dritte — der größte und neueste — verliert Geld. Der Geschäftsführer will wissen, ob er ihn retten kann.$T$, NULL, $T$Profitability Framework$T$,
  $T$• Diagnose: Warum defizitär?: Standort-P&L vs. die zwei profitablen, Frequenz-, Preis- oder Kostenproblem?
• Auslastung Wochentage: Kitas/Schulen, Kurse, Vereins-Kooperationen, Off-Peak-Preise & Abos für Vielbesucher — Unteräste: Geburtstags-/Eventgeschäft aktiv vermarkten
• Kosten & Fläche: Öffnungszeiten & Personaleinsatz flexibilisieren, Teilfläche untervermieten (Option nutzen)
• Exit-Vergleich: Turnaround-Case vs. Schließungskosten (7 Jahre Miete), Entscheidung mit Meilensteinen$T$,
  $J$[{"id": "m3-n1", "title": "Diagnose: Warum defizitär?", "isPriority": false, "bulletPoints": [{"id": "m3-n1b1", "text": "Standort-P&L vs. die zwei profitablen"}, {"id": "m3-n1b2", "text": "Frequenz-, Preis- oder Kostenproblem?"}], "children": []}, {"id": "m3-n2", "title": "Auslastung Wochentage", "isPriority": true, "bulletPoints": [{"id": "m3-n2b1", "text": "Kitas/Schulen, Kurse, Vereins-Kooperationen"}, {"id": "m3-n2b2", "text": "Off-Peak-Preise & Abos für Vielbesucher"}], "children": [{"id": "m3-n2c1", "title": "Geburtstags-/Eventgeschäft aktiv vermarkten", "bulletPoints": [], "children": []}]}, {"id": "m3-n3", "title": "Kosten & Fläche", "isPriority": false, "bulletPoints": [{"id": "m3-n3b1", "text": "Öffnungszeiten & Personaleinsatz flexibilisieren"}, {"id": "m3-n3b2", "text": "Teilfläche untervermieten (Option nutzen)"}], "children": []}, {"id": "m3-n4", "title": "Exit-Vergleich", "isPriority": false, "bulletPoints": [{"id": "m3-n4b1", "text": "Turnaround-Case vs. Schließungskosten (7 Jahre Miete)"}, {"id": "m3-n4b2", "text": "Entscheidung mit Meilensteinen"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was unterscheidet den dritten Standort?", "a": "Er ist doppelt so groß, liegt am Stadtrand im Gewerbegebiet und hat die höchste Miete."}, {"q": "Wie sind die Besucherzahlen?", "a": "Am Wochenende ordentlich, unter der Woche fast leer — deutlich schlechter als die beiden anderen."}, {"q": "Wie setzt sich der Umsatz zusammen?", "a": "Eintritt plus Gastronomie; Geburtstagsfeiern sind das margenstärkste Produkt, dort ist er aber schwach gebucht."}, {"q": "Wie lange läuft der Mietvertrag?", "a": "Noch sieben Jahre, mit Option auf Untervermietung von Teilflächen."}, {"q": "Was kostet der Betrieb unter der Woche?", "a": "Fast so viel wie am Wochenende — Personal- und Energiekosten laufen weitgehend durch."}]$J$::jsonb,
  $T$Fixkosten-lastiges Freizeitgeschäft: Der Hebel ist Wochentags-Auslastung + Eventgeschäft; die Untervermietungs-Option ist das Sicherheitsnetz. Ein Entscheidungsrahmen (retten vs. exit) gehört dazu.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'profitability', $T$Dein Klient ist eine Werbeagentur mit 80 Mitarbeitenden. Der Umsatz wächst, aber die Marge schrumpft seit drei Jahren. Die Gründer ahnen, dass einige Kunden und Projekte Geld verbrennen — Transparenz fehlt. Strukturiere die Analyse.$T$, NULL, $T$Profitability / Portfolio Framework$T$,
  $T$• Transparenz schaffen: Nachkalkulation je Projekt & Kunde, Profitabilitäts-Ranking: Wer verbrennt Geld? — Unteräste: Ursachen: Scope Creep, Rabatte, Fehlkalkulation
• Kommerzielle Disziplin: Change-Requests konsequent bepreisen, Rabatt-Governance bei Pitches
• Ressourcen & Auslastung: Kapazitätsplanung Kreation vs. Strategie, Freelancer-Einsatz steuern
• Portfolio-Entscheidungen: Unprofitable Kunden sanieren oder trennen, Wachstum auf margenstarke Leistungen lenken$T$,
  $J$[{"id": "m4-n1", "title": "Transparenz schaffen", "isPriority": true, "bulletPoints": [{"id": "m4-n1b1", "text": "Nachkalkulation je Projekt & Kunde"}, {"id": "m4-n1b2", "text": "Profitabilitäts-Ranking: Wer verbrennt Geld?"}], "children": [{"id": "m4-n1c1", "title": "Ursachen: Scope Creep, Rabatte, Fehlkalkulation", "bulletPoints": [], "children": []}]}, {"id": "m4-n2", "title": "Kommerzielle Disziplin", "isPriority": false, "bulletPoints": [{"id": "m4-n2b1", "text": "Change-Requests konsequent bepreisen"}, {"id": "m4-n2b2", "text": "Rabatt-Governance bei Pitches"}], "children": []}, {"id": "m4-n3", "title": "Ressourcen & Auslastung", "isPriority": false, "bulletPoints": [{"id": "m4-n3b1", "text": "Kapazitätsplanung Kreation vs. Strategie"}, {"id": "m4-n3b2", "text": "Freelancer-Einsatz steuern"}], "children": []}, {"id": "m4-n4", "title": "Portfolio-Entscheidungen", "isPriority": false, "bulletPoints": [{"id": "m4-n4b1", "text": "Unprofitable Kunden sanieren oder trennen"}, {"id": "m4-n4b2", "text": "Wachstum auf margenstarke Leistungen lenken"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Gibt es eine Projekt-Nachkalkulation?", "a": "Nein — Stunden werden erfasst, aber nie gegen die Angebote ausgewertet."}, {"q": "Wie wird verkauft?", "a": "Überwiegend Festpreise, kalkuliert vom jeweiligen Beratungsteam — Rabatte bei Pitches sind üblich."}, {"q": "Welche Kunden wachsen?", "a": "Zwei Großkunden mit vielen kleinen Change-Requests, die selten berechnet werden."}, {"q": "Wie ist die Auslastung?", "a": "Kreation ist überbucht, Strategie unterausgelastet — Freelancer füllen teuer die Spitzen."}, {"q": "Was ist das Ziel der Gründer?", "a": "Marge zurück auf Branchenniveau, ohne Kernkunden zu verlieren."}]$J$::jsonb,
  $T$Professional-Services-Klassiker: Ohne Projekt-P&L keine Steuerung. Scope Creep bei Großkunden ist der versteckte Margenkiller — wer Transparenz → Disziplin → Portfolio logisch aufbaut, punktet.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'market_entry', $T$Dein Klient ist ein erfolgreicher Berliner Anbieter von Kochboxen-Abos. Er überlegt, in den österreichischen und Schweizer Markt zu expandieren. Wie würdest du die Entscheidung strukturieren?$T$, NULL, $T$Market Entry Framework$T$,
  $T$• Marktattraktivität je Land: Marktgröße, Abo-Affinität, Zahlungsbereitschaft, Wettbewerbsintensität AT vs. CH
• Operative Machbarkeit: AT: Belieferung aus DE-Netz möglich, CH: Zoll, eigenes Lager, Zutaten-Sourcing — Unteräste: Frische-/Lieferzeit-Anforderungen je Land
• Go-to-Market: Lokalisierung: Rezepte, Preise, Marketing, CAC-Annahmen & Startregionen
• Business Case & Sequenz: Investment & Break-even je Land, Empfehlung: AT zuerst, CH nach Beweis$T$,
  $J$[{"id": "m5-n1", "title": "Marktattraktivität je Land", "isPriority": false, "bulletPoints": [{"id": "m5-n1b1", "text": "Marktgröße, Abo-Affinität, Zahlungsbereitschaft"}, {"id": "m5-n1b2", "text": "Wettbewerbsintensität AT vs. CH"}], "children": []}, {"id": "m5-n2", "title": "Operative Machbarkeit", "isPriority": true, "bulletPoints": [{"id": "m5-n2b1", "text": "AT: Belieferung aus DE-Netz möglich"}, {"id": "m5-n2b2", "text": "CH: Zoll, eigenes Lager, Zutaten-Sourcing"}], "children": [{"id": "m5-n2c1", "title": "Frische-/Lieferzeit-Anforderungen je Land", "bulletPoints": [], "children": []}]}, {"id": "m5-n3", "title": "Go-to-Market", "isPriority": false, "bulletPoints": [{"id": "m5-n3b1", "text": "Lokalisierung: Rezepte, Preise, Marketing"}, {"id": "m5-n3b2", "text": "CAC-Annahmen & Startregionen"}], "children": []}, {"id": "m5-n4", "title": "Business Case & Sequenz", "isPriority": false, "bulletPoints": [{"id": "m5-n4b1", "text": "Investment & Break-even je Land"}, {"id": "m5-n4b2", "text": "Empfehlung: AT zuerst, CH nach Beweis"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was ist das Ziel der Expansion?", "a": "Neues Wachstum, weil der deutsche Markt zunehmend gesättigt ist — profitabel innerhalb von zwei Jahren je Markt."}, {"q": "Wie unterscheiden sich die Märkte?", "a": "Österreich ähnelt Deutschland; die Schweiz hat höhere Zahlungsbereitschaft, aber auch deutlich höhere Logistik- und Zutatenkosten plus Zollgrenze."}, {"q": "Gibt es dort schon Wettbewerber?", "a": "Ein internationaler Player ist in beiden Ländern aktiv, lokale Anbieter sind klein."}, {"q": "Kann die bestehende Logistik genutzt werden?", "a": "Für Österreich teilweise (Lieferung aus Bayern denkbar); die Schweiz bräuchte wegen Zoll und Frische ein eigenes Setup."}, {"q": "Wie stark ist die Marke dort?", "a": "Kaum bekannt — Marketing müsste von vorn aufgebaut werden."}]$J$::jsonb,
  $T$Zweiländer-Vergleich mit operativer Pointe: Österreich ist der logistisch einfache Einstieg, die Schweiz der margenreiche, aber teure Sonderfall. Eine Sequenz-Empfehlung wird erwartet.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'market_entry', $T$Dein Klient stellt hochwertige E-Bikes her und verkauft bisher nur über Fachhändler. Jetzt überlegt er, einen eigenen Online-Direktvertrieb zu starten. Strukturiere die Entscheidung.$T$, NULL, $T$Market Entry Framework$T$,
  $T$• Kanalkonflikt: Händler-Reaktionen & Abhängigkeit quantifizieren, Hybrid-Modelle: Online-Kauf, Händler-Übergabe — Unteräste: Händler einbinden: Provision auf D2C-Umsätze
• Kundennutzen & Nachfrage: Wer kauft online? (Segment, Preislage), Beratung/Probefahrt digital ersetzen?
• Operative Voraussetzungen: Versand, Montagegrad, Retouren, Servicenetz für Online-Kunden
• Wirtschaftlichkeit: Margen-Vergleich D2C vs. Handel (voll kalkuliert), Pilot mit Modell-Teilsortiment$T$,
  $J$[{"id": "m6-n1", "title": "Kanalkonflikt", "isPriority": true, "bulletPoints": [{"id": "m6-n1b1", "text": "Händler-Reaktionen & Abhängigkeit quantifizieren"}, {"id": "m6-n1b2", "text": "Hybrid-Modelle: Online-Kauf, Händler-Übergabe"}], "children": [{"id": "m6-n1c1", "title": "Händler einbinden: Provision auf D2C-Umsätze", "bulletPoints": [], "children": []}]}, {"id": "m6-n2", "title": "Kundennutzen & Nachfrage", "isPriority": false, "bulletPoints": [{"id": "m6-n2b1", "text": "Wer kauft online? (Segment, Preislage)"}, {"id": "m6-n2b2", "text": "Beratung/Probefahrt digital ersetzen?"}], "children": []}, {"id": "m6-n3", "title": "Operative Voraussetzungen", "isPriority": false, "bulletPoints": [{"id": "m6-n3b1", "text": "Versand, Montagegrad, Retouren"}, {"id": "m6-n3b2", "text": "Servicenetz für Online-Kunden"}], "children": []}, {"id": "m6-n4", "title": "Wirtschaftlichkeit", "isPriority": false, "bulletPoints": [{"id": "m6-n4b1", "text": "Margen-Vergleich D2C vs. Handel (voll kalkuliert)"}, {"id": "m6-n4b2", "text": "Pilot mit Modell-Teilsortiment"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Warum will der Klient D2C?", "a": "Höhere Marge, direkter Kundenzugang und Unabhängigkeit — Online-Pure-Player wachsen schneller als der Fachhandel."}, {"q": "Wie wichtig ist der Fachhandel heute?", "a": "Er macht praktisch den gesamten Absatz und übernimmt Beratung, Probefahrten und Service."}, {"q": "Wie reagieren Händler auf D2C-Pläne?", "a": "Sehr empfindlich — ein großer Händlerverbund hat bereits mit Auslistung gedroht."}, {"q": "Wer übernimmt Service und Garantie online?", "a": "Ungeklärt — E-Bikes brauchen Montage, Inspektionen und Reparaturnetz."}, {"q": "Was machen Wettbewerber?", "a": "Zwei Premium-Marken fahren hybride Modelle mit Online-Kauf und Händler-Übergabe."}]$J$::jsonb,
  $T$Kein reiner Online-Case, sondern Kanalkonflikt-Management: Das Hybrid-Modell mit Händlereinbindung ist die reife Antwort. Service/Montage entscheidet über D2C-Tauglichkeit.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'market_entry', $T$Dein Klient ist eine regionale Brauerei mit starker Marke. Der Biermarkt schrumpft, und die Geschäftsführung will in den wachsenden Markt für alkoholfreie Erfrischungsgetränke (Limonaden, Schorlen) einsteigen. Wie gehst du vor?$T$, NULL, $T$Market Entry Framework$T$,
  $T$• Markt & Positionierung: Segment: natürlich/regional statt Mainstream, Wettbewerb: Konzerne vs. Trend-Startups
• Eigene Stärken nutzen: Marke regional dehnen — passt sie zu Limo?, Abfüllung, Logistik, Gastro-/Handelszugang — Unteräste: Gastronomie als Launch-Kanal
• Produkt & Test: Prototypen im Markt testen (Gastro-Pilot), Preispositionierung Premium-Regional
• Wirtschaftlichkeit & Risiken: Umrüstkosten & Deckungsbeitrag je Kiste, Markenrisiko & Kannibalisierung (gering)$T$,
  $J$[{"id": "m7-n1", "title": "Markt & Positionierung", "isPriority": false, "bulletPoints": [{"id": "m7-n1b1", "text": "Segment: natürlich/regional statt Mainstream"}, {"id": "m7-n1b2", "text": "Wettbewerb: Konzerne vs. Trend-Startups"}], "children": []}, {"id": "m7-n2", "title": "Eigene Stärken nutzen", "isPriority": true, "bulletPoints": [{"id": "m7-n2b1", "text": "Marke regional dehnen — passt sie zu Limo?"}, {"id": "m7-n2b2", "text": "Abfüllung, Logistik, Gastro-/Handelszugang"}], "children": [{"id": "m7-n2c1", "title": "Gastronomie als Launch-Kanal", "bulletPoints": [], "children": []}]}, {"id": "m7-n3", "title": "Produkt & Test", "isPriority": false, "bulletPoints": [{"id": "m7-n3b1", "text": "Prototypen im Markt testen (Gastro-Pilot)"}, {"id": "m7-n3b2", "text": "Preispositionierung Premium-Regional"}], "children": []}, {"id": "m7-n4", "title": "Wirtschaftlichkeit & Risiken", "isPriority": false, "bulletPoints": [{"id": "m7-n4b1", "text": "Umrüstkosten & Deckungsbeitrag je Kiste"}, {"id": "m7-n4b2", "text": "Markenrisiko & Kannibalisierung (gering)"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was ist das Ziel?", "a": "Ein zweites Standbein, das in fünf Jahren einen relevanten Umsatzanteil liefert."}, {"q": "Welche Stärken bringt die Brauerei mit?", "a": "Bekannte Regionalmarke, eigene Abfüllung, Logistik und beste Beziehungen zu Gastronomie und Handel der Region."}, {"q": "Wie sieht der Limonadenmarkt aus?", "a": "Wächst, besonders bei natürlichen/zuckerreduzierten Produkten — besetzt von Konzernen und trendigen Startups."}, {"q": "Kann die Anlage Limonade abfüllen?", "a": "Ja, mit überschaubarer Umrüstung — freie Kapazitäten sind vorhanden."}, {"q": "Gibt es schon Produktideen?", "a": "Ein Braumeister-Team hat Prototypen mit regionalen Zutaten entwickelt, aber nichts ist getestet."}]$J$::jsonb,
  $T$Diversifikation entlang eigener Assets (Marke, Anlage, Vertrieb) — die Gastro-Basis als Testkanal zu nutzen ist der elegante Zug. Bewertet wird der Fit, nicht Fantasie-Marktgrößen.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'growth', $T$Dein Klient ist eine Fahrschul-Kette mit 25 Standorten. Die Nachfrage ist stabil, aber der Umsatz stagniert und die Wartezeiten für Fahrstunden sind lang. Der Inhaber will wachsen — wie strukturierst du das?$T$, NULL, $T$Growth Framework$T$,
  $T$• Kapazität: Fahrlehrer: Rekrutierung & eigene Ausbildung finanzieren, Bindung: Gehalt, Dienstwagenmodell, Planbarkeit — Unteräste: Vormittags-Auslastung: Erwachsene, Intensivkurse
• Preis & Angebot: Preiserhöhung bei Übernachfrage, Premium-Pakete: Intensiv, Automatik, Garantie-Modelle
• Digitalisierung: Online-Theorie & App-Buchung, Verwaltung zentralisieren, Fahrlehrer entlasten
• Expansion: Neue Standorte nur nach Kapazitätslösung, Übernahme kleiner Fahrschulen (Konsolidierung)$T$,
  $J$[{"id": "m8-n1", "title": "Kapazität: Fahrlehrer", "isPriority": true, "bulletPoints": [{"id": "m8-n1b1", "text": "Rekrutierung & eigene Ausbildung finanzieren"}, {"id": "m8-n1b2", "text": "Bindung: Gehalt, Dienstwagenmodell, Planbarkeit"}], "children": [{"id": "m8-n1c1", "title": "Vormittags-Auslastung: Erwachsene, Intensivkurse", "bulletPoints": [], "children": []}]}, {"id": "m8-n2", "title": "Preis & Angebot", "isPriority": false, "bulletPoints": [{"id": "m8-n2b1", "text": "Preiserhöhung bei Übernachfrage"}, {"id": "m8-n2b2", "text": "Premium-Pakete: Intensiv, Automatik, Garantie-Modelle"}], "children": []}, {"id": "m8-n3", "title": "Digitalisierung", "isPriority": false, "bulletPoints": [{"id": "m8-n3b1", "text": "Online-Theorie & App-Buchung"}, {"id": "m8-n3b2", "text": "Verwaltung zentralisieren, Fahrlehrer entlasten"}], "children": []}, {"id": "m8-n4", "title": "Expansion", "isPriority": false, "bulletPoints": [{"id": "m8-n4b1", "text": "Neue Standorte nur nach Kapazitätslösung"}, {"id": "m8-n4b2", "text": "Übernahme kleiner Fahrschulen (Konsolidierung)"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was begrenzt das Wachstum?", "a": "Fahrlehrermangel: Stellen bleiben monatelang unbesetzt, Fahrzeuge stehen zeitweise ungenutzt."}, {"q": "Wie ist die Preisgestaltung?", "a": "Eher unteres Marktniveau; die letzte Erhöhung liegt Jahre zurück, die Nachfrage übersteigt das Angebot."}, {"q": "Wie laufen Theorie und Verwaltung?", "a": "Theorie klassisch in Präsenz, Terminvergabe telefonisch — digital ist wenig."}, {"q": "Gibt es Zusatzgeschäft?", "a": "Kaum: keine Intensivkurse, kein B197/Automatik-Fokus, keine Firmenkooperationen."}, {"q": "Wie ist die Auslastung über den Tag?", "a": "Nachmittags überbucht, vormittags schwach — Schüler wollen alle nach der Schule fahren."}]$J$::jsonb,
  $T$Wachstum bei Angebotsengpass: Erst Kapazität (Fahrlehrer, Auslastung, Digitalisierung), dann Preis nutzen, dann expandieren. 'Mehr Marketing' wäre hier die falsche Antwort.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'growth', $T$Dein Klient ist ein Hersteller von Premium-Hundefutter mit starkem Online-Abo-Geschäft in Deutschland. Das Wachstum flacht ab. Entwickle eine Wachstumsstruktur für die nächsten drei Jahre.$T$, NULL, $T$Growth Framework (Ansoff-Logik)$T$,
  $T$• Bestandskunden ausschöpfen: Cross-Sell: Snacks, Zubehör, Gesundheitsprodukte, Preis-/Paketdifferenzierung
• Neue Segmente & Produkte: Katzenfutter als nächste Kategorie, Einstiegslinie für preissensiblere Halter — Unteräste: Vet-/Spezialfutter (Allergien, Senior)
• Neue Kanäle: Selektiver Einzelhandel/Fachhandel als Reichweite, Marktplätze mit Abo-Brücke
• Neue Märkte: AT/CH als naheliegende Expansion, Logistik & Lokalisierung prüfen$T$,
  $J$[{"id": "m9-n1", "title": "Bestandskunden ausschöpfen", "isPriority": false, "bulletPoints": [{"id": "m9-n1b1", "text": "Cross-Sell: Snacks, Zubehör, Gesundheitsprodukte"}, {"id": "m9-n1b2", "text": "Preis-/Paketdifferenzierung"}], "children": []}, {"id": "m9-n2", "title": "Neue Segmente & Produkte", "isPriority": true, "bulletPoints": [{"id": "m9-n2b1", "text": "Katzenfutter als nächste Kategorie"}, {"id": "m9-n2b2", "text": "Einstiegslinie für preissensiblere Halter"}], "children": [{"id": "m9-n2c1", "title": "Vet-/Spezialfutter (Allergien, Senior)", "bulletPoints": [], "children": []}]}, {"id": "m9-n3", "title": "Neue Kanäle", "isPriority": false, "bulletPoints": [{"id": "m9-n3b1", "text": "Selektiver Einzelhandel/Fachhandel als Reichweite"}, {"id": "m9-n3b2", "text": "Marktplätze mit Abo-Brücke"}], "children": []}, {"id": "m9-n4", "title": "Neue Märkte", "isPriority": false, "bulletPoints": [{"id": "m9-n4b1", "text": "AT/CH als naheliegende Expansion"}, {"id": "m9-n4b2", "text": "Logistik & Lokalisierung prüfen"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie ist das Geschäftsmodell?", "a": "D2C-Abos mit personalisierten Futterplänen; Abo-Anteil über 80%, gute Margen."}, {"q": "Warum flacht das Wachstum ab?", "a": "Die Kernzielgruppe (zahlungskräftige Hundehalter online) ist zunehmend durchdrungen, CAC steigt."}, {"q": "Wie ist die Kundenbindung?", "a": "Sehr gut — Churn niedrig, hohe Weiterempfehlung."}, {"q": "Was gibt es außer Hundefutter?", "a": "Nur wenige Snacks; kein Katzenfutter, kein Zubehör."}, {"q": "Ist der Handel eine Option?", "a": "Bisher bewusst nicht — der Vorstand fürchtet Margenverlust und Kanalkonflikt, ist aber gesprächsbereit."}]$J$::jsonb,
  $T$Sättigung der Nische: Wachstum über Kategorie-Erweiterung (Katze!) und kontrollierte Kanalöffnung. Gute Antworten wägen Kanalkonflikt explizit ab statt ihn zu ignorieren.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'growth', $T$Dein Klient betreibt ein regionales Jobportal für Handwerks- und Logistikberufe. Es ist profitabel, wächst aber kaum noch. Große Generalisten-Portale dominieren den Markt. Wie kann das Portal wachsen?$T$, NULL, $T$Growth Framework$T$,
  $T$• Monetarisierung vertiefen: Abo-/Flatrate-Modelle für Vielinserenten, Employer-Branding- & Active-Sourcing-Produkte — Unteräste: Erfolgsbasierte Modelle (Cost-per-Hire) testen
• Kandidatenbindung: Profile & Job-Alerts aufbauen (wiederkehrende Nutzer), Content/Community für Gewerke
• Geografische Expansion: Nachbarregionen mit gleichem Playbook, Vertrieb regional skalieren
• Fokus-Entscheidung: Nische vertiefen statt Branchen verbreitern, Kriterien & Sequenz festlegen$T$,
  $J$[{"id": "m10-n1", "title": "Monetarisierung vertiefen", "isPriority": true, "bulletPoints": [{"id": "m10-n1b1", "text": "Abo-/Flatrate-Modelle für Vielinserenten"}, {"id": "m10-n1b2", "text": "Employer-Branding- & Active-Sourcing-Produkte"}], "children": [{"id": "m10-n1c1", "title": "Erfolgsbasierte Modelle (Cost-per-Hire) testen", "bulletPoints": [], "children": []}]}, {"id": "m10-n2", "title": "Kandidatenbindung", "isPriority": false, "bulletPoints": [{"id": "m10-n2b1", "text": "Profile & Job-Alerts aufbauen (wiederkehrende Nutzer)"}, {"id": "m10-n2b2", "text": "Content/Community für Gewerke"}], "children": []}, {"id": "m10-n3", "title": "Geografische Expansion", "isPriority": false, "bulletPoints": [{"id": "m10-n3b1", "text": "Nachbarregionen mit gleichem Playbook"}, {"id": "m10-n3b2", "text": "Vertrieb regional skalieren"}], "children": []}, {"id": "m10-n4", "title": "Fokus-Entscheidung", "isPriority": false, "bulletPoints": [{"id": "m10-n4b1", "text": "Nische vertiefen statt Branchen verbreitern"}, {"id": "m10-n4b2", "text": "Kriterien & Sequenz festlegen"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was ist die Stärke des Portals?", "a": "Tiefe Spezialisierung: passgenaue Kandidaten, gute Besetzungsquoten, starke Arbeitgebermarke in der Nische."}, {"q": "Wer zahlt und wie?", "a": "Arbeitgeber zahlen pro Anzeige; es gibt keine Abos und kein Employer-Branding-Produkt."}, {"q": "Wie ist die Kandidatenseite?", "a": "Solider Traffic über SEO und Empfehlungen, aber wenige registrierte Profile — Kandidaten kommen und gehen."}, {"q": "Was machen die Generalisten?", "a": "Masse statt Klasse — in der Zielnische sind ihre Besetzungsquoten messbar schlechter."}, {"q": "Gibt es Expansionsideen?", "a": "Diskutiert werden: weitere Regionen, weitere Branchen und neue Produkte — der Inhaber will Fokus."}]$J$::jsonb,
  $T$Nischen-Marktplatz: Wachstum aus Monetarisierungstiefe + Kandidatenbindung + regionaler Replikation. Die Verbreiterung in fremde Branchen ist die Falle, die Fokus-Argumentation der Kern.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'growth', $T$Dein Klient ist ein mittelständischer Hersteller von Gartengeräten (Qualitätssegment), der fast nur über Baumärkte verkauft. Der Umsatz stagniert, die Baumärkte drücken die Preise. Entwickle Wachstumsoptionen.$T$, NULL, $T$Growth Framework$T$,
  $T$• Produktportfolio: Akku-Offensive: Plattformstrategie, Time-to-Market, Ersatzteile & Zubehör als Margenträger — Unteräste: Services: Schärfen, Reparatur, Garantie-Plus
• Kanal-Diversifizierung: Eigener Shop + Marktplätze behutsam ausbauen, Fachhandel/Gartencenter als Zweitkanal
• Marke & Zielgruppen: Verjüngung: Content, Garten-Communities, Urban Gardening/Balkon-Segment
• Baumarkt-Beziehung: Kategorie-Partnerschaft statt Preisverhandlung, Exklusive Linien je Kette gegen Konditionen$T$,
  $J$[{"id": "m11-n1", "title": "Produktportfolio", "isPriority": true, "bulletPoints": [{"id": "m11-n1b1", "text": "Akku-Offensive: Plattformstrategie, Time-to-Market"}, {"id": "m11-n1b2", "text": "Ersatzteile & Zubehör als Margenträger"}], "children": [{"id": "m11-n1c1", "title": "Services: Schärfen, Reparatur, Garantie-Plus", "bulletPoints": [], "children": []}]}, {"id": "m11-n2", "title": "Kanal-Diversifizierung", "isPriority": false, "bulletPoints": [{"id": "m11-n2b1", "text": "Eigener Shop + Marktplätze behutsam ausbauen"}, {"id": "m11-n2b2", "text": "Fachhandel/Gartencenter als Zweitkanal"}], "children": []}, {"id": "m11-n3", "title": "Marke & Zielgruppen", "isPriority": false, "bulletPoints": [{"id": "m11-n3b1", "text": "Verjüngung: Content, Garten-Communities"}, {"id": "m11-n3b2", "text": "Urban Gardening/Balkon-Segment"}], "children": []}, {"id": "m11-n4", "title": "Baumarkt-Beziehung", "isPriority": false, "bulletPoints": [{"id": "m11-n4b1", "text": "Kategorie-Partnerschaft statt Preisverhandlung"}, {"id": "m11-n4b2", "text": "Exklusive Linien je Kette gegen Konditionen"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie abhängig ist der Klient vom Baumarkt-Kanal?", "a": "Sehr: Drei Ketten stehen für den Großteil des Umsatzes und nutzen das in den Jahresgesprächen aus."}, {"q": "Wie stark ist die Marke beim Endkunden?", "a": "Bekannt und vertraut bei der älteren Zielgruppe, bei Jüngeren kaum präsent."}, {"q": "Gibt es E-Commerce?", "a": "Einen kleinen eigenen Shop ohne nennenswerten Umsatz; Marktplätze werden nicht aktiv bespielt."}, {"q": "Was passiert im Produktbereich?", "a": "Akku-Geräte wachsen stark — dort ist der Klient spät dran; klassische Handgeräte sind die Basis."}, {"q": "Wohin will der Inhaber?", "a": "Weniger Kanalabhängigkeit, mehr Marge, moderne Zielgruppen — ohne die Baumärkte zu verprellen."}]$J$::jsonb,
  $T$Kanalmacht-Problem plus Technologiewandel (Akku): Wachstum = Produktoffensive + vorsichtige Kanal-Diversifizierung, ohne den Kernkanal zu sprengen. Die Balance ist der Prüfstein.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'ma', $T$Dein Klient ist eine Steuerberatungs-Gruppe, die durch Zukäufe kleiner Kanzleien wächst. Aktuell steht die Übernahme einer Kanzlei mit 25 Mitarbeitenden an, deren Inhaber in den Ruhestand geht. Wie prüfst du den Deal strukturiert?$T$, NULL, $T$M&A Framework$T$,
  $T$• Qualität der Kanzlei: Mandantenstruktur: Branchen, Größen, Abhängigkeiten, Ertragsqualität & Stundensätze
• Menschen & Übergang: Inhaber-Übergangsphase vertraglich sichern, Leistungsträger binden (Angebote, Perspektiven) — Unteräste: Mandanten-Kommunikation planen
• Wertsteigerung nach Kauf: Digitalisierung & Prozesse der Gruppe ausrollen, Stundensätze schrittweise anheben
• Deal-Struktur: Multiple + Earn-out an Mandantenerhalt koppeln, Integrationsplan: Woche 1 bis Jahr 1$T$,
  $J$[{"id": "m12-n1", "title": "Qualität der Kanzlei", "isPriority": false, "bulletPoints": [{"id": "m12-n1b1", "text": "Mandantenstruktur: Branchen, Größen, Abhängigkeiten"}, {"id": "m12-n1b2", "text": "Ertragsqualität & Stundensätze"}], "children": []}, {"id": "m12-n2", "title": "Menschen & Übergang", "isPriority": true, "bulletPoints": [{"id": "m12-n2b1", "text": "Inhaber-Übergangsphase vertraglich sichern"}, {"id": "m12-n2b2", "text": "Leistungsträger binden (Angebote, Perspektiven)"}], "children": [{"id": "m12-n2c1", "title": "Mandanten-Kommunikation planen", "bulletPoints": [], "children": []}]}, {"id": "m12-n3", "title": "Wertsteigerung nach Kauf", "isPriority": false, "bulletPoints": [{"id": "m12-n3b1", "text": "Digitalisierung & Prozesse der Gruppe ausrollen"}, {"id": "m12-n3b2", "text": "Stundensätze schrittweise anheben"}], "children": []}, {"id": "m12-n4", "title": "Deal-Struktur", "isPriority": false, "bulletPoints": [{"id": "m12-n4b1", "text": "Multiple + Earn-out an Mandantenerhalt koppeln"}, {"id": "m12-n4b2", "text": "Integrationsplan: Woche 1 bis Jahr 1"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Warum verkauft der Inhaber?", "a": "Altersnachfolge — er will geordnet übergeben und hängt an seinem Team und den Mandanten."}, {"q": "Wie loyal sind die Mandanten?", "a": "Langjährig, aber stark auf den Inhaber persönlich bezogen — die Übergangsbegleitung ist entscheidend."}, {"q": "Wie steht die Kanzlei wirtschaftlich da?", "a": "Solide Umsatzrendite, aber wenig digitalisiert und mit unterdurchschnittlichen Stundensätzen."}, {"q": "Wie ist das Team aufgestellt?", "a": "Erfahren, aber zwei Leistungsträger liebäugeln mit Wechsel — Bindung ist ein Thema."}, {"q": "Wie wird üblicherweise bezahlt?", "a": "Kaufpreis als Umsatz-Multiple mit Earn-out über zwei bis drei Jahre, abhängig vom Mandantenerhalt."}]$J$::jsonb,
  $T$People-Business-Nachfolge: Mandanten- und Mitarbeiterbindung sind der Deal — Earn-out als Absicherung. Wertsteigerungslogik (Digitalisierung, Preise) macht die Antwort rund.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'ma', $T$Dein Klient ist ein Anbieter von Betriebsverpflegung (Kantinen). Er kann einen Wettbewerber ähnlicher Größe übernehmen, der in einer Nachbarregion stark ist. Bewerte die Übernahme strukturiert.$T$, NULL, $T$M&A Framework$T$,
  $T$• Strategischer Fit: Regionale Komplementarität, keine Kannibalisierung, Skaleneffekte: Einkauf, Verwaltung, Logistik
• Target-Qualität: Vertragslaufzeiten & Change-of-Control-Klauseln, Margenlücke: Ursachen & Hebbarkeit — Unteräste: Kundenbindung im Übergang sichern
• Synergien & Integration: Einkaufskonditionen harmonisieren (Quick Win), Küchenkonzepte/Systeme: Aufwand realistisch schätzen
• Preis & Risiken: Bewertung mit/ohne Synergien, Schlüsselrisiko: Vertragsverluste im Jahr 1$T$,
  $J$[{"id": "m13-n1", "title": "Strategischer Fit", "isPriority": false, "bulletPoints": [{"id": "m13-n1b1", "text": "Regionale Komplementarität, keine Kannibalisierung"}, {"id": "m13-n1b2", "text": "Skaleneffekte: Einkauf, Verwaltung, Logistik"}], "children": []}, {"id": "m13-n2", "title": "Target-Qualität", "isPriority": true, "bulletPoints": [{"id": "m13-n2b1", "text": "Vertragslaufzeiten & Change-of-Control-Klauseln"}, {"id": "m13-n2b2", "text": "Margenlücke: Ursachen & Hebbarkeit"}], "children": [{"id": "m13-n2c1", "title": "Kundenbindung im Übergang sichern", "bulletPoints": [], "children": []}]}, {"id": "m13-n3", "title": "Synergien & Integration", "isPriority": false, "bulletPoints": [{"id": "m13-n3b1", "text": "Einkaufskonditionen harmonisieren (Quick Win)"}, {"id": "m13-n3b2", "text": "Küchenkonzepte/Systeme: Aufwand realistisch schätzen"}], "children": []}, {"id": "m13-n4", "title": "Preis & Risiken", "isPriority": false, "bulletPoints": [{"id": "m13-n4b1", "text": "Bewertung mit/ohne Synergien"}, {"id": "m13-n4b2", "text": "Schlüsselrisiko: Vertragsverluste im Jahr 1"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was ist die strategische Logik?", "a": "Regionale Erweiterung ohne Überschneidung plus Skaleneffekte im Einkauf und in der Verwaltung."}, {"q": "Wie profitabel ist das Target?", "a": "Etwas schwächer als der Klient — vor allem wegen teurerer Wareneinsätze und älterer Verträge."}, {"q": "Wie sind die Kundenverträge?", "a": "Mehrjährige Verträge mit Unternehmen und Kliniken; einige laufen im Übernahmejahr aus."}, {"q": "Gibt es Wechselklauseln bei Betreiberwechsel?", "a": "Bei einem Teil der Verträge ja — Kunden könnten bei Übernahme kündigen."}, {"q": "Wie ähnlich sind die Betriebsmodelle?", "a": "Ähnlich, aber unterschiedliche Küchenkonzepte und Systeme — Integration wäre echte Arbeit."}]$J$::jsonb,
  $T$Konsolidierungs-Deal: Der Wert hängt an Vertragsbestand (Change-of-Control!) und hebbaren Einkaufssynergien. Wer Integrationsaufwand ehrlich einpreist, hebt sich ab.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'ma', $T$Dein Klient ist ein Softwareanbieter für Zahnarztpraxen. Ein großer Dentalgeräte-Hersteller bietet an, den Klienten zu übernehmen — alternativ eine strategische Partnerschaft. Die Gründer fragen dich: Wie sollen wir diese Offerte bewerten?$T$, NULL, $T$M&A / Partnership Framework$T$,
  $T$• Ziele der Gründer klären: Exit vs. Wachstum vs. Kontrolle gewichten, Preis-Schwelle für Vollverkauf definieren
• Option Übernahme: Bewertung & Struktur (Earn-out, Rollen), Integrationsrisiko: Produktkultur im Konzern
• Option Partnerschaft: Vertriebshebel quantifizieren (Pipeline-Zusagen), Exklusivität: Verlust anderer Partner einpreisen — Unteräste: Vertragsschutz: Laufzeit, Mindestumsätze, Rückfall
• Alternative: Eigenständig: Finanzierungsrunde + Vertriebsaufbau, BATNA für die Verhandlung nutzen$T$,
  $J$[{"id": "m14-n1", "title": "Ziele der Gründer klären", "isPriority": true, "bulletPoints": [{"id": "m14-n1b1", "text": "Exit vs. Wachstum vs. Kontrolle gewichten"}, {"id": "m14-n1b2", "text": "Preis-Schwelle für Vollverkauf definieren"}], "children": []}, {"id": "m14-n2", "title": "Option Übernahme", "isPriority": false, "bulletPoints": [{"id": "m14-n2b1", "text": "Bewertung & Struktur (Earn-out, Rollen)"}, {"id": "m14-n2b2", "text": "Integrationsrisiko: Produktkultur im Konzern"}], "children": []}, {"id": "m14-n3", "title": "Option Partnerschaft", "isPriority": false, "bulletPoints": [{"id": "m14-n3b1", "text": "Vertriebshebel quantifizieren (Pipeline-Zusagen)"}, {"id": "m14-n3b2", "text": "Exklusivität: Verlust anderer Partner einpreisen"}], "children": [{"id": "m14-n3c1", "title": "Vertragsschutz: Laufzeit, Mindestumsätze, Rückfall", "bulletPoints": [], "children": []}]}, {"id": "m14-n4", "title": "Alternative: Eigenständig", "isPriority": false, "bulletPoints": [{"id": "m14-n4b1", "text": "Finanzierungsrunde + Vertriebsaufbau"}, {"id": "m14-n4b2", "text": "BATNA für die Verhandlung nutzen"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was bietet der Hersteller konkret?", "a": "Eine Vollübernahme zu attraktivem Preis — alternativ exklusive Vertriebspartnerschaft mit Minderheitsbeteiligung."}, {"q": "Was wollen die Gründer eigentlich?", "a": "Wachstum beschleunigen; ein kompletter Ausstieg war nicht geplant, ist aber beim richtigen Preis diskutabel."}, {"q": "Welche Synergien verspricht der Hersteller?", "a": "Zugang zu tausenden Praxen über seinen Außendienst und Bundling mit Geräten."}, {"q": "Was wäre der Preis der Exklusivität?", "a": "Andere Gerätehersteller — heute Kooperationspartner — würden wohl abspringen."}, {"q": "Wie steht der Klient allein da?", "a": "Profitabel wachsend, aber Vertrieb ist der Engpass; eine Finanzierungsrunde wäre die Alternative."}]$J$::jsonb,
  $T$Optionen-Case aus Verkäufersicht: Erst Gründerziele, dann drei Optionen inkl. BATNA. Der Exklusivitäts-Preis der Partnerschaft ist die versteckte Kernfrage.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'pricing', $T$Dein Klient betreibt eine Kette von Autowaschanlagen. Alle Standorte haben identische Preise, obwohl sich Lage, Wettbewerb und Auslastung stark unterscheiden. Der CEO fragt: Wie sollten wir unsere Preise gestalten?$T$, NULL, $T$Pricing Framework$T$,
  $T$• Preisdifferenzierung: Standort-Pricing nach Lage & Wettbewerb, Zeitbasiert: Peak vs. Off-Peak — Unteräste: Programm-Architektur & Upsell-Treppe
• Bindungsmodelle: Wasch-Abo/Flatrate für Vielwäscher, App & Loyalty statt Stempelkarte
• Zahlungsbereitschaft & Tests: Elastizität je Standorttyp testen (Piloten), Wettbewerbs-Preisanker je Mikromarkt
• Umsetzung & Risiken: Preiskommunikation & Fairness-Wahrnehmung, Kannibalisierung Abo vs. Einzelwäsche steuern$T$,
  $J$[{"id": "m15-n1", "title": "Preisdifferenzierung", "isPriority": true, "bulletPoints": [{"id": "m15-n1b1", "text": "Standort-Pricing nach Lage & Wettbewerb"}, {"id": "m15-n1b2", "text": "Zeitbasiert: Peak vs. Off-Peak"}], "children": [{"id": "m15-n1c1", "title": "Programm-Architektur & Upsell-Treppe", "bulletPoints": [], "children": []}]}, {"id": "m15-n2", "title": "Bindungsmodelle", "isPriority": false, "bulletPoints": [{"id": "m15-n2b1", "text": "Wasch-Abo/Flatrate für Vielwäscher"}, {"id": "m15-n2b2", "text": "App & Loyalty statt Stempelkarte"}], "children": []}, {"id": "m15-n3", "title": "Zahlungsbereitschaft & Tests", "isPriority": false, "bulletPoints": [{"id": "m15-n3b1", "text": "Elastizität je Standorttyp testen (Piloten)"}, {"id": "m15-n3b2", "text": "Wettbewerbs-Preisanker je Mikromarkt"}], "children": []}, {"id": "m15-n4", "title": "Umsetzung & Risiken", "isPriority": false, "bulletPoints": [{"id": "m15-n4b1", "text": "Preiskommunikation & Fairness-Wahrnehmung"}, {"id": "m15-n4b2", "text": "Kannibalisierung Abo vs. Einzelwäsche steuern"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie ist das heutige Preissystem?", "a": "Vier Waschprogramme mit bundesweit einheitlichen Preisen; Rabatt gibt es nur über eine selten genutzte Stempelkarte."}, {"q": "Wie unterschiedlich sind die Standorte?", "a": "Stark: Innenstadtlagen mit Warteschlangen am Samstag, Landstandorte mit Leerlauf unter der Woche."}, {"q": "Was macht der Wettbewerb?", "a": "Lokal sehr unterschiedlich — von Discount-Waschstraßen bis Premium-Handwäsche."}, {"q": "Gibt es Abo-Modelle im Markt?", "a": "Ja, Flatrate-Abos setzen sich international durch und binden Vielwäscher."}, {"q": "Welche Daten liegen vor?", "a": "Auslastung je Standort und Stunde sowie Programm-Mix sind sauber erfasst."}]$J$::jsonb,
  $T$Einheitspreis trotz heterogener Standorte = verschenktes Geld. Standort- und Zeitdifferenzierung plus Abo-Modell sind die Kernhebel; Pilotlogik zeigt Umsetzungsreife.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'pricing', $T$Dein Klient ist ein Anbieter von Online-Weiterbildungen für Pflegekräfte (B2B-Verkauf an Kliniken und Heime). Die Abschlussquoten im Vertrieb sind gut, aber der CFO glaubt, dass systematisch zu billig verkauft wird. Analysiere das Pricing.$T$, NULL, $T$Pricing Framework$T$,
  $T$• Preis-Diagnose: Win-Rate & Rabatt-Verteilung analysieren, Wettbewerbs- & Wertbenchmark (Freistellungskosten) — Unteräste: Zahlungsbereitschaft je Einrichtungstyp
• Preisarchitektur: Listenpreise & Paket-/Flatrate-Modelle je Haustyp, Rabatt-Leitplanken statt freier Verhandlung
• Vertriebssteuerung: Provision auf Marge/Preisqualität umstellen, Value-Selling-Argumentarium
• Rollout: Preiserhöhung bei Neukunden zuerst, Bestandskunden mit Mehrwert-Story migrieren$T$,
  $J$[{"id": "m16-n1", "title": "Preis-Diagnose", "isPriority": true, "bulletPoints": [{"id": "m16-n1b1", "text": "Win-Rate & Rabatt-Verteilung analysieren"}, {"id": "m16-n1b2", "text": "Wettbewerbs- & Wertbenchmark (Freistellungskosten)"}], "children": [{"id": "m16-n1c1", "title": "Zahlungsbereitschaft je Einrichtungstyp", "bulletPoints": [], "children": []}]}, {"id": "m16-n2", "title": "Preisarchitektur", "isPriority": false, "bulletPoints": [{"id": "m16-n2b1", "text": "Listenpreise & Paket-/Flatrate-Modelle je Haustyp"}, {"id": "m16-n2b2", "text": "Rabatt-Leitplanken statt freier Verhandlung"}], "children": []}, {"id": "m16-n3", "title": "Vertriebssteuerung", "isPriority": false, "bulletPoints": [{"id": "m16-n3b1", "text": "Provision auf Marge/Preisqualität umstellen"}, {"id": "m16-n3b2", "text": "Value-Selling-Argumentarium"}], "children": []}, {"id": "m16-n4", "title": "Rollout", "isPriority": false, "bulletPoints": [{"id": "m16-n4b1", "text": "Preiserhöhung bei Neukunden zuerst"}, {"id": "m16-n4b2", "text": "Bestandskunden mit Mehrwert-Story migrieren"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie wird heute bepreist?", "a": "Preis pro Kurs und Teilnehmer mit hohen, individuell verhandelten Nachlässen — jeder Verkäufer entscheidet selbst."}, {"q": "Was deutet auf zu niedrige Preise hin?", "a": "Sehr hohe Win-Rates, kaum Preis-Einwände und Wettbewerber, die für Vergleichbares spürbar mehr verlangen."}, {"q": "Welchen Wert stiften die Kurse?", "a": "Sie erfüllen Pflichtfortbildungen und sparen Freistellungszeit — der Nutzen ist gut belegbar."}, {"q": "Gibt es Paket- oder Abomodelle?", "a": "Nein, nur Einzelkurse; einige Großkunden fragen nach Flatrates fürs ganze Haus."}, {"q": "Wie reagiert der Vertrieb auf Preisprojekte?", "a": "Skeptisch — die Provision hängt am Abschluss, nicht an der Marge."}]$J$::jsonb,
  $T$Underpricing-Diagnose: hohe Win-Rate + keine Einwände = klares Signal. Der Fix ist Architektur + Governance + Vertriebsanreize, nicht bloß 'Preise rauf'.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'pricing', $T$Dein Klient ist ein Theater- und Konzertveranstalter mit eigenem Haus (1.200 Plätze). Viele Vorstellungen sind halb leer, Top-Acts dagegen in Minuten ausverkauft. Der Intendant möchte die Preisstrategie überarbeiten, ohne das Publikum zu verärgern.$T$, NULL, $T$Pricing Framework$T$,
  $T$• Differenzierung nach Nachfrage: Dynamische Korridore je Vorstellung (früh günstig), Top-Acts: Premiumkategorien statt Zweitmarkt-Marge — Unteräste: Schwache Termine: Last-Minute, Zielgruppenaktionen
• Publikums- & Fairness-Logik: Sozial-/Jugendkontingente sichtbar erhalten, Abo-Vorteile schützen (Optik!)
• Produkt & Bundles: Pakete: Dinner, Garderobe, Premium-Seats, Serien-/Wahlabos für Gelegenheitsbesucher
• Umsetzung: Pilot-Sparten & A/B-Verkaufsfenster, Kommunikation: Mehrerlöse fördern Programm$T$,
  $J$[{"id": "m17-n1", "title": "Differenzierung nach Nachfrage", "isPriority": true, "bulletPoints": [{"id": "m17-n1b1", "text": "Dynamische Korridore je Vorstellung (früh günstig)"}, {"id": "m17-n1b2", "text": "Top-Acts: Premiumkategorien statt Zweitmarkt-Marge"}], "children": [{"id": "m17-n1c1", "title": "Schwache Termine: Last-Minute, Zielgruppenaktionen", "bulletPoints": [], "children": []}]}, {"id": "m17-n2", "title": "Publikums- & Fairness-Logik", "isPriority": false, "bulletPoints": [{"id": "m17-n2b1", "text": "Sozial-/Jugendkontingente sichtbar erhalten"}, {"id": "m17-n2b2", "text": "Abo-Vorteile schützen (Optik!)"}], "children": []}, {"id": "m17-n3", "title": "Produkt & Bundles", "isPriority": false, "bulletPoints": [{"id": "m17-n3b1", "text": "Pakete: Dinner, Garderobe, Premium-Seats"}, {"id": "m17-n3b2", "text": "Serien-/Wahlabos für Gelegenheitsbesucher"}], "children": []}, {"id": "m17-n4", "title": "Umsetzung", "isPriority": false, "bulletPoints": [{"id": "m17-n4b1", "text": "Pilot-Sparten & A/B-Verkaufsfenster"}, {"id": "m17-n4b2", "text": "Kommunikation: Mehrerlöse fördern Programm"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie wird heute bepreist?", "a": "Feste Preiskategorien nach Sitzplatz, identisch für alle Veranstaltungen einer Sparte."}, {"q": "Was passiert bei ausverkauften Shows?", "a": "Tickets landen zu Vielfachen auf Zweitmärkten — die Marge machen andere."}, {"q": "Wie preissensibel ist das Publikum?", "a": "Gemischt: Stammabonnenten reagieren empfindlich auf Optik, junges Publikum vergleicht mit Streaming und Kino."}, {"q": "Gibt es Fördervorgaben?", "a": "Ja, als teilgefördertes Haus muss Zugänglichkeit gewahrt bleiben — reine Gewinnmaximierung ist politisch heikel."}, {"q": "Welche Daten sind vorhanden?", "a": "Verkaufsverläufe je Vorstellung und historische Auslastung liegen vollständig vor."}]$J$::jsonb,
  $T$Revenue Management im Kulturkontext: Differenzieren ja, aber mit Fairness-Leitplanken (Förderauftrag, Abonnenten). Der Zweitmarkt-Hinweis ist der Hebel für Premium-Kategorien.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'operations', $T$Dein Klient ist ein Online-Händler für Autoteile. Kunden bestellen oft falsche Teile, die Retourenquote ist hoch und der Kundenservice ertrinkt in Anfragen zur Teile-Kompatibilität. Strukturiere die Verbesserung.$T$, NULL, $T$Operations Framework$T$,
  $T$• Fehlbestellungen verhindern: Fahrzeugidentifikation als Pflichtschritt (HSN/TSN, Kennzeichen), Kompatibilitätsdaten vollständig integrieren — Unteräste: Unsichere Fälle: geführte Beratung vor Kauf
• Retourenprozess: Ursachen-Codes erfassen & auswerten, Schnelle Abwicklung & Wiedereinlagerung
• Kundenservice entlasten: Self-Service: Passform-Checker, FAQ, Chatbot, Priorisierung & Routing der Anfragen
• Steuerung: KPI-Set: Fehlbestellquote, Kontaktrate, Retourenkosten, Feedback-Loop in Katalogpflege$T$,
  $J$[{"id": "m18-n1", "title": "Fehlbestellungen verhindern", "isPriority": true, "bulletPoints": [{"id": "m18-n1b1", "text": "Fahrzeugidentifikation als Pflichtschritt (HSN/TSN, Kennzeichen)"}, {"id": "m18-n1b2", "text": "Kompatibilitätsdaten vollständig integrieren"}], "children": [{"id": "m18-n1c1", "title": "Unsichere Fälle: geführte Beratung vor Kauf", "bulletPoints": [], "children": []}]}, {"id": "m18-n2", "title": "Retourenprozess", "isPriority": false, "bulletPoints": [{"id": "m18-n2b1", "text": "Ursachen-Codes erfassen & auswerten"}, {"id": "m18-n2b2", "text": "Schnelle Abwicklung & Wiedereinlagerung"}], "children": []}, {"id": "m18-n3", "title": "Kundenservice entlasten", "isPriority": false, "bulletPoints": [{"id": "m18-n3b1", "text": "Self-Service: Passform-Checker, FAQ, Chatbot"}, {"id": "m18-n3b2", "text": "Priorisierung & Routing der Anfragen"}], "children": []}, {"id": "m18-n4", "title": "Steuerung", "isPriority": false, "bulletPoints": [{"id": "m18-n4b1", "text": "KPI-Set: Fehlbestellquote, Kontaktrate, Retourenkosten"}, {"id": "m18-n4b2", "text": "Feedback-Loop in Katalogpflege"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie oft passen bestellte Teile nicht?", "a": "Ein erheblicher Teil der Retouren entsteht durch Kompatibilitätsfehler — Kunden wählen das falsche Teil fürs Fahrzeug."}, {"q": "Wie finden Kunden heute ihre Teile?", "a": "Über Suche und Kategorien; die Fahrzeug-Zuordnung ist unvollständig gepflegt und wird oft übersprungen."}, {"q": "Was kostet eine Retoure?", "a": "Versand, Prüfung, Wiedereinlagerung — bei margenschwachen Teilen frisst eine Retoure mehrere Verkäufe auf."}, {"q": "Womit kämpft der Kundenservice?", "a": "Vor allem Vorkauf-Fragen zur Passform und Nachkauf-Beschwerden — beides mit langen Antwortzeiten."}, {"q": "Welche Daten existieren?", "a": "Fahrzeugdatenbanken sind lizenziert, aber nur teilweise ins Shopsystem integriert."}]$J$::jsonb,
  $T$Ursache vor Symptom: Die Retouren- und Serviceflut entsteht im Bestellprozess (Kompatibilität). Wer Prävention strukturell vor Prozessoptimierung setzt, hat den Case verstanden.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'operations', $T$Dein Klient ist eine Möbelspedition mit 40 Fahrzeugen, spezialisiert auf Neumöbel-Auslieferung mit Montage. Kunden beschweren sich über geplatzte Termine, und die Touren schaffen weniger Stopps als kalkuliert. Analysiere strukturiert.$T$, NULL, $T$Operations Framework$T$,
  $T$• Planung & Kalkulation: Realistische Zeitmodelle je Auftrag (Etage, Volumen), Tourenoptimierung mit Software — Unteräste: Pufferlogik & dynamische Zeitfenster
• Ausführung & Qualität: Montage-Standards & Teamqualifikation, Nachbesserungsquote senken (Fotos, Checklisten)
• Kundenkommunikation: Echtzeit-Tracking & proaktive Verschiebe-Infos, Terminbestätigung digital
• Steuerung: KPIs: Stopps/Tour, First-Time-Right, Termintreue, Tagessteuerung durch Disposition$T$,
  $J$[{"id": "m19-n1", "title": "Planung & Kalkulation", "isPriority": true, "bulletPoints": [{"id": "m19-n1b1", "text": "Realistische Zeitmodelle je Auftrag (Etage, Volumen)"}, {"id": "m19-n1b2", "text": "Tourenoptimierung mit Software"}], "children": [{"id": "m19-n1c1", "title": "Pufferlogik & dynamische Zeitfenster", "bulletPoints": [], "children": []}]}, {"id": "m19-n2", "title": "Ausführung & Qualität", "isPriority": false, "bulletPoints": [{"id": "m19-n2b1", "text": "Montage-Standards & Teamqualifikation"}, {"id": "m19-n2b2", "text": "Nachbesserungsquote senken (Fotos, Checklisten)"}], "children": []}, {"id": "m19-n3", "title": "Kundenkommunikation", "isPriority": false, "bulletPoints": [{"id": "m19-n3b1", "text": "Echtzeit-Tracking & proaktive Verschiebe-Infos"}, {"id": "m19-n3b2", "text": "Terminbestätigung digital"}], "children": []}, {"id": "m19-n4", "title": "Steuerung", "isPriority": false, "bulletPoints": [{"id": "m19-n4b1", "text": "KPIs: Stopps/Tour, First-Time-Right, Termintreue"}, {"id": "m19-n4b2", "text": "Tagessteuerung durch Disposition"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie werden Termine heute vergeben?", "a": "Grobe Zeitfenster, telefonisch vereinbart — ohne Blick auf realistische Tourenreihenfolge."}, {"q": "Warum platzen Termine?", "a": "Montagen dauern länger als geplant, Fahrzeuge stehen im Stau, und es gibt keine Echtzeit-Information an die Kunden."}, {"q": "Wie wird die Montagezeit kalkuliert?", "a": "Pauschal je Möbeltyp — unabhängig von Aufwand vor Ort (Etage, Trageweg, Komplexität)."}, {"q": "Wie ist die Erstmontage-Qualität?", "a": "Nachbesserungen sind häufig und blockieren Folgetouren."}, {"q": "Welche Systeme sind im Einsatz?", "a": "Disposition weitgehend manuell in Excel; keine Telematik, keine Tourenoptimierung."}]$J$::jsonb,
  $T$Termintreue-Case: Wurzel ist die unrealistische Planung (Pauschalzeiten), nicht die Fahrer. Software-gestützte Disposition plus Qualitätsschleife sind die Kernhebel.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('medium', 'operations', $T$Dein Klient ist eine Stadtverwaltung, deren Bürgeramt Wartezeiten von mehreren Wochen für Termine hat (Ausweise, Ummeldungen). Der Oberbürgermeister will die Wartezeit drastisch senken — ohne nennenswert mehr Personal. Strukturiere die Analyse.$T$, NULL, $T$Operations Framework$T$,
  $T$• Nachfrage senken: Online-Services für digitalisierbare Anliegen, Abholung entkoppeln (Automaten, Direktausgabe) — Unteräste: No-Shows: Erinnerungen, Ein-Klick-Storno, Nachrückerliste
• Kapazität besser nutzen: Slot-Längen nach Anliegen differenzieren, Randzeiten/Samstag & Springer-Pools
• Prozess & Steuerung: Fallarten vorqualifizieren (Checklisten, Unterlagen), Echtzeit-Steuerung & Kennzahlen je Standort
• Umsetzung: Quick Wins zuerst (No-Show, Slots), Digitalisierung als 2. Welle$T$,
  $J$[{"id": "m20-n1", "title": "Nachfrage senken", "isPriority": true, "bulletPoints": [{"id": "m20-n1b1", "text": "Online-Services für digitalisierbare Anliegen"}, {"id": "m20-n1b2", "text": "Abholung entkoppeln (Automaten, Direktausgabe)"}], "children": [{"id": "m20-n1c1", "title": "No-Shows: Erinnerungen, Ein-Klick-Storno, Nachrückerliste", "bulletPoints": [], "children": []}]}, {"id": "m20-n2", "title": "Kapazität besser nutzen", "isPriority": false, "bulletPoints": [{"id": "m20-n2b1", "text": "Slot-Längen nach Anliegen differenzieren"}, {"id": "m20-n2b2", "text": "Randzeiten/Samstag & Springer-Pools"}], "children": []}, {"id": "m20-n3", "title": "Prozess & Steuerung", "isPriority": false, "bulletPoints": [{"id": "m20-n3b1", "text": "Fallarten vorqualifizieren (Checklisten, Unterlagen)"}, {"id": "m20-n3b2", "text": "Echtzeit-Steuerung & Kennzahlen je Standort"}], "children": []}, {"id": "m20-n4", "title": "Umsetzung", "isPriority": false, "bulletPoints": [{"id": "m20-n4b1", "text": "Quick Wins zuerst (No-Show, Slots)"}, {"id": "m20-n4b2", "text": "Digitalisierung als 2. Welle"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie entstehen die Wartezeiten?", "a": "Termin-Slots sind auf Wochen ausgebucht; gleichzeitig verfallen täglich viele Termine durch No-Shows."}, {"q": "Wie hoch ist die No-Show-Quote?", "a": "Zweistellig — Erinnerungen oder einfache Stornierung gibt es nicht."}, {"q": "Wie unterscheiden sich die Anliegen?", "a": "Von 5-Minuten-Abholungen bis zu komplexen Fällen — alle bekommen gleich lange Slots."}, {"q": "Was ist digital möglich?", "a": "Rechtlich könnten mehrere Anliegen komplett online erledigt werden — die Stadt bietet es nur nicht an."}, {"q": "Wie ist die Auslastung über den Tag?", "a": "Vormittags überlaufen, spätnachmittags Leerlauf; Samstage gibt es nicht."}]$J$::jsonb,
  $T$Public-Sector-Ops: Ohne Mehrpersonal zählt Nachfrage-Reduktion (online, No-Shows) vor Kapazitätsfeinschliff. Die No-Show-Quote ist der Sofort-Hebel — wer ihn findet, punktet.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'profitability', $T$Dein Klient ist eine Warenhauskette mit 35 Häusern in deutschen Innenstädten. Der Konzern verliert seit Jahren Geld; die Hälfte der Häuser ist defizitär, die Immobilien gehören teils dem Konzern, teils Vermietern. Der neue CEO will in 100 Tagen einen Sanierungsplan. Strukturiere ihn.$T$, NULL, $T$Profitability / Turnaround Framework$T$,
  $T$• Portfolio-Triage: Häuser clustern: halten, sanieren, schließen, Immobilienwert je Standort gegen Betriebsverlust stellen — Unteräste: Eigenimmobilien: verkaufen/umnutzen (Mixed-Use)
• Ertragsmodell je Haus: Flächenproduktivität: Sortimente, Untervermietung an Partner, Lokale Formate statt Einheitswarenhaus
• Kosten & Liquidität: Zentrale & Einkauf verschlanken, Mietverhandlungen mit Schließungsoption als Hebel
• Stakeholder-Fahrplan: Banken: Meilensteine & Reporting, Sozialplan & Kommunen-Kommunikation$T$,
  $J$[{"id": "h1-n1", "title": "Portfolio-Triage", "isPriority": true, "bulletPoints": [{"id": "h1-n1b1", "text": "Häuser clustern: halten, sanieren, schließen"}, {"id": "h1-n1b2", "text": "Immobilienwert je Standort gegen Betriebsverlust stellen"}], "children": [{"id": "h1-n1c1", "title": "Eigenimmobilien: verkaufen/umnutzen (Mixed-Use)", "bulletPoints": [], "children": []}]}, {"id": "h1-n2", "title": "Ertragsmodell je Haus", "isPriority": false, "bulletPoints": [{"id": "h1-n2b1", "text": "Flächenproduktivität: Sortimente, Untervermietung an Partner"}, {"id": "h1-n2b2", "text": "Lokale Formate statt Einheitswarenhaus"}], "children": []}, {"id": "h1-n3", "title": "Kosten & Liquidität", "isPriority": false, "bulletPoints": [{"id": "h1-n3b1", "text": "Zentrale & Einkauf verschlanken"}, {"id": "h1-n3b2", "text": "Mietverhandlungen mit Schließungsoption als Hebel"}], "children": []}, {"id": "h1-n4", "title": "Stakeholder-Fahrplan", "isPriority": false, "bulletPoints": [{"id": "h1-n4b1", "text": "Banken: Meilensteine & Reporting"}, {"id": "h1-n4b2", "text": "Sozialplan & Kommunen-Kommunikation"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie ist die Lage je Haus?", "a": "Sehr unterschiedlich: Ein Drittel solide, ein Drittel knapp negativ, ein Drittel tiefrot — Transparenz je Haus existiert, wird aber nicht genutzt."}, {"q": "Wem gehören die Immobilien?", "a": "Etwa die Hälfte Eigenbestand in teils besten Lagen; der Rest ist mit langen Verträgen gemietet."}, {"q": "Wie entwickelt sich der Umsatz?", "a": "Frequenz sinkt seit Jahren; online hat die Kette kaum Relevanz, Eigenmarken sind schwach."}, {"q": "Welche Stakeholder sind kritisch?", "a": "Gewerkschaft und Kommunen — Schließungen sind politisch aufgeladen; ein Sozialplan wäre teuer."}, {"q": "Wie viel Liquidität bleibt?", "a": "Etwa 18 Monate bei aktuellem Verlusttempo; die Banken verlangen den Plan als Bedingung für frische Linien."}]$J$::jsonb,
  $T$Sanierungs-Case mit Immobilien-Dimension: Die Triage je Haus inkl. Immobilienwert ist der Kern — Untervermietung/Umnutzung schlägt pauschales Sparen. Liquiditäts- und Stakeholder-Logik gehören in den 100-Tage-Plan.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'profitability', $T$Dein Klient ist ein Anbieter von Windpark-Wartung (O&M) in Europa. Trotz Rekord-Auftragsbestand sinkt die Marge drastisch. Verträge sind langfristig mit festen Preisen, die Kosten laufen davon. Der CEO braucht eine Struktur für das Margen-Rettungsprogramm.$T$, NULL, $T$Profitability Framework$T$,
  $T$• Vertragsportfolio: Marge je Vertrag: rot/gelb/grün clustern, Nachverhandlung: Index, Scope, Laufzeit-Deals — Unteräste: Neuverträge: Kalkulation & Risikoprämien fixen
• Servicekosten senken: Predictive Maintenance & Ferndiagnose skalieren, Techniker-Routen & Cluster-Einsätze
• Ersatzteile & Großkomponenten: Einkauf bündeln, Refurbishing nutzen, Bestands- vs. Verfügbarkeitsrisiko steuern
• Steuerung: Verfügbarkeits-Pönalen aktiv managen, Margen-Cockpit je Vertrag/Region$T$,
  $J$[{"id": "h2-n1", "title": "Vertragsportfolio", "isPriority": true, "bulletPoints": [{"id": "h2-n1b1", "text": "Marge je Vertrag: rot/gelb/grün clustern"}, {"id": "h2-n1b2", "text": "Nachverhandlung: Index, Scope, Laufzeit-Deals"}], "children": [{"id": "h2-n1c1", "title": "Neuverträge: Kalkulation & Risikoprämien fixen", "bulletPoints": [], "children": []}]}, {"id": "h2-n2", "title": "Servicekosten senken", "isPriority": false, "bulletPoints": [{"id": "h2-n2b1", "text": "Predictive Maintenance & Ferndiagnose skalieren"}, {"id": "h2-n2b2", "text": "Techniker-Routen & Cluster-Einsätze"}], "children": []}, {"id": "h2-n3", "title": "Ersatzteile & Großkomponenten", "isPriority": false, "bulletPoints": [{"id": "h2-n3b1", "text": "Einkauf bündeln, Refurbishing nutzen"}, {"id": "h2-n3b2", "text": "Bestands- vs. Verfügbarkeitsrisiko steuern"}], "children": []}, {"id": "h2-n4", "title": "Steuerung", "isPriority": false, "bulletPoints": [{"id": "h2-n4b1", "text": "Verfügbarkeits-Pönalen aktiv managen"}, {"id": "h2-n4b2", "text": "Margen-Cockpit je Vertrag/Region"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie sind die Verträge gestaltet?", "a": "Full-Service über 10-15 Jahre mit fixen, teils unzureichend indexierten Preisen und harten Verfügbarkeitsgarantien."}, {"q": "Welche Kosten laufen davon?", "a": "Technikerlöhne, Ersatzteile (v.a. Großkomponenten) und Anfahrten zu abgelegenen Parks."}, {"q": "Wie treffsicher ist die Kalkulation?", "a": "Alte Verträge wurden mit optimistischen Ausfallraten kalkuliert; die Flotte altert schneller als geplant."}, {"q": "Gibt es Nachverhandlungsspielraum?", "a": "Begrenzt — aber Indexklauseln, Scope-Änderungen und Laufzeitverlängerungen gegen Preisanpassung sind verhandelbar."}, {"q": "Wie ist die Einsatzplanung organisiert?", "a": "Regional fragmentiert; Ferndiagnose und predictive Ansätze stecken in Pilotprojekten."}]$J$::jsonb,
  $T$B2B-Service mit Altvertragsfalle: Vertragsportfolio-Triage plus Nachverhandlungshebel sind der Kern; operative Effizienz (predictive, Routen) flankiert. Wer nur Kosten senkt und die Verträge ignoriert, verfehlt die Hälfte.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'profitability', $T$Dein Klient ist eine Privatklinik-Gruppe für planbare Orthopädie-Eingriffe. Auslastung und Fallzahlen steigen, doch der Gewinn stagniert. Der CFO vermutet ein Fallmix-Problem und bittet dich um eine strukturierte Analyse.$T$, NULL, $T$Profitability / Pricing-Mix Framework$T$,
  $T$• Fallmix-Transparenz: Deckungsbeitrag je DRG/Fallart, Verweildauer- und Komplexitätstreiber — Unteräste: Zuweiser-Analyse: Woher kommen welche Fälle?
• Mix aktiv steuern: Standard-Eingriffe zurückgewinnen (Wartezeit, Pfade), Komplexfälle selektiv & korrekt kodiert
• Erlöse je Fall: Wahlleistungspakete modernisieren, Qualitäts-/Spezialverträge mit Kassen
• Kosten je Fall: OP-Effizienz & standardisierte Pfade, Sachkosten (Implantate) bündeln$T$,
  $J$[{"id": "h3-n1", "title": "Fallmix-Transparenz", "isPriority": true, "bulletPoints": [{"id": "h3-n1b1", "text": "Deckungsbeitrag je DRG/Fallart"}, {"id": "h3-n1b2", "text": "Verweildauer- und Komplexitätstreiber"}], "children": [{"id": "h3-n1c1", "title": "Zuweiser-Analyse: Woher kommen welche Fälle?", "bulletPoints": [], "children": []}]}, {"id": "h3-n2", "title": "Mix aktiv steuern", "isPriority": false, "bulletPoints": [{"id": "h3-n2b1", "text": "Standard-Eingriffe zurückgewinnen (Wartezeit, Pfade)"}, {"id": "h3-n2b2", "text": "Komplexfälle selektiv & korrekt kodiert"}], "children": []}, {"id": "h3-n3", "title": "Erlöse je Fall", "isPriority": false, "bulletPoints": [{"id": "h3-n3b1", "text": "Wahlleistungspakete modernisieren"}, {"id": "h3-n3b2", "text": "Qualitäts-/Spezialverträge mit Kassen"}], "children": []}, {"id": "h3-n4", "title": "Kosten je Fall", "isPriority": false, "bulletPoints": [{"id": "h3-n4b1", "text": "OP-Effizienz & standardisierte Pfade"}, {"id": "h3-n4b2", "text": "Sachkosten (Implantate) bündeln"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie verdient die Gruppe Geld?", "a": "DRG-Fallpauschalen plus Wahlleistungen (Chefarzt, Zimmer); die Pauschalen sind fix, die Kosten je Fall variieren stark."}, {"q": "Was hat sich im Fallmix geändert?", "a": "Mehr komplexe Revisionen und multimorbide Patienten mit langer Verweildauer — schlecht gedeckt in den Pauschalen."}, {"q": "Wie sind die OP-Ressourcen ausgelastet?", "a": "Voll — aber zunehmend mit margenschwachen Fällen; lukrative Standardeingriffe wandern zu Wettbewerbern mit kürzeren Wartezeiten."}, {"q": "Wie steht es um Wahlleistungen?", "a": "Rückläufig — Ansprache und Pakete sind veraltet."}, {"q": "Gibt es Verhandlungsmacht bei Kassen?", "a": "Punktuell, über Qualitätsverträge und Spezialisierungsausweise."}]$J$::jsonb,
  $T$Profitabilität im DRG-System = Fallmix-Steuerung: Deckungsbeitrag je Fallart ist die Schlüsselanalyse, Zuweiser-Management der unterschätzte Hebel. Wer nur 'Kosten senken' strukturiert, greift zu kurz.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'profitability', $T$Dein Klient ist ein SaaS-Unternehmen (Projektsteuerung für Bauträger) mit 40 Mio. € ARR, das jahrelang auf Wachstum getrimmt wurde. Die Investoren fordern jetzt 'profitables Wachstum': EBITDA-Break-even in 18 Monaten bei maximal halbiertem Wachstumstempo. Strukturiere das Programm.$T$, NULL, $T$Profitability Framework$T$,
  $T$• Wachstumseffizienz: CAC-Payback je Kanal/Segment — Budget umschichten, Fokus aufs Kernsegment (beste NRR) — Unteräste: Unprofitable Länder-Präsenzen schließen
• Monetarisierung: Preiserhöhung & Nutzungs-Tiers bei Bestand, Packaging: Add-ons statt Alles-inklusive
• Kostenstruktur: Roadmap fokussieren, Randprodukte einstellen, Support-Aufwand der Churn-Segmente reduzieren
• Programm-Steuerung: Break-even-Brücke: Maßnahmen quantifiziert, Meilensteine fürs Board, Rule of 40 als Leitplanke$T$,
  $J$[{"id": "h4-n1", "title": "Wachstumseffizienz", "isPriority": true, "bulletPoints": [{"id": "h4-n1b1", "text": "CAC-Payback je Kanal/Segment — Budget umschichten"}, {"id": "h4-n1b2", "text": "Fokus aufs Kernsegment (beste NRR)"}], "children": [{"id": "h4-n1c1", "title": "Unprofitable Länder-Präsenzen schließen", "bulletPoints": [], "children": []}]}, {"id": "h4-n2", "title": "Monetarisierung", "isPriority": false, "bulletPoints": [{"id": "h4-n2b1", "text": "Preiserhöhung & Nutzungs-Tiers bei Bestand"}, {"id": "h4-n2b2", "text": "Packaging: Add-ons statt Alles-inklusive"}], "children": []}, {"id": "h4-n3", "title": "Kostenstruktur", "isPriority": false, "bulletPoints": [{"id": "h4-n3b1", "text": "Roadmap fokussieren, Randprodukte einstellen"}, {"id": "h4-n3b2", "text": "Support-Aufwand der Churn-Segmente reduzieren"}], "children": []}, {"id": "h4-n4", "title": "Programm-Steuerung", "isPriority": false, "bulletPoints": [{"id": "h4-n4b1", "text": "Break-even-Brücke: Maßnahmen quantifiziert"}, {"id": "h4-n4b2", "text": "Meilensteine fürs Board, Rule of 40 als Leitplanke"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wo steht das Unternehmen heute?", "a": "ARR wächst ordentlich, EBITDA-Marge deutlich negativ — der Burn liegt im hohen einstelligen Millionenbereich pro Jahr."}, {"q": "Wo geht das Geld hin?", "a": "Größter Block: Vertrieb & Marketing mit langem CAC-Payback; dazu breite Produkt-Roadmap und internationale Mini-Präsenzen ohne Traktion."}, {"q": "Wie gesund ist die Kundenbasis?", "a": "Kernsegment mit exzellenter NRR; kleinere Kundensegmente churnen stark und binden Support."}, {"q": "Was ist tabu?", "a": "Kernprodukt-Qualität und das Enterprise-Segment — dort entsteht der Wert."}, {"q": "Wie belastbar ist die Preissetzung?", "a": "Preise seit Jahren unangetastet; Benchmarks zeigen Luft, besonders bei Bestandskunden mit hoher Nutzung."}]$J$::jsonb,
  $T$Growth-to-Profit-Pivot: Die Brücke zum Break-even muss aus konkreten, quantifizierten Blöcken bestehen (Effizienz, Pricing, Fokus). Rule-of-40-Denken und Segment-Schutz (Enterprise) zeigen Klasse.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'market_entry', $T$Dein Klient ist eine europäische Direktbank mit starkem Retail-Geschäft. Der Vorstand will in den Markt für Vermögensverwaltung einsteigen — konkret: digitale Vermögensverwaltung (Robo-Advisory) für die Massenaffluent-Kundschaft. Es gibt etablierte Robos, Banken und FinTechs. Strukturiere die Markteintrittsentscheidung.$T$, NULL, $T$Market Entry Framework (regulierter Markt)$T$,
  $T$• Strategische Logik: Bestandskunden-Hebel: Konversion statt teurer Akquise, Ertragsmodell: Gebühren, Volumen, Skaleneffekte
• Eintrittsmodell: Make vs. Buy vs. White-Label vergleichen, Time-to-Market & Kompetenzlücke bewerten — Unteräste: Zielbild: eigene Marke oder Sub-Brand
• Produkt & Kunde: Einfaches Produkt: ETF-Portfolios, klare Preise, Onboarding im Banking-App-Flow
• Regulatorik & Risiken: Geeignetheit & Produkt-Governance-Prozesse, Kannibalisierung Depot-/Sparprodukte prüfen$T$,
  $J$[{"id": "h5-n1", "title": "Strategische Logik", "isPriority": false, "bulletPoints": [{"id": "h5-n1b1", "text": "Bestandskunden-Hebel: Konversion statt teurer Akquise"}, {"id": "h5-n1b2", "text": "Ertragsmodell: Gebühren, Volumen, Skaleneffekte"}], "children": []}, {"id": "h5-n2", "title": "Eintrittsmodell", "isPriority": true, "bulletPoints": [{"id": "h5-n2b1", "text": "Make vs. Buy vs. White-Label vergleichen"}, {"id": "h5-n2b2", "text": "Time-to-Market & Kompetenzlücke bewerten"}], "children": [{"id": "h5-n2c1", "title": "Zielbild: eigene Marke oder Sub-Brand", "bulletPoints": [], "children": []}]}, {"id": "h5-n3", "title": "Produkt & Kunde", "isPriority": false, "bulletPoints": [{"id": "h5-n3b1", "text": "Einfaches Produkt: ETF-Portfolios, klare Preise"}, {"id": "h5-n3b2", "text": "Onboarding im Banking-App-Flow"}], "children": []}, {"id": "h5-n4", "title": "Regulatorik & Risiken", "isPriority": false, "bulletPoints": [{"id": "h5-n4b1", "text": "Geeignetheit & Produkt-Governance-Prozesse"}, {"id": "h5-n4b2", "text": "Kannibalisierung Depot-/Sparprodukte prüfen"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Warum will die Bank in diesen Markt?", "a": "Zinsüberschuss-Abhängigkeit reduzieren; Provisionserträge aus dem Bestand heben — Millionen Kunden parken Geld unverzinst."}, {"q": "Welche Assets bringt die Bank mit?", "a": "Große Bestandskundschaft mit App-Nutzung, Banklizenz, Vertrauen — aber keine Anlage-Beratungskompetenz im Haus."}, {"q": "Wie ist der Robo-Markt?", "a": "Die Pioniere wachsen langsam und verdienen wenig; Skalenerfordernis ist hoch, Kundengewinnung teuer."}, {"q": "Make, Buy oder Partner?", "a": "Alle Optionen offen: Eigenentwicklung, Übernahme eines Robos oder White-Label-Kooperation."}, {"q": "Welche regulatorischen Anforderungen gelten?", "a": "Geeignetheitsprüfung, Produkt-Governance und laufende Überwachung — mit Banklizenz machbar, aber prozessintensiv."}]$J$::jsonb,
  $T$Der Bestandskunden-Zugang ist das eigentliche Asset — die Eintrittsfrage ist primär Make/Buy/Partner unter Zeit- und Kompetenzgesichtspunkten. Wer Robo-Ökonomie (Skalenbedarf) versteht, argumentiert realistisch.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'market_entry', $T$Dein Klient ist ein führender Anbieter von Großküchentechnik. Er beobachtet den Boom von Dark Kitchens (reine Liefer-Küchen) und überlegt, neben dem Gerätegeschäft ein eigenes 'Kitchen-as-a-Service'-Angebot zu starten: voll ausgestattete Mietküchen für Gastronomen. Bewerte den Einstieg.$T$, NULL, $T$Market Entry Framework$T$,
  $T$• Marktattraktivität: Nachfrage je Stadt: Lieferdichte, Mietniveau, Wettbewerb & gescheiterte Modelle analysieren
• Geschäftsmodell-Design: Unit Economics je Modul: Miete, Auslastung, Laufzeit, Risikoteilung: Umsatzmiete vs. Fixmiete — Unteräste: Asset-light-Variante: Partner hält Immobilie
• Fit & Kannibalisierung: Synergien: Technik, Service, Daten, Kanalkonflikt mit Bestandskunden managen
• Pilot & Skalierung: 1-2 Städte, klare Erfolgskriterien, Exit-/Umnutzungsplan je Standort$T$,
  $J$[{"id": "h6-n1", "title": "Marktattraktivität", "isPriority": false, "bulletPoints": [{"id": "h6-n1b1", "text": "Nachfrage je Stadt: Lieferdichte, Mietniveau"}, {"id": "h6-n1b2", "text": "Wettbewerb & gescheiterte Modelle analysieren"}], "children": []}, {"id": "h6-n2", "title": "Geschäftsmodell-Design", "isPriority": true, "bulletPoints": [{"id": "h6-n2b1", "text": "Unit Economics je Modul: Miete, Auslastung, Laufzeit"}, {"id": "h6-n2b2", "text": "Risikoteilung: Umsatzmiete vs. Fixmiete"}], "children": [{"id": "h6-n2c1", "title": "Asset-light-Variante: Partner hält Immobilie", "bulletPoints": [], "children": []}]}, {"id": "h6-n3", "title": "Fit & Kannibalisierung", "isPriority": false, "bulletPoints": [{"id": "h6-n3b1", "text": "Synergien: Technik, Service, Daten"}, {"id": "h6-n3b2", "text": "Kanalkonflikt mit Bestandskunden managen"}], "children": []}, {"id": "h6-n4", "title": "Pilot & Skalierung", "isPriority": false, "bulletPoints": [{"id": "h6-n4b1", "text": "1-2 Städte, klare Erfolgskriterien"}, {"id": "h6-n4b2", "text": "Exit-/Umnutzungsplan je Standort"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie sieht das angedachte Modell aus?", "a": "Der Klient mietet Flächen, stattet sie mit eigener Technik aus und vermietet einsatzfertige Küchenmodule an Gastronomen und Liefermarken — inklusive Wartung."}, {"q": "Warum passt das zum Kerngeschäft?", "a": "Technik, Planung und Service sind Kernkompetenz; die Geräteauslastung eigener Module wäre zudem ein Schaufenster."}, {"q": "Wie entwickelt sich die Nachfrage?", "a": "Liefervolumina wachsen, aber mehrere Dark-Kitchen-Betreiber sind gescheitert — Überkapazitäten in einzelnen Städten."}, {"q": "Was sind die Hauptrisiken?", "a": "Immobilien-Fixkosten und Mieterausfall; das Geschäft ist näher an Real Estate als an Maschinenbau."}, {"q": "Wie reagiert der Vertrieb?", "a": "Gespalten — einige fürchten, künftig mit den eigenen Kunden (Küchenbauern, Betreibern) zu konkurrieren."}]$J$::jsonb,
  $T$Diversifikation Richtung Betreibermodell: Der Knackpunkt sind Unit Economics + Immobilienrisiko — asset-light-Strukturen und Risikoteilung unterscheiden reife von naiven Antworten.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'market_entry', $T$Dein Klient ist ein polnischer Hersteller von Fertighäusern in Holzbauweise mit exzellenter Kostenposition. Er will nach Deutschland expandieren, wo der Wohnungsbau kriselt, aber serielles Bauen politisch gefördert wird. Kommunen und Wohnungsgesellschaften suchen günstige Lösungen. Strukturiere den Markteintritt.$T$, NULL, $T$Market Entry / Geographic Expansion$T$,
  $T$• Segmentwahl: EFH-Privatkunden vs. serieller Wohnungsbau (B2G/B2B), Angebotslücke: günstiger Geschosswohnungsbau — Unteräste: Rahmenvereinbarungen als Eintrittstür
• Zulassung & Vertrauen: Bauartzulassungen & Zertifizierungen, Referenzprojekte mit Pilotkommunen
• Operatives Setup: Montage-/Bauleitungsteams in DE, Gewährleistung & Servicestruktur
• Wettbewerbsstrategie: Kostenführerschaft in Ausschreibungen ausspielen, Kapazitätssteuerung Werk Polen (Nachfrage-Peaks)$T$,
  $J$[{"id": "h7-n1", "title": "Segmentwahl", "isPriority": true, "bulletPoints": [{"id": "h7-n1b1", "text": "EFH-Privatkunden vs. serieller Wohnungsbau (B2G/B2B)"}, {"id": "h7-n1b2", "text": "Angebotslücke: günstiger Geschosswohnungsbau"}], "children": [{"id": "h7-n1c1", "title": "Rahmenvereinbarungen als Eintrittstür", "bulletPoints": [], "children": []}]}, {"id": "h7-n2", "title": "Zulassung & Vertrauen", "isPriority": false, "bulletPoints": [{"id": "h7-n2b1", "text": "Bauartzulassungen & Zertifizierungen"}, {"id": "h7-n2b2", "text": "Referenzprojekte mit Pilotkommunen"}], "children": []}, {"id": "h7-n3", "title": "Operatives Setup", "isPriority": false, "bulletPoints": [{"id": "h7-n3b1", "text": "Montage-/Bauleitungsteams in DE"}, {"id": "h7-n3b2", "text": "Gewährleistung & Servicestruktur"}], "children": []}, {"id": "h7-n4", "title": "Wettbewerbsstrategie", "isPriority": false, "bulletPoints": [{"id": "h7-n4b1", "text": "Kostenführerschaft in Ausschreibungen ausspielen"}, {"id": "h7-n4b2", "text": "Kapazitätssteuerung Werk Polen (Nachfrage-Peaks)"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was kann der Klient besser als deutsche Anbieter?", "a": "20-30% niedrigere Herstellkosten durch industrielle Fertigung und günstigere Löhne — bei solider Qualität."}, {"q": "Welche Segmente kommen infrage?", "a": "Einfamilienhäuser für Private oder serieller Mietwohnungsbau für kommunale Gesellschaften — zwei sehr unterschiedliche Spiele."}, {"q": "Welche Zulassungen braucht es?", "a": "Deutsche Bauartzulassungen und Nachweise; für seriellen Wohnungsbau gibt es Rahmenvereinbarungen (z.B. GdW), die Türen öffnen."}, {"q": "Wie wichtig ist lokale Präsenz?", "a": "Sehr: Montageteams, Bauleitung und Gewährleistung müssen vor Ort funktionieren — sonst kein Vertrauen."}, {"q": "Wie ist die Wettbewerbslage?", "a": "Deutsche Fertighaus-Anbieter sind im EFH-Premium stark; im günstigen Geschosswohnungsbau gibt es eine echte Angebotslücke."}]$J$::jsonb,
  $T$Segmentwahl entscheidet: Der kommunale Serienbau spielt die Kostenstärke aus und umgeht den Marken-Nachteil im Privatgeschäft. Zulassung + lokale Ausführung sind die Glaubwürdigkeits-Hürden.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'growth', $T$Dein Klient ist eine Baumarktkette mit 90 Märkten und solidem Online-Shop. Der Vorstand will das Servicegeschäft rund ums Wohnen ausbauen — von Handwerkervermittlung bis Mietgeräten — und diskutiert, ob man zur 'Home-Improvement-Plattform' werden soll. Strukturiere Wachstumsoptionen und Priorisierung.$T$, NULL, $T$Growth / Platform Framework$T$,
  $T$• Service-Portfolio: Mietgeräte flächig skalieren (Standardisierung), Montage-/Installationsservices produktisieren — Unteräste: Handwerkervermittlung: Qualität & Haftung klären
• Plattform-Logik: Buy/Build/Partner je Service, Digitale Buchung im Shop & Markt verzahnen
• Ökonomie & Machbarkeit: Deckungsbeitrag je Service, Frequenz-Effekt, Pilotmärkte & Skalierungskriterien
• Organisation: Service-Einheit mit eigener P&L, Partnernetz-Steuerung (SLAs, Bewertungen)$T$,
  $J$[{"id": "h8-n1", "title": "Service-Portfolio", "isPriority": true, "bulletPoints": [{"id": "h8-n1b1", "text": "Mietgeräte flächig skalieren (Standardisierung)"}, {"id": "h8-n1b2", "text": "Montage-/Installationsservices produktisieren"}], "children": [{"id": "h8-n1c1", "title": "Handwerkervermittlung: Qualität & Haftung klären", "bulletPoints": [], "children": []}]}, {"id": "h8-n2", "title": "Plattform-Logik", "isPriority": false, "bulletPoints": [{"id": "h8-n2b1", "text": "Buy/Build/Partner je Service"}, {"id": "h8-n2b2", "text": "Digitale Buchung im Shop & Markt verzahnen"}], "children": []}, {"id": "h8-n3", "title": "Ökonomie & Machbarkeit", "isPriority": false, "bulletPoints": [{"id": "h8-n3b1", "text": "Deckungsbeitrag je Service, Frequenz-Effekt"}, {"id": "h8-n3b2", "text": "Pilotmärkte & Skalierungskriterien"}], "children": []}, {"id": "h8-n4", "title": "Organisation", "isPriority": false, "bulletPoints": [{"id": "h8-n4b1", "text": "Service-Einheit mit eigener P&L"}, {"id": "h8-n4b2", "text": "Partnernetz-Steuerung (SLAs, Bewertungen)"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was läuft heute schon an Services?", "a": "Geräteverleih in einigen Märkten, punktuelle Montageservices über Subunternehmer — unkoordiniert und kaum vermarktet."}, {"q": "Was ist die strategische Motivation?", "a": "Produkte werden vergleichbar und margenschwach; Services versprechen Differenzierung, Frequenz und Daten."}, {"q": "Welche Assets hat die Kette?", "a": "Flächendeckende Standorte, Handwerker-Kundschaft, Sortimentskompetenz und hohes Kundenvertrauen."}, {"q": "Wie sieht der Wettbewerb aus?", "a": "Online-Plattformen vermitteln Handwerker, Hersteller bauen Direktservices — der Klient hat aber den physischen Zugang."}, {"q": "Welche Grenzen setzt der Vorstand?", "a": "Kein Kauf großer Plattformen; Aufbau muss aus eigener Kraft mit Partnern erfolgen."}]$J$::jsonb,
  $T$Vom Händler zum Service-Anbieter: Priorisierung nach Asset-Fit (Mietgeräte, Montage zuerst; Vermittlung mit Qualitätsrisiko später). Plattform-Rhetorik ohne Ökonomie je Service wäre die Falle.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'growth', $T$Dein Klient ist ein Spezialversicherer für Cyber-Risiken im Mittelstand. Der Markt wächst zweistellig, aber der Klient wächst langsamer als der Markt und die Schadenquoten steigen. Der CEO will profitabel Marktanteile gewinnen. Strukturiere die Wachstumsstrategie.$T$, NULL, $T$Growth Framework (B2B)$T$,
  $T$• Risikoselektion & Underwriting: Automatisierte Sicherheits-Scans im Antragsprozess, Preis- & Annahme-Differenzierung nach IT-Reife — Unteräste: Bestand sanieren: Nachbesserungen oder Kündigung
• Produkt & Prävention: Versicherung + Präventionsservices bündeln, Modulare Deckungen je Branche/Größe
• Vertrieb verbreitern: Maklernetz jenseits der Großmakler aktivieren, Embedded/Partner-Kanäle (IT-Dienstleister)
• Profitables Skalieren: Schadenquote als Wachstumsvoraussetzung (Rück-Kapazität), Kohorten-Monitoring & Preisagilität$T$,
  $J$[{"id": "h9-n1", "title": "Risikoselektion & Underwriting", "isPriority": true, "bulletPoints": [{"id": "h9-n1b1", "text": "Automatisierte Sicherheits-Scans im Antragsprozess"}, {"id": "h9-n1b2", "text": "Preis- & Annahme-Differenzierung nach IT-Reife"}], "children": [{"id": "h9-n1c1", "title": "Bestand sanieren: Nachbesserungen oder Kündigung", "bulletPoints": [], "children": []}]}, {"id": "h9-n2", "title": "Produkt & Prävention", "isPriority": false, "bulletPoints": [{"id": "h9-n2b1", "text": "Versicherung + Präventionsservices bündeln"}, {"id": "h9-n2b2", "text": "Modulare Deckungen je Branche/Größe"}], "children": []}, {"id": "h9-n3", "title": "Vertrieb verbreitern", "isPriority": false, "bulletPoints": [{"id": "h9-n3b1", "text": "Maklernetz jenseits der Großmakler aktivieren"}, {"id": "h9-n3b2", "text": "Embedded/Partner-Kanäle (IT-Dienstleister)"}], "children": []}, {"id": "h9-n4", "title": "Profitables Skalieren", "isPriority": false, "bulletPoints": [{"id": "h9-n4b1", "text": "Schadenquote als Wachstumsvoraussetzung (Rück-Kapazität)"}, {"id": "h9-n4b2", "text": "Kohorten-Monitoring & Preisagilität"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Warum wächst der Klient langsamer als der Markt?", "a": "Vertrieb läuft fast nur über wenige Großmakler; kleinere Makler und Direktkanäle sind unbearbeitet."}, {"q": "Was treibt die Schadenquote?", "a": "Ransomware-Wellen und Kunden mit schwacher IT-Hygiene — die Risikoprüfung ist oberflächlich."}, {"q": "Wie ist das Produkt aufgestellt?", "a": "Eine Einheitspolice; Prävention (Monitoring, Schulungen) wird nicht angeboten."}, {"q": "Was machen Wettbewerber?", "a": "InsurTechs koppeln Versicherung an Sicherheits-Scans und Präventionsdienste — mit besseren Quoten."}, {"q": "Welche Kapazitäten gibt es?", "a": "Rückversicherung ist gesichert, aber nur bei nachweislich verbesserter Risikoselektion ausbaubar."}]$J$::jsonb,
  $T$Wachstum und Schadenquote hängen hier zusammen: Ohne bessere Risikoselektion keine Kapazität. Prävention als Produktbestandteil ist der strategische Zug, Vertriebsverbreiterung der Volumenhebel.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'growth', $T$Dein Klient ist ein D2C-Kosmetikunternehmen (vegane Hautpflege) mit 60 Mio. € Umsatz, stark auf Instagram/TikTok gewachsen. Das DACH-Wachstum flacht ab, Paid-Social wird teurer. Der Beirat fordert einen Plan: In drei Jahren 150 Mio. € Umsatz. Strukturiere die Wachstumsstrategie.$T$, NULL, $T$Growth / Internationalisierung$T$,
  $T$• Kanal-Expansion: Retail-Eintritt (Drogerie): Reichweite vs. Margen-/Kanalkonflikt, Amazon & Marktplätze kontrolliert — Unteräste: D2C-Effizienz: CRM, Abo, Community statt Paid-Only
• Sortiment & Preisarchitektur: Kategorie-Erweiterung (Körper, Sonne), Hero-Produkte & Bundles für AOV
• Internationalisierung: 1-2 EU-Märkte mit Playbook (nicht flächig), Lokalisierung: Influencer, Regulatorik
• Zielpfad 150 Mio.: Wachstumsbrücke je Hebel quantifizieren, Meilensteine & Investitionsbedarf$T$,
  $J$[{"id": "h10-n1", "title": "Kanal-Expansion", "isPriority": true, "bulletPoints": [{"id": "h10-n1b1", "text": "Retail-Eintritt (Drogerie): Reichweite vs. Margen-/Kanalkonflikt"}, {"id": "h10-n1b2", "text": "Amazon & Marktplätze kontrolliert"}], "children": [{"id": "h10-n1c1", "title": "D2C-Effizienz: CRM, Abo, Community statt Paid-Only", "bulletPoints": [], "children": []}]}, {"id": "h10-n2", "title": "Sortiment & Preisarchitektur", "isPriority": false, "bulletPoints": [{"id": "h10-n2b1", "text": "Kategorie-Erweiterung (Körper, Sonne)"}, {"id": "h10-n2b2", "text": "Hero-Produkte & Bundles für AOV"}], "children": []}, {"id": "h10-n3", "title": "Internationalisierung", "isPriority": false, "bulletPoints": [{"id": "h10-n3b1", "text": "1-2 EU-Märkte mit Playbook (nicht flächig)"}, {"id": "h10-n3b2", "text": "Lokalisierung: Influencer, Regulatorik"}], "children": []}, {"id": "h10-n4", "title": "Zielpfad 150 Mio.", "isPriority": false, "bulletPoints": [{"id": "h10-n4b1", "text": "Wachstumsbrücke je Hebel quantifizieren"}, {"id": "h10-n4b2", "text": "Meilensteine & Investitionsbedarf"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Woher kommt das heutige Geschäft?", "a": "Fast alles D2C online in DACH; Retail nur ein Testlisting, internationale Umsätze minimal."}, {"q": "Wie entwickeln sich die Marketingkosten?", "a": "CAC über Paid Social hat sich in zwei Jahren fast verdoppelt; organische Reichweite trägt noch, skaliert aber nicht beliebig."}, {"q": "Wie stark ist die Marke?", "a": "In der Zielgruppe DACH sehr stark (Community, Wiederkauf); außerhalb unbekannt."}, {"q": "Was ist mit Retail?", "a": "Drogerieketten haben Interesse signalisiert — der Beirat ist gespalten (Marge vs. Reichweite)."}, {"q": "Wie sieht das Sortiment aus?", "a": "Fokussiert auf Gesichtspflege; Körperpflege, Sonnenschutz und Männerlinie fehlen."}]$J$::jsonb,
  $T$Die 150-Mio.-Brücke braucht mehrere Hebel: Retail ist der große Reichweiten-Schritt (Kanalkonflikt abwägen!), plus Sortiment und selektive Internationalisierung. Eine quantifizierte Brücke adelt die Antwort.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'growth', $T$Dein Klient ist ein Landmaschinenhändler-Verbund (12 Standorte), der Traktoren und Erntemaschinen eines großen Herstellers vertreibt. Neumaschinen-Margen sinken, Landwirte investieren zögerlicher. Der Verbund sucht Wachstum jenseits des Neumaschinenverkaufs. Entwickle die Struktur.$T$, NULL, $T$Growth / Ecosystem Framework$T$,
  $T$• Service & Aftermarket: Wartungsverträge & Winter-Checks systematisieren, Ersatzteil-Verfügbarkeit & Express-Logistik — Unteräste: Flottenbestand aktiv managen (wer fährt was, wann fällig)
• Miete & Gebraucht: Mietflotte für Erntespitzen aufbauen, Gebraucht professionalisieren (Ankauf, Aufbereitung, Export)
• Precision-Farming-Dienste: Nachrüstung, Einrichtung, Schulung als Service, Datendienste mit Hersteller bündeln
• Struktur & Skalierung: Verbund-Synergien: Zentrale Disposition, Einkauf, Zukauf kleiner Händler (Konsolidierung)$T$,
  $J$[{"id": "h11-n1", "title": "Service & Aftermarket", "isPriority": true, "bulletPoints": [{"id": "h11-n1b1", "text": "Wartungsverträge & Winter-Checks systematisieren"}, {"id": "h11-n1b2", "text": "Ersatzteil-Verfügbarkeit & Express-Logistik"}], "children": [{"id": "h11-n1c1", "title": "Flottenbestand aktiv managen (wer fährt was, wann fällig)", "bulletPoints": [], "children": []}]}, {"id": "h11-n2", "title": "Miete & Gebraucht", "isPriority": false, "bulletPoints": [{"id": "h11-n2b1", "text": "Mietflotte für Erntespitzen aufbauen"}, {"id": "h11-n2b2", "text": "Gebraucht professionalisieren (Ankauf, Aufbereitung, Export)"}], "children": []}, {"id": "h11-n3", "title": "Precision-Farming-Dienste", "isPriority": false, "bulletPoints": [{"id": "h11-n3b1", "text": "Nachrüstung, Einrichtung, Schulung als Service"}, {"id": "h11-n3b2", "text": "Datendienste mit Hersteller bündeln"}], "children": []}, {"id": "h11-n4", "title": "Struktur & Skalierung", "isPriority": false, "bulletPoints": [{"id": "h11-n4b1", "text": "Verbund-Synergien: Zentrale Disposition, Einkauf"}, {"id": "h11-n4b2", "text": "Zukauf kleiner Händler (Konsolidierung)"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie verteilt sich das Geschäft heute?", "a": "Großteil Neumaschinen (margenschwach), dazu Werkstatt, Ersatzteile und etwas Gebrauchtgeschäft — Service ist profitabel, aber unterentwickelt."}, {"q": "Wie ist die Kundenbindung?", "a": "Über den Standort stark, aber unsystematisch: keine Wartungsverträge, kein aktives Bestandsmanagement der Maschinenflotte."}, {"q": "Welche Trends verändern den Markt?", "a": "Precision Farming (GPS, Datendienste), Miet-/Sharing-Modelle für teure Erntetechnik und wachsender Gebrauchtmarkt."}, {"q": "Was erlaubt der Hersteller?", "a": "Service, Gebraucht, Vermietung und Datendienste sind frei gestaltbar; Fremdmarken im Neugeschäft nicht."}, {"q": "Wie ist die Kapitallage?", "a": "Solide — Investitionen in Mietflotte oder Übernahmen kleinerer Händler sind möglich."}]$J$::jsonb,
  $T$Vom Verkäufer zum Lebenszyklus-Partner: Service-Systematisierung ist der sichere Kern, Miete/Gebraucht und Precision-Dienste die Wachstumsflächen. Herstellergrenzen (kein Fremd-Neugeschäft) beachten.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'ma', $T$Dein Klient ist ein Chemiekonzern, der sein margenschwaches Additiv-Geschäft (600 Mio. € Umsatz) verkaufen will. Interessenten: ein Wettbewerber und zwei PE-Fonds. Das Geschäft teilt Standorte, IT und Vertrieb mit dem Konzern. Strukturiere Verkaufsvorbereitung und Prozess.$T$, NULL, $T$M&A / Carve-out Framework$T$,
  $T$• Carve-out-Design: Perimeter: Was gehört dazu (Anlagen, Patente, Leute)?, Standalone-Kosten & TSAs (IT, Standort, Vertrieb) — Unteräste: Entflechtungs-Roadmap vor Signing
• Equity Story & Wert: Kostenpotenzial als Upside dokumentieren, Bewertungsspanne & Stapled-Finanzierung
• Prozess & Bieter: Stratege (Synergien, Kartellrisiko) vs. PE (Preis, TSA-Appetit), Wettbewerblicher Prozess, saubere Datenraum-Basis
• Stakeholder & Kontinuität: Key Accounts: Lieferbeziehungen absichern, Betriebsrat & Standortvereinbarungen$T$,
  $J$[{"id": "h12-n1", "title": "Carve-out-Design", "isPriority": true, "bulletPoints": [{"id": "h12-n1b1", "text": "Perimeter: Was gehört dazu (Anlagen, Patente, Leute)?"}, {"id": "h12-n1b2", "text": "Standalone-Kosten & TSAs (IT, Standort, Vertrieb)"}], "children": [{"id": "h12-n1c1", "title": "Entflechtungs-Roadmap vor Signing", "bulletPoints": [], "children": []}]}, {"id": "h12-n2", "title": "Equity Story & Wert", "isPriority": false, "bulletPoints": [{"id": "h12-n2b1", "text": "Kostenpotenzial als Upside dokumentieren"}, {"id": "h12-n2b2", "text": "Bewertungsspanne & Stapled-Finanzierung"}], "children": []}, {"id": "h12-n3", "title": "Prozess & Bieter", "isPriority": false, "bulletPoints": [{"id": "h12-n3b1", "text": "Stratege (Synergien, Kartellrisiko) vs. PE (Preis, TSA-Appetit)"}, {"id": "h12-n3b2", "text": "Wettbewerblicher Prozess, saubere Datenraum-Basis"}], "children": []}, {"id": "h12-n4", "title": "Stakeholder & Kontinuität", "isPriority": false, "bulletPoints": [{"id": "h12-n4b1", "text": "Key Accounts: Lieferbeziehungen absichern"}, {"id": "h12-n4b2", "text": "Betriebsrat & Standortvereinbarungen"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Warum wird verkauft?", "a": "Portfolio-Fokus auf Hochmargen-Spezialitäten; das Additiv-Geschäft braucht Investitionen, die der Konzern woanders einsetzen will."}, {"q": "Wie verflochten ist das Geschäft?", "a": "Stark: Zwei von vier Produktionslinien teilen Standorte, Vertrieb läuft über gemeinsame Key Accounts, IT/ERP ist konzernweit."}, {"q": "Was bedeutet das für den Verkauf?", "a": "Ohne Carve-out-Konzept (Standalone-Kosten, Übergangsverträge) sind Bewertungen der Bieter kaum belastbar."}, {"q": "Wie performt das Geschäft?", "a": "Stabile Umsätze, Marge unter Konzernschnitt — mit klarem Kostensenkungspotenzial, das der Konzern nie priorisiert hat."}, {"q": "Welche Sensibilitäten gibt es?", "a": "Kunden-Doppelbeziehungen (kaufen auch andere Konzernprodukte) und Betriebsrats-Themen an geteilten Standorten."}]$J$::jsonb,
  $T$Carve-out-Verkauf: Ohne Perimeter/TSA-Klarheit keine validen Gebote — das ist der Kern. Bieter-Differenzierung (Stratege vs. PE) und Kundenkontinuität runden die Struktur ab.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'ma', $T$Dein Klient ist ein Energieversorger, der mit einem Immobilienkonzern ein Joint Venture für Mieterstrom und Gebäude-Photovoltaik gründen will. Beide bringen Assets ein, die Governance ist strittig. Bewerte das Vorhaben und strukturiere die JV-Entscheidung.$T$, NULL, $T$M&A / Joint Venture Framework$T$,
  $T$• Strategische Logik: Komplementarität der Assets prüfen, Marktpotenzial & Rollout-Geschwindigkeit
• JV-Design: Governance: Anteile, Vetos, Deadlock-Mechanismen, Exklusivität & Drittgeschäft regeln — Unteräste: Einbringungswerte fair bewerten
• Ökonomie & Risiken: Business Case je Objekt & Skalenpfad, Regulatorik-Szenarien (Förderung ändert sich)
• Alternativen & Exit: JV vs. Vertragsmodell vergleichen, Exit-/Buy-out-Klauseln von Anfang an$T$,
  $J$[{"id": "h13-n1", "title": "Strategische Logik", "isPriority": false, "bulletPoints": [{"id": "h13-n1b1", "text": "Komplementarität der Assets prüfen"}, {"id": "h13-n1b2", "text": "Marktpotenzial & Rollout-Geschwindigkeit"}], "children": []}, {"id": "h13-n2", "title": "JV-Design", "isPriority": true, "bulletPoints": [{"id": "h13-n2b1", "text": "Governance: Anteile, Vetos, Deadlock-Mechanismen"}, {"id": "h13-n2b2", "text": "Exklusivität & Drittgeschäft regeln"}], "children": [{"id": "h13-n2c1", "title": "Einbringungswerte fair bewerten", "bulletPoints": [], "children": []}]}, {"id": "h13-n3", "title": "Ökonomie & Risiken", "isPriority": false, "bulletPoints": [{"id": "h13-n3b1", "text": "Business Case je Objekt & Skalenpfad"}, {"id": "h13-n3b2", "text": "Regulatorik-Szenarien (Förderung ändert sich)"}], "children": []}, {"id": "h13-n4", "title": "Alternativen & Exit", "isPriority": false, "bulletPoints": [{"id": "h13-n4b1", "text": "JV vs. Vertragsmodell vergleichen"}, {"id": "h13-n4b2", "text": "Exit-/Buy-out-Klauseln von Anfang an"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was soll das JV konkret machen?", "a": "PV-Anlagen auf den Beständen des Immobilienpartners bauen und Mieterstrom vermarkten — später Drittkunden."}, {"q": "Was bringt jede Seite ein?", "a": "Der Versorger: Technik, Energiehandel, Abrechnung, Regulatorik-Know-how. Der Immobilienkonzern: Dachflächen, Mieterzugang, Kapitalanteil."}, {"q": "Wo hakt die Governance?", "a": "Beide wollen 51% und den CEO stellen; strittig sind auch Exklusivität und Drittgeschäft."}, {"q": "Wie attraktiv ist die Ökonomie?", "a": "Solide Renditen je Objekt, aber stark abhängig von Regulatorik (Mieterstromzuschlag) und Skaleneffekten im Rollout."}, {"q": "Was wäre die Alternative zum JV?", "a": "Ein reiner Liefer-/Dienstleistungsvertrag ohne gemeinsame Gesellschaft — weniger Upside, weniger Konfliktpotenzial."}]$J$::jsonb,
  $T$JV-Cases entscheiden sich am Design: Governance (Deadlock!), Exklusivität und Exit-Klauseln sind wichtiger als die reine Marktstory. Die Vertragsalternative als BATNA zeigt Verhandlungsreife.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'ma', $T$Dein Klient ist ein börsennotierter Personaldienstleister. Um dem Margendruck zu entgehen, will der CEO eine HR-Tech-Plattform (Freelancer-Management-System, 25 Mio. € ARR, wachstumsstark, unprofitabel) für einen hohen Preis übernehmen. Der Aufsichtsrat ist skeptisch. Strukturiere die Entscheidungsvorlage.$T$, NULL, $T$M&A Framework (Tech-Akquisition)$T$,
  $T$• Strategische These prüfen: Zielbild: Dienstleister mit Software oder Software-Firma?, Synergien hart quantifizieren (Cross-Sell, Eigenumsatz) — Unteräste: Lehren aus gescheiterten Digital-Zukäufen
• Target-Qualität: Produkt, Kohorten, Churn, Burn, Gründerbindung & Schlüsselteam
• Preis & Struktur: Bewertung vs. SaaS-Benchmarks, Earn-out, Kapitalmarkt-Story (Verwässerung, Guidance)
• Integrationsmodell: Standalone mit Brücken statt Vollintegration, Governance & Anreize fürs Zielteam$T$,
  $J$[{"id": "h14-n1", "title": "Strategische These prüfen", "isPriority": true, "bulletPoints": [{"id": "h14-n1b1", "text": "Zielbild: Dienstleister mit Software oder Software-Firma?"}, {"id": "h14-n1b2", "text": "Synergien hart quantifizieren (Cross-Sell, Eigenumsatz)"}], "children": [{"id": "h14-n1c1", "title": "Lehren aus gescheiterten Digital-Zukäufen", "bulletPoints": [], "children": []}]}, {"id": "h14-n2", "title": "Target-Qualität", "isPriority": false, "bulletPoints": [{"id": "h14-n2b1", "text": "Produkt, Kohorten, Churn, Burn"}, {"id": "h14-n2b2", "text": "Gründerbindung & Schlüsselteam"}], "children": []}, {"id": "h14-n3", "title": "Preis & Struktur", "isPriority": false, "bulletPoints": [{"id": "h14-n3b1", "text": "Bewertung vs. SaaS-Benchmarks, Earn-out"}, {"id": "h14-n3b2", "text": "Kapitalmarkt-Story (Verwässerung, Guidance)"}], "children": []}, {"id": "h14-n4", "title": "Integrationsmodell", "isPriority": false, "bulletPoints": [{"id": "h14-n4b1", "text": "Standalone mit Brücken statt Vollintegration"}, {"id": "h14-n4b2", "text": "Governance & Anreize fürs Zielteam"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was ist die strategische These?", "a": "Verschiebung vom margenschwachen Verleihgeschäft zur skalierbaren Software — die Plattform würde Kunden und Freelancer digital binden."}, {"q": "Warum ist der Aufsichtsrat skeptisch?", "a": "Preis (zweistelliges ARR-Multiple), Kulturunterschied und die Historie: Zwei frühere Digital-Zukäufe sind gescheitert."}, {"q": "Wie solide ist das Target?", "a": "Starkes Produkt, gute Kundenbindung, aber hoher Burn und Abhängigkeit vom Gründerteam."}, {"q": "Welche Synergien sind realistisch?", "a": "Cross-Sell in die Konzern-Kundenbasis und Nutzung der Plattform für den eigenen Freelancer-Pool — quantifiziert hat das noch niemand."}, {"q": "Wie soll integriert werden?", "a": "Offen — von voller Integration bis 'Standalone mit Brücken' ist alles denkbar."}]$J$::jsonb,
  $T$Transformation-durch-Akquisition: Die Entscheidungsvorlage braucht harte Synergie-Quantifizierung und ein Integrationsmodell, das das Asset nicht zerstört (Standalone-Logik). Die gescheiterte Historie explizit adressieren.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'pricing', $T$Dein Klient ist ein Verkehrsverbund, der ein neues Tarifsystem einführen will: weg vom Zonen-Dschungel, hin zu einem einfachen, digitalen Modell (Luftlinien- oder Capping-Tarif). Ziel: mehr Fahrgäste, stabile Einnahmen, politische Zustimmung. Strukturiere die Tarifreform.$T$, NULL, $T$Pricing / Monetization Framework$T$,
  $T$• Tarifdesign: Modelle vergleichen: Luftlinie vs. Capping, Einfachheit als Kernziel (verstehbar in 1 Satz) — Unteräste: Preispunkte & Capping-Schwellen kalibrieren
• Einnahmen-Simulation: Gewinner/Verlierer-Analysen je Kundengruppe, Elastizität: Mehrfahrten vs. Preis je Fahrt
• Zugänglichkeit & Fairness: Nicht-Digital-Lösungen (Karte, Vertrieb), Sozialtarife & Pendler-Schutz
• Politik & Umsetzung: Pilotphase & transparente Evaluation, Ausgleichsmechanik zwischen Verbundpartnern$T$,
  $J$[{"id": "h15-n1", "title": "Tarifdesign", "isPriority": true, "bulletPoints": [{"id": "h15-n1b1", "text": "Modelle vergleichen: Luftlinie vs. Capping"}, {"id": "h15-n1b2", "text": "Einfachheit als Kernziel (verstehbar in 1 Satz)"}], "children": [{"id": "h15-n1c1", "title": "Preispunkte & Capping-Schwellen kalibrieren", "bulletPoints": [], "children": []}]}, {"id": "h15-n2", "title": "Einnahmen-Simulation", "isPriority": false, "bulletPoints": [{"id": "h15-n2b1", "text": "Gewinner/Verlierer-Analysen je Kundengruppe"}, {"id": "h15-n2b2", "text": "Elastizität: Mehrfahrten vs. Preis je Fahrt"}], "children": []}, {"id": "h15-n3", "title": "Zugänglichkeit & Fairness", "isPriority": false, "bulletPoints": [{"id": "h15-n3b1", "text": "Nicht-Digital-Lösungen (Karte, Vertrieb)"}, {"id": "h15-n3b2", "text": "Sozialtarife & Pendler-Schutz"}], "children": []}, {"id": "h15-n4", "title": "Politik & Umsetzung", "isPriority": false, "bulletPoints": [{"id": "h15-n4b1", "text": "Pilotphase & transparente Evaluation"}, {"id": "h15-n4b2", "text": "Ausgleichsmechanik zwischen Verbundpartnern"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Was ist am heutigen System das Problem?", "a": "Dutzende Zonen und Ticketarten — Gelegenheitskunden verstehen es nicht und fahren seltener oder schwarz."}, {"q": "Welche Modelle stehen zur Debatte?", "a": "Luftlinien-Preis je Fahrt oder Check-in/Check-out mit Tages-/Monats-Capping wie in London."}, {"q": "Welche Einnahmen-Restriktion gilt?", "a": "Die Einnahmen der Verbundpartner dürfen im Übergangsjahr höchstens leicht sinken — es gibt einen Ausgleichsmechanismus."}, {"q": "Wie ist die digitale Ausstattung?", "a": "Die App ist verbreitet, aber Barzahler und Senioren müssen weiter bedient werden."}, {"q": "Wer entscheidet am Ende?", "a": "Die Verbandsversammlung der Kommunen — politische Vermittelbarkeit ist ein hartes Kriterium."}]$J$::jsonb,
  $T$Tarifreform = Pricing unter politischen Nebenbedingungen: Einnahmen-Simulation mit Gewinner/Verlierer-Logik ist Pflicht, Einfachheit das Leitkriterium. Wer Nicht-Digital-Kunden vergisst, scheitert politisch.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'pricing', $T$Dein Klient ist ein Zulieferer für die Lebensmittelindustrie (Aromen und Extrakte). Der größte Kunde — ein multinationaler Konzern — fordert in der Jahresverhandlung 8% Preissenkung und droht mit Dual Sourcing. Der Klient hat selbst Kostensteigerungen. Strukturiere Verhandlungsstrategie und Preisarchitektur.$T$, NULL, $T$Pricing Framework (B2B-Verhandlung)$T$,
  $T$• Verhandlungs-Vorbereitung: Produkt-Matrix: substituierbar vs. designed-in, Eigene BATNA & Kundenkosten eines Wechsels — Unteräste: Verhandlungsziele & Walk-away je Produktgruppe
• Preisarchitektur: Differenzierte Antwort statt pauschal -8%, Indexierung (Rohstoffe) & Gleitklauseln einbauen
• Wert statt Preis: Effizienz-/Reformulierungsprojekte anbieten, Bündelung, Laufzeit, Exklusivität als Währung
• Risiko & Nachspiel: Dual-Sourcing-Szenario planen (Kapazität, Mix), Kundenabhängigkeit mittelfristig senken$T$,
  $J$[{"id": "h16-n1", "title": "Verhandlungs-Vorbereitung", "isPriority": true, "bulletPoints": [{"id": "h16-n1b1", "text": "Produkt-Matrix: substituierbar vs. designed-in"}, {"id": "h16-n1b2", "text": "Eigene BATNA & Kundenkosten eines Wechsels"}], "children": [{"id": "h16-n1c1", "title": "Verhandlungsziele & Walk-away je Produktgruppe", "bulletPoints": [], "children": []}]}, {"id": "h16-n2", "title": "Preisarchitektur", "isPriority": false, "bulletPoints": [{"id": "h16-n2b1", "text": "Differenzierte Antwort statt pauschal -8%"}, {"id": "h16-n2b2", "text": "Indexierung (Rohstoffe) & Gleitklauseln einbauen"}], "children": []}, {"id": "h16-n3", "title": "Wert statt Preis", "isPriority": false, "bulletPoints": [{"id": "h16-n3b1", "text": "Effizienz-/Reformulierungsprojekte anbieten"}, {"id": "h16-n3b2", "text": "Bündelung, Laufzeit, Exklusivität als Währung"}], "children": []}, {"id": "h16-n4", "title": "Risiko & Nachspiel", "isPriority": false, "bulletPoints": [{"id": "h16-n4b1", "text": "Dual-Sourcing-Szenario planen (Kapazität, Mix)"}, {"id": "h16-n4b2", "text": "Kundenabhängigkeit mittelfristig senken"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie wichtig ist der Kunde?", "a": "Rund 25% des Umsatzes über mehrere Werke und Rezepturen — ein Verlust wäre schwer, aber nicht existenzbedrohend."}, {"q": "Wie austauschbar sind die Produkte?", "a": "Gemischt: Einige Standard-Extrakte sind substituierbar, mehrere Schlüsselaromen sind in Kundenrezepturen designt und qualifiziert — ein Wechsel dauert dort 12-18 Monate."}, {"q": "Wie ist die eigene Kostenlage?", "a": "Rohstoffe und Energie deutlich gestiegen; die aktuelle Kundenmarge ist bereits unter Portfolio-Schnitt."}, {"q": "Was weiß man über die Gegenseite?", "a": "Der Einkauf fährt ein konzernweites Kostenprogramm; Qualität und Liefertreue des Klienten werden intern hoch geschätzt."}, {"q": "Welche Zugeständnisse wären denkbar?", "a": "Volumenbündelung, längere Laufzeiten, gemeinsame Effizienzprojekte — reine Preisnachlässe will der CEO vermeiden."}]$J$::jsonb,
  $T$B2B-Preisverhandlung: Die Produkt-Matrix (wo hat wer Macht?) ist das Herzstück — pauschale Zugeständnisse sind der Fehler. Wert-Zugeständnisse statt Preis und Indexierung zeigen Pricing-Reife.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'pricing', $T$Dein Klient betreibt eine Fitness- und Ernährungs-App mit 4 Mio. registrierten Nutzern, davon zahlen 3% für Premium. Investoren fordern deutlich mehr Umsatz. Das Team streitet: Paywall härter ziehen, Preise erhöhen oder Werbung einführen? Strukturiere die Monetarisierungsstrategie.$T$, NULL, $T$Pricing / Freemium Framework$T$,
  $T$• Freemium-Architektur: Free/Premium-Grenze neu ziehen (Wert vs. Viralität), Conversion-Momente gezielt monetarisieren (Pläne) — Unteräste: A/B-Roadmap statt Big-Bang-Paywall
• Preis & Pakete: Preistests je Markt/Kohorte, Tiers: Monat/Jahr, Bundles (Coaching, Familie)
• Zusätzliche Erlösquellen: B2B: Kassen-/Arbeitgeberlizenzen, Werbung nur als klar getrenntes Free-Erlebnis prüfen
• Retention der Zahler: Jahres-Churn: Engagement-Programm vor Renewal, Winback & Pausen-Angebote$T$,
  $J$[{"id": "h17-n1", "title": "Freemium-Architektur", "isPriority": true, "bulletPoints": [{"id": "h17-n1b1", "text": "Free/Premium-Grenze neu ziehen (Wert vs. Viralität)"}, {"id": "h17-n1b2", "text": "Conversion-Momente gezielt monetarisieren (Pläne)"}], "children": [{"id": "h17-n1c1", "title": "A/B-Roadmap statt Big-Bang-Paywall", "bulletPoints": [], "children": []}]}, {"id": "h17-n2", "title": "Preis & Pakete", "isPriority": false, "bulletPoints": [{"id": "h17-n2b1", "text": "Preistests je Markt/Kohorte"}, {"id": "h17-n2b2", "text": "Tiers: Monat/Jahr, Bundles (Coaching, Familie)"}], "children": []}, {"id": "h17-n3", "title": "Zusätzliche Erlösquellen", "isPriority": false, "bulletPoints": [{"id": "h17-n3b1", "text": "B2B: Kassen-/Arbeitgeberlizenzen"}, {"id": "h17-n3b2", "text": "Werbung nur als klar getrenntes Free-Erlebnis prüfen"}], "children": []}, {"id": "h17-n4", "title": "Retention der Zahler", "isPriority": false, "bulletPoints": [{"id": "h17-n4b1", "text": "Jahres-Churn: Engagement-Programm vor Renewal"}, {"id": "h17-n4b2", "text": "Winback & Pausen-Angebote"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie sieht das heutige Freemium aus?", "a": "Sehr großzügig: Tracking, Rezepte und Basis-Pläne sind gratis; Premium bietet Personalisierung und Detailauswertungen."}, {"q": "Was weiß man über die Zahler?", "a": "Sie konvertieren meist in den ersten Wochen, churnen aber nach Jahreszahlung stark; Conversion-Treiber sind Trainingspläne."}, {"q": "Wie reagieren Nutzer auf Paywall-Tests?", "a": "Ein kleiner Test mit härterer Paywall hob die Conversion, senkte aber Neuregistrierungen über Word-of-Mouth."}, {"q": "Ist Werbung eine Option?", "a": "Möglich, aber die Marke ist werbefrei positioniert; das Team fürchtet Nutzerverärgerung und Downloads-Verlust."}, {"q": "Gibt es B2B-Ideen?", "a": "Krankenkassen und Arbeitgeber haben Interesse an Firmenlizenzen signalisiert — bislang unbearbeitet."}]$J$::jsonb,
  $T$Freemium-Monetarisierung ist Architektur-Arbeit: Die Free-Grenze bestimmt Conversion UND Wachstum — Trade-off explizit machen. B2B ist die unterschätzte Erlösquelle, Zahler-Churn der stille Hebel.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'operations', $T$Dein Klient ist ein Hersteller von Elektro-Kleingeräten mit Fertigung in China und Vertrieb in Europa. Nach mehreren Lieferkrisen (Frachtraten, Lockdowns, Rotes Meer) fordert der Aufsichtsrat eine widerstandsfähigere Lieferkette — ohne die Kostenposition zu ruinieren. Strukturiere das Resilienz-Programm.$T$, NULL, $T$Operations / Supply Chain Framework$T$,
  $T$• Risiko-Transparenz: Kritikalitäts-Matrix: Produkte x Ausfallkosten, Single Points of Failure kartieren
• Sourcing-Strategie: Dual Sourcing für A-Produkte (China+1), Nearshoring selektiv (Türkei) für Reaktionsfähigkeit — Unteräste: TCO-Vergleich statt Stückkosten-Fixierung
• Puffer & Logistik: Differenzierte Sicherheitsbestände (A-Artikel), Frachtmix & Routen-Alternativen vertraglich sichern
• Steuerung & Frühwarnung: Szenario-Playbooks & Eskalationslogik, Resilienz-KPIs neben Kosten-KPIs$T$,
  $J$[{"id": "h18-n1", "title": "Risiko-Transparenz", "isPriority": false, "bulletPoints": [{"id": "h18-n1b1", "text": "Kritikalitäts-Matrix: Produkte x Ausfallkosten"}, {"id": "h18-n1b2", "text": "Single Points of Failure kartieren"}], "children": []}, {"id": "h18-n2", "title": "Sourcing-Strategie", "isPriority": true, "bulletPoints": [{"id": "h18-n2b1", "text": "Dual Sourcing für A-Produkte (China+1)"}, {"id": "h18-n2b2", "text": "Nearshoring selektiv (Türkei) für Reaktionsfähigkeit"}], "children": [{"id": "h18-n2c1", "title": "TCO-Vergleich statt Stückkosten-Fixierung", "bulletPoints": [], "children": []}]}, {"id": "h18-n3", "title": "Puffer & Logistik", "isPriority": false, "bulletPoints": [{"id": "h18-n3b1", "text": "Differenzierte Sicherheitsbestände (A-Artikel)"}, {"id": "h18-n3b2", "text": "Frachtmix & Routen-Alternativen vertraglich sichern"}], "children": []}, {"id": "h18-n4", "title": "Steuerung & Frühwarnung", "isPriority": false, "bulletPoints": [{"id": "h18-n4b1", "text": "Szenario-Playbooks & Eskalationslogik"}, {"id": "h18-n4b2", "text": "Resilienz-KPIs neben Kosten-KPIs"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie ist die Kette heute aufgebaut?", "a": "Zwei Vertragsfertiger in China, Seefracht nach Rotterdam, ein Zentrallager für Europa — kostenoptimal, aber ohne Redundanz."}, {"q": "Was haben die Krisen konkret gekostet?", "a": "Umsatzausfälle durch Out-of-Stock in Peak-Saisons und teure Luftfracht-Notfälle — zusammen ein mittlerer siebenstelliger Betrag in drei Jahren."}, {"q": "Welche Produkte sind kritisch?", "a": "Ein Drittel des Sortiments bringt 80% des Deckungsbeitrags — dort tut ein Ausfall richtig weh."}, {"q": "Welche Alternativen wurden geprüft?", "a": "Erste Gespräche mit Fertigern in Vietnam und der Türkei; Nearshoring wäre je Einheit teurer, aber schneller."}, {"q": "Welche Rolle spielt Bestandspolitik?", "a": "Bestände wurden aus Cash-Gründen minimiert — Sicherheitsbestände existieren faktisch nicht."}]$J$::jsonb,
  $T$Resilienz vs. Kosten: differenzieren statt pauschal — China+1 und Puffer nur für kritische A-Produkte, bewertet über TCO inkl. Ausfallkosten. Wer alles absichern will, hat den Trade-off nicht verstanden.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'operations', $T$Dein Klient ist eine Bank, deren Baufinanzierungs-Bearbeitung von Antrag bis Zusage im Schnitt 18 Arbeitstage dauert — Vermittler geben Kunden zunehmend an schnellere Wettbewerber (unter 5 Tagen). Der Vorstand will unter eine Woche kommen, ohne die Risikostandards zu senken. Strukturiere das Vorhaben.$T$, NULL, $T$Operations Framework (Service)$T$,
  $T$• Fall-Segmentierung: Fast Lane für Standardfälle (>50%), Komplexfälle mit Experten-Team — Unteräste: Automatisierte Vorprüfung & Dunkelverarbeitung
• Eingangsqualität: Verbindliche digitale Checklisten für Vermittler, Vollständigkeit als Annahme-Gate + Statusportal
• Prozess & Organisation: End-to-End-Teams statt Funktions-Silos, Liegezeiten & Warteschlangen steuern (Takt, WIP-Limits)
• Risiko & Steuerung: Standards unangetastet: Kompetenzen klar regeln, Durchlaufzeit-KPI je Segment & Vermittler-SLA$T$,
  $J$[{"id": "h19-n1", "title": "Fall-Segmentierung", "isPriority": true, "bulletPoints": [{"id": "h19-n1b1", "text": "Fast Lane für Standardfälle (>50%)"}, {"id": "h19-n1b2", "text": "Komplexfälle mit Experten-Team"}], "children": [{"id": "h19-n1c1", "title": "Automatisierte Vorprüfung & Dunkelverarbeitung", "bulletPoints": [], "children": []}]}, {"id": "h19-n2", "title": "Eingangsqualität", "isPriority": false, "bulletPoints": [{"id": "h19-n2b1", "text": "Verbindliche digitale Checklisten für Vermittler"}, {"id": "h19-n2b2", "text": "Vollständigkeit als Annahme-Gate + Statusportal"}], "children": []}, {"id": "h19-n3", "title": "Prozess & Organisation", "isPriority": false, "bulletPoints": [{"id": "h19-n3b1", "text": "End-to-End-Teams statt Funktions-Silos"}, {"id": "h19-n3b2", "text": "Liegezeiten & Warteschlangen steuern (Takt, WIP-Limits)"}], "children": []}, {"id": "h19-n4", "title": "Risiko & Steuerung", "isPriority": false, "bulletPoints": [{"id": "h19-n4b1", "text": "Standards unangetastet: Kompetenzen klar regeln"}, {"id": "h19-n4b2", "text": "Durchlaufzeit-KPI je Segment & Vermittler-SLA"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wo bleibt die Zeit liegen?", "a": "Vor allem in Liegezeiten: unvollständige Unterlagen, Rückfragen-Schleifen mit Vermittlern und Warteschlangen vor der Votierung — die reine Bearbeitungszeit ist kurz."}, {"q": "Wie kommen Anträge herein?", "a": "Zu einem großen Teil über Vermittlerplattformen, oft unvollständig; eine verbindliche Unterlagen-Checkliste fehlt."}, {"q": "Wie ist die Bearbeitung organisiert?", "a": "Funktional zerschnitten: Datenerfassung, Marktfolge, Votum, Beschlussfertigung — mit Übergaben und Medienbrüchen."}, {"q": "Was ist automatisierbar?", "a": "Haushaltsrechnung, Objektbewertung (bei Standardobjekten) und Unterlagenprüfung sind technisch weitgehend automatisierbar."}, {"q": "Welche Fälle sind Standard?", "a": "Gut die Hälfte: angestellte Kunden, Standardobjekt, klare Beleihung — der Rest ist komplex (Selbstständige, Sonderobjekte)."}]$J$::jsonb,
  $T$Durchlaufzeit-Case: Liegezeiten schlagen Bearbeitungszeit — Segmentierung (Fast Lane) plus Eingangsqualität sind die großen Hebel. 'Mehr Personal' wäre die falsche, 'Risikostandards lockern' die verbotene Antwort.$T$, true);

INSERT INTO public.framework_cases
  (difficulty, category, prompt, context_info, recommended_framework, reference_solution, reference_tree, clarifying_qa, interviewer_notes, active)
VALUES ('hard', 'operations', $T$Dein Klient ist ein Anbieter von Paketstationen, der sein Netz in drei Jahren von 2.000 auf 10.000 Automaten ausbauen will. Schon heute hakt es: Aufbau-Rückstände, Vandalismus-Ausfälle und unrentable Standorte. Der COO fragt: Wie skalieren wir das Netz profitabel?$T$, NULL, $T$Operations / Netzwerk Framework$T$,
  $T$• Standort-Strategie: Datenbasiertes Scoring (Dichte, Frequenz, Carrier), Bestands-Triage: Underperformer versetzen/kündigen — Unteräste: Partner-Pipelines priorisieren statt Opportunismus
• Rollout-Maschine: Standardisierte Aufbau-Kits & Genehmigungs-Playbooks, Montagekapazität skalieren (Partnerfirmen, Takt)
• Betrieb & Verfügbarkeit: Predictive Maintenance & Ersatzteil-Logistik, Vandalismus: Härtung, Standortwahl, Versicherung
• Ökonomie & Verträge: Unit Economics je Automat als Steuerungsgröße, Carrier-Verträge: Verfügbarkeits-Anreize$T$,
  $J$[{"id": "h20-n1", "title": "Standort-Strategie", "isPriority": true, "bulletPoints": [{"id": "h20-n1b1", "text": "Datenbasiertes Scoring (Dichte, Frequenz, Carrier)"}, {"id": "h20-n1b2", "text": "Bestands-Triage: Underperformer versetzen/kündigen"}], "children": [{"id": "h20-n1c1", "title": "Partner-Pipelines priorisieren statt Opportunismus", "bulletPoints": [], "children": []}]}, {"id": "h20-n2", "title": "Rollout-Maschine", "isPriority": false, "bulletPoints": [{"id": "h20-n2b1", "text": "Standardisierte Aufbau-Kits & Genehmigungs-Playbooks"}, {"id": "h20-n2b2", "text": "Montagekapazität skalieren (Partnerfirmen, Takt)"}], "children": []}, {"id": "h20-n3", "title": "Betrieb & Verfügbarkeit", "isPriority": false, "bulletPoints": [{"id": "h20-n3b1", "text": "Predictive Maintenance & Ersatzteil-Logistik"}, {"id": "h20-n3b2", "text": "Vandalismus: Härtung, Standortwahl, Versicherung"}], "children": []}, {"id": "h20-n4", "title": "Ökonomie & Verträge", "isPriority": false, "bulletPoints": [{"id": "h20-n4b1", "text": "Unit Economics je Automat als Steuerungsgröße"}, {"id": "h20-n4b2", "text": "Carrier-Verträge: Verfügbarkeits-Anreize"}], "children": []}]$J$::jsonb,
  $J$[{"q": "Wie werden Standorte heute ausgewählt?", "a": "Opportunistisch — wo Partner (Supermärkte, Wohnungswirtschaft) Flächen anbieten; eine datenbasierte Standortbewertung fehlt."}, {"q": "Was macht einen Standort rentabel?", "a": "Paketvolumen pro Automat — getrieben von Wohndichte, Carrier-Anbindung und Sichtbarkeit; ein Fünftel der Standorte liegt weit unter Plan."}, {"q": "Woran hakt der Aufbau?", "a": "Genehmigungen, Stromanschlüsse und knappe Montagetrupps — die Pipeline ist voll, aber der Durchsatz niedrig."}, {"q": "Wie schlimm sind die Ausfälle?", "a": "Vandalismus und Technikdefekte legen Automaten teils wochenlang lahm — Ersatzteile und Techniker sind der Engpass."}, {"q": "Wie ist das Verhältnis zu den Carriern?", "a": "Mehrere Carrier nutzen das Netz; die Verträge honorieren Volumen, nicht Verfügbarkeit."}]$J$::jsonb,
  $T$Skalierung = Wiederholbarkeit: Standort-Scoring und eine industrialisierte Rollout-Maschine sind der Kern; Betrieb (Verfügbarkeit) entscheidet über die Ökonomie. Wer nur 'schneller bauen' sagt, skaliert die Probleme mit.$T$, true);

COMMIT;
